type AccordionIndicatorRenderProps = IconRenderProps & {
    readonly expanded: boolean;
};

interface AccordionItem<T extends string> {
    readonly value: T;
    readonly title: string;
    readonly description?: string | undefined;
    readonly content: NonNullable<ReactNode>;
    readonly leading?: ReactNode | undefined;
    /**
     * Presentation-only decoration at the end of the header row, before the
     * expansion indicator — a count badge, for example. It renders inside the
     * trigger but is hidden from accessibility, so the trigger's accessible name
     * stays the title. Interactive trailing content is unsupported; when the
     * information matters to assistive technology, repeat it in `description`.
     */
    readonly trailing?: ReactNode | undefined;
    readonly disabled?: boolean | undefined;
}

type AccordionProps<T extends string> = AccordionBaseProps<T> & ({
    type?: 'single' | undefined;
    value: NoInfer<T> | null;
    onValueChange: (value: T | null) => void;
    /** When false, the last open item cannot be closed. Defaults to true. */
    collapsible?: boolean | undefined;
} | {
    type: 'multiple';
    value: ReadonlyArray<NoInfer<T>>;
    onValueChange: (value: readonly T[]) => void;
    collapsible?: never;
});

type ActionChipProps = ChipBaseProps & {
    kind: 'action';
    onPress: () => void;
    selected?: never;
    onSelectedChange?: never;
    onRemove?: never;
    removeAccessibilityLabel?: never;
};

type ActionLinkProps = LinkBaseProps & {
    onPress: () => void;
    href?: never;
    target?: never;
    rel?: never;
    onOpenError?: never;
};

type ActionSheetDismissDetails<T extends string> = DialogDismissDetails | (ActionSheetDetailBase & {
    readonly reason: 'cancel-action';
}) | (ActionSheetDetailBase & {
    readonly reason: 'action-select';
    readonly value: T;
});

interface ActionSheetItem<T extends string> {
    readonly value: T;
    readonly label: string;
    readonly description?: string | undefined;
    readonly accessibilityLabel?: string | undefined;
    readonly destructive?: boolean | undefined;
    readonly disabled?: boolean | undefined;
    readonly testID?: string | undefined;
}

interface ActionSheetProps<T extends string> extends Omit<CommonProps, 'unstyled'> {
    visible: boolean;
    title: string;
    description?: string | undefined;
    /** Dynamic arrays may be empty; the safe cancel action still renders. */
    items: readonly ActionSheetItem<T>[];
    onDismiss: (details: ActionSheetDismissDetails<NoInfer<T>>) => void;
    /** Defaults to strings.cancel. */
    cancelLabel?: string | undefined;
    presentation?: ActionSheetPresentation | undefined;
    animationType?: NonNullable<ModalProps['animationType']> | undefined;
    dismissOnBackdrop?: boolean | undefined;
    dismissDisabled?: boolean | undefined;
    /** Blocks every action and dismissal during an async transition and exposes the busy state. */
    busy?: boolean | undefined;
    bottomInset?: number | undefined;
    keyboardOverlap?: number | undefined;
    accessibilityLabel?: string | undefined;
    finalFocusRef?: DialogFocusRef | undefined;
    overlayId?: string | undefined;
    unstyled?: never;
}

/**
 * Adds whole days (negative to subtract), crossing month and year boundaries
 * exactly. The result must stay inside the year range 1–9999.
 */
declare function addCalendarDays(date: CalendarDate, amount: number): CalendarDate;

/** Either a title or non-empty children must be present. */
type AlertProps = AlertOwnProps & ({
    title: string;
    children?: ReactNode | undefined;
} | {
    title?: never;
    children: NonNullable<ReactNode>;
});

/** AspectRatio — pins the ratio of a media slot through a platform-shared View style. */
interface AspectRatioProps extends Omit<CommonProps, 'unstyled'> {
    /** width / height. Only finite numbers greater than 0 are allowed. */
    ratio: number;
    /** It can be omitted, but if you pass it, it has to be a node — not null or undefined. */
    children?: NonNullable<ReactNode>;
    unstyled?: never;
}

interface BadgeProps extends Omit<CommonProps, 'unstyled'> {
    label: string;
    /**
     * Overrides the accessible name derived from the visible label — for example
     * "Paid (PAID)" while the visible label stays localized. When present, the
     * badge is exposed as one accessibility element carrying this name: native
     * flattens the accessible root, and the web root takes `role="img"` with the
     * label hidden from assistive technology, because ARIA prohibits naming a
     * role-less generic element.
     */
    accessibilityLabel?: string | undefined;
    /** Defaults to 'neutral'. */
    variant?: StatusVariant | undefined;
    /** Defaults to 'md'. */
    size?: BadgeSize | undefined;
    /** A static node, or an icon render function that receives color and size. */
    leading?: ReactNode | RenderIcon | undefined;
    labelStyle?: StyleProp<TextStyle> | undefined;
    labelClassName?: string | undefined;
    unstyled?: never;
}

/** Renamed from 'dark' to 'inverse' — resolves the inverted meaning of a "dark" variant getting lighter in the dark theme (§5.2). */
type ButtonVariant = 'primary' | 'primary-outline' | 'secondary'
/** A transparent action that uses the ordinary text color. */
 | 'ghost' | 'destructive' | 'destructive-outline' | 'inverse';

/**
 * Pure calendar-date math — the foundation of MonthCalendar and DateField.
 *
 * This module is deliberately clock-free and time-zone-free: nothing here reads
 * the current time, and the JavaScript Date object appears in no signature.
 * A CalendarDate is a plain civil date in the proleptic Gregorian calendar;
 * which instant it corresponds to (and in which time zone "today" falls) is the
 * application's decision. Like src/theme, this folder imports neither react nor
 * react-native, so Node scripts can load the math safely.
 */
/**
 * A plain civil calendar date. `month` is 1–12 and `day` is 1–31; `year` is a
 * four-digit-key year (1–9999). Deliberately not a Date: a CalendarDate names a
 * day, not an instant, so no time zone can silently shift it.
 */
interface CalendarDate {
    readonly year: number;
    /** 1–12. */
    readonly month: number;
    /** 1–31, at most the length of the month. */
    readonly day: number;
}

/** A year–month pair naming one displayed calendar month. `month` is 1–12. */
interface CalendarMonth {
    readonly year: number;
    /** 1–12. */
    readonly month: number;
}

/**
 * Clamps a date into the inclusive [min, max] range. Either bound may be
 * omitted. Returns the input object itself when it is already in range.
 */
declare function clampCalendarDate(date: CalendarDate, min?: CalendarDate, max?: CalendarDate): CalendarDate;

type CollapsibleProps = CommonProps & {
    title: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    children: NonNullable<ReactNode>;
    disabled?: boolean | undefined;
    variant?: CollapsibleVariant | undefined;
    /** Web heading level. Defaults to 3. */
    headingLevel?: 1 | 2 | 3 | 4 | 5 | 6 | undefined;
    triggerStyle?: StyleProp<ViewStyle> | undefined;
    contentStyle?: StyleProp<ViewStyle> | undefined;
    accessibilityLabel?: string | undefined;
};

interface ComboboxFilterDetails {
    readonly normalizedQuery: string;
    readonly tokens: readonly string[];
    readonly locale?: string | readonly string[] | undefined;
}

interface ComboboxInputValueChangeDetails<T extends string> {
    readonly reason: ComboboxInputValueChangeReason;
    readonly previousInputValue: string;
    readonly isComposing: boolean;
    readonly item?: ComboboxItem<T> | undefined;
    readonly originalEvent?: unknown;
}

interface ComboboxItem<T extends string> {
    readonly value: T;
    readonly label: string;
    readonly textValue?: string | undefined;
    readonly keywords?: readonly string[] | undefined;
    readonly description?: string | undefined;
    readonly leading?: ReactNode | RenderIcon | undefined;
    readonly trailing?: ReactNode | RenderIcon | undefined;
    readonly disabled?: boolean | undefined;
