}

type ComboboxState<T extends string> = {
    readonly status: "ready";
    readonly items: readonly ComboboxItem<T>[];
    readonly statusLabel?: string | undefined;
    readonly onRetry?: never;
} | {
    readonly status: "loading";
    /** Retained results remain available while a newer query is loading. */
    readonly items: readonly ComboboxItem<T>[];
    readonly statusLabel?: string | undefined;
    readonly onRetry?: never;
} | {
    readonly status: "error";
    /** Localized, visible error copy. */
    readonly statusLabel: string;
    readonly items: readonly ComboboxItem<T>[];
    readonly onRetry?: (() => void) | undefined;
};

interface ConfirmActionRowProps extends Omit<CommonProps, 'unstyled'> {
    onCancel: () => void;
    onConfirm: () => void;
    /** Defaults to strings.cancel. */
    cancelLabel?: string | undefined;
    /** Defaults to strings.confirm. */
    confirmLabel?: string | undefined;
    /** Defaults to 'secondary'. */
    cancelVariant?: ButtonVariant | undefined;
    /** Defaults to 'primary', or to 'destructive' when destructive is true. */
    confirmVariant?: ButtonVariant | undefined;
    destructive?: boolean | undefined;
    /** Confirm is loading — cancel is disabled automatically. */
    loading?: boolean | undefined;
    cancelLoading?: boolean | undefined;
    cancelTestID?: string | undefined;
    confirmTestID?: string | undefined;
    /** Per-button container style, layered after the built-in flex sizing. */
    cancelStyle?: StyleProp<ViewStyle> | undefined;
    confirmStyle?: StyleProp<ViewStyle> | undefined;
    cancelLabelStyle?: StyleProp<TextStyle> | undefined;
    confirmLabelStyle?: StyleProp<TextStyle> | undefined;
    unstyled?: never;
}

/**
 * A controlled confirmation modal with one safe cancellation route and one
 * affirmative action. Use Dialog directly when the footer or modal body needs
 * richer composition.
 */
declare function ConfirmDialog({ visible, title, description, onConfirm, onDismiss, cancelLabel, confirmLabel, confirmVariant, confirmDisabled, loading, dismissOnBackdrop, animationType, finalFocusRef, overlayId: overlayIdProp, cancelTestID, confirmTestID, style, className, testID, }: ConfirmDialogProps): ReactElement;

/** Dialog dismissal plus the explicit safe cancel action. */
type ConfirmDialogDismissDetails = DialogDismissDetails | (Omit<DialogDismissDetails, 'reason'> & {
    readonly reason: 'cancel-action';
});

interface ConfirmDialogProps extends Omit<CommonProps, 'unstyled'> {
    /** The caller owns visibility; this component only requests dismissal. */
    visible: boolean;
    /** The visible title also names the underlying modal. */
    title: string;
    description?: string | undefined;
    /** Runs the affirmative action. It never closes the dialog automatically. */
    onConfirm: () => void;
    /** Receives every user-initiated close request, including the cancel action. */
    onDismiss: (details: ConfirmDialogDismissDetails) => void;
    /** Defaults to strings.cancel. */
    cancelLabel?: string | undefined;
    /** Defaults to strings.confirm. */
    confirmLabel?: string | undefined;
    /** Defaults to primary. The narrow set keeps the affirmative action semantic. */
    confirmVariant?: Extract<ButtonVariant, 'primary' | 'destructive'> | undefined;
    /** Disables only the affirmative action; cancel and ordinary dismissal stay available. */
    confirmDisabled?: boolean | undefined;
    /** Blocks every action and dismissal while the caller's confirmation work is pending. */
    loading?: boolean | undefined;
    /** Defaults to true. It affects only backdrop presses, like Dialog. */
    dismissOnBackdrop?: boolean | undefined;
    /**
     * Passed through to Dialog. Defaults to Dialog's 'fade'; Dialog animates
     * only once the platform has affirmatively reported that reduced motion is
     * off, and presents with 'none' otherwise (unresolved or reduced).
     */
    animationType?: NonNullable<ModalProps['animationType']> | undefined;
    /** Best-effort focus restoration after the modal exits. */
    finalFocusRef?: DialogFocusRef | undefined;
    overlayId?: string | undefined;
    /** testID of the cancel button. Defaults to `${testID}-cancel`. */
    cancelTestID?: string | undefined;
    /** testID of the confirm button. Defaults to `${testID}-confirm`. */
    confirmTestID?: string | undefined;
    unstyled?: never;
}

interface ContentFrameProps extends Omit<CommonProps, 'unstyled'> {
    children?: ReactNode | undefined;
    /** Defaults to 1040 — inherited from the predecessor. */
    maxWidth?: number | undefined;
    /** Defaults to 'xl'. */
    padding?: SpacingKey | number | undefined;
    topPadding?: SpacingKey | number | undefined;
    bottomPadding?: SpacingKey | number | undefined;
    center?: boolean | undefined;
    unstyled?: never;
}

/**
 * "Brand colors for both schemes at once" — builds a pair by merging shared
 * overrides first, then per-scheme ones. Overriding only light leaves dark on the
 * default dark palette; nothing is derived automatically, by explicit principle.
 */
declare function createThemes(input?: {
    readonly shared?: ThemeOverrides | undefined;
    readonly light?: ThemeOverrides | undefined;
    readonly dark?: ThemeOverrides | undefined;
}): ThemePair;

declare function DataTable<Row, RowKey extends DataTableRowKey, const Columns extends readonly {
    readonly id: string;
}[]>(props: DataTableComponentProps<Row, RowKey, Columns>): ReactElement;

interface DataTableCellContext<Row, RowKey extends DataTableRowKey, ColumnId extends string> extends DataTableValueContext<Row, RowKey, ColumnId> {
    /** Nonblank scalar returned by getTextValue. */
    readonly textValue: string;
    readonly presentation: "table";
}

type DataTableColumn<Row, ColumnId extends string, RowKey extends DataTableRowKey = DataTableRowKey> = DataTableColumnLayout & DataTableSortableColumn & {
    readonly id: ColumnId;
    /** Visible, nonblank column title and the default control name. */
    readonly header: string;
    /**
     * Localized scalar used by native accessibility and compact renderers.
     * Rich visual cells can still be returned by renderCell.
     */
    readonly getTextValue: (context: DataTableValueContext<Row, RowKey, ColumnId>) => string;
    readonly renderCell?: (context: DataTableCellContext<Row, RowKey, ColumnId>) => ReactElement;
    readonly align?: DataTableAlignment | undefined;
    readonly minWidth?: number | undefined;
    readonly maxWidth?: number | undefined;
    readonly headerStyle?: StyleProp<ViewStyle> | undefined;
    readonly headerClassName?: string | undefined;
    readonly headerTextStyle?: StyleProp<TextStyle> | undefined;
    readonly headerTextClassName?: string | undefined;
    readonly cellStyle?: StyleProp<ViewStyle> | undefined;
    readonly cellClassName?: string | undefined;
    readonly cellTextStyle?: StyleProp<TextStyle> | undefined;
    readonly cellTextClassName?: string | undefined;
};

type DataTableColumnId<Columns extends readonly {
    readonly id: string;
}[]> = Extract<Columns[number]["id"], string>;

/**
 * JSX call contract. Literal column tuples narrow sort.columnId to only columns
 * marked `sortable: true`; widened column arrays retain the explicit
 * DataTableProps controlled-pair union.
 */
type DataTableComponentProps<Row, RowKey extends DataTableRowKey, Columns extends readonly {
    readonly id: string;
}[]> = DistributiveDataTableOmit<DataTableProps<Row, DataTableColumnId<Columns>, RowKey>, "columns" | "sort" | "onSortChange"> & {
    readonly columns: Columns & readonly DataTableColumn<Row, DataTableColumnId<Columns>, RowKey>[];
} & InferredDataTableSorting<Columns>;

interface DataTableListCell<ColumnId extends string> {
    readonly columnId: ColumnId;
    readonly header: string;
    readonly textValue: string;
    readonly align: DataTableAlignment;
}

interface DataTableListRowContext<Row, RowKey extends DataTableRowKey, ColumnId extends string> {
    readonly row: Row;
    readonly rowKey: RowKey;
    readonly rowIndex: number;
    readonly cells: readonly DataTableListCell<ColumnId>[];
    readonly selected: boolean;
    readonly selectionDisabled: boolean;
    readonly presentation: "list";
}

/**
 * DataTable public contracts.
 *
 * DataTable is a bounded, presentational data table rather than a spreadsheet
 * widget. The application owns ordering, filtering, pagination, and fetching;
 * this package owns semantics, responsive presentation, and controlled UI
 * notifications. A future DataGrid may add composite arrow-key navigation and
 * virtualization without changing this static-table contract.
 */
type DataTableRowKey = string | number;

interface DataTableRowPressContext<RowKey extends DataTableRowKey> {
    readonly rowKey: RowKey;
    readonly rowIndex: number;
    /** "table" for the semantic web table and the native visual table; "list" for compact presentations. */
    readonly presentation: "table" | "list";
    readonly originalEvent?: unknown;
}

interface DataTableRowStyleContext<RowKey extends DataTableRowKey> {
    readonly rowKey: RowKey;
    readonly rowIndex: number;
    /** True when this row's key equals activeRow.key. */
    readonly active: boolean;
    /** "table" for the semantic web table and the native visual table; "list" for compact presentations. */
    readonly presentation: "table" | "list";
}

interface DataTableSelection<Row, RowKey extends DataTableRowKey> {
    /** Include-only controlled model. Off-page keys are preserved by page toggles. */
    readonly selectedRowKeys: readonly NoInfer<RowKey>[];
    readonly onSelectionChange: (selectedRowKeys: readonly RowKey[], details: DataTableSelectionChangeDetails<RowKey>) => void;
    readonly getRowSelectionAccessibilityLabel: (context: DataTableSelectionRowContext<Row, RowKey>) => string;
    readonly isRowSelectionDisabled?: (context: DataTableSelectionRowContext<Row, RowKey>) => boolean;
    /** Defaults to true. It always means the currently supplied visible rows. */
    readonly showSelectAll?: boolean | undefined;
    readonly selectAllAccessibilityLabel?: string | undefined;
    readonly clearSelectionAccessibilityLabel?: string | undefined;
}

type DataTableSelectionChangeDetails<RowKey extends DataTableRowKey> = {
    readonly reason: "row-toggle";
    readonly scope: "visible";
    readonly rowKey: RowKey;
    readonly selected: boolean;
    readonly originalEvent?: unknown;
} | {
    readonly reason: "page-toggle";
    readonly scope: "visible";
    /** Visible, enabled keys whose selected boolean actually changed. */
    readonly affectedRowKeys: readonly RowKey[];
    readonly selected: boolean;
    readonly originalEvent?: unknown;
};

interface DataTableSelectionRowContext<Row, RowKey extends DataTableRowKey> {
    readonly row: Row;
    readonly rowKey: RowKey;
    readonly rowIndex: number;
}

interface DataTableSort<ColumnId extends string> {
    readonly columnId: ColumnId;
    readonly direction: DataTableSortDirection;
}

type DataTableSortableColumnId<Columns extends readonly {
    readonly id: string;
}[]> = Extract<Extract<Columns[number], {
    readonly sortable: true;
}>["id"], string>;

interface DataTableSortChangeDetails<ColumnId extends string> {
    readonly reason: "column-header-press";
    readonly columnId: ColumnId;
    readonly previous: DataTableSort<ColumnId> | null;
    readonly originalEvent?: unknown;
}

type DataTableState<Row> = {
