};

/**
 * 촬영 시각(ms 에폭) → ISO 문자열. 전신 `deviceAssetCapturedAt`(devicePhotoLibrary.ts:372-378).
 *
 * peer 0인 순수 함수이므로 `"./device"`가 아니라 `"./core"`에 둔다(§5.7.5).
 * ⚠ `creationTime`이 0이면 null이다 — 전신의 falsy 판정을 그대로 보존한다. 에폭 0(1970-01-01)은
 *   기기가 시각을 모른다는 뜻이지 실제 촬영 시각이 아니며, 이것을 ISO로 흘리면 서버의
 *   타임라인 정렬이 1970년으로 끌려간다.
 */
declare function deviceAssetCapturedAt(asset: {
    readonly creationTime?: number | undefined;
}): string | null;

type DeviceAssetInfo = {
    /** 앱 컨테이너 밖(iOS Photos 컨테이너)일 수 있다 — core가 캐시로 실체화한다(§7 하드닝 2). */
    readonly localUri?: string | undefined;
    readonly uri?: string | undefined;
    readonly exif?: Readonly<Record<string, unknown>> | undefined;
    /** true면 원본이 iCloud에만 있다. core 기본 정책은 여기서 중단(§7 하드닝 6). */
    readonly isNetworkAsset: boolean;
};

type DeviceAssetPage = {
    readonly assets: readonly DeviceAsset[];
    /**
     * §1-7 규약(`?: T | undefined`)을 따른다 — 초안은 필수-undefined였다(G20-14).
     * 필수로 두면 3자 어댑터 구현자가 값 없는 마지막 페이지에서도 키를 명시해야 한다.
     */
    readonly endCursor?: string | undefined;
    readonly hasNextPage: boolean;
    readonly totalCount: number;
};

/**
 * 하드닝된 업로드 resolve가 필요로 하는 최소 정체성. 전체 `MediaLibrary.Asset`이 이것을
 * 구조적으로 만족하며, 동기화 큐는 이 두 필드만 저장해 두고 넘길 수 있다
 * (전신 devicePhotoLibrary.ts:21-24 주석 계승).
 */
type DeviceAssetRef = {
    readonly id: string;
    readonly filename: string;
};

/** `DeviceLibrary` + `DeviceUploads`를 한 객체로 — staging·files는 `MediaKit`이 공급한다(§5.5). */
interface DeviceKit<TAsset, TCollectionId extends string = string> extends DeviceLibrary, DeviceUploads<TAsset, TCollectionId> {
}

interface DeviceLibrary {
    /** 순수 조회. 요청하지 않는다. */
    getPermission(): Promise<MediaPermission>;
    /**
     * 권한 합성 규칙의 **유일한 거처**(§5.4-④(c), G17):
     * 조회 → `!granted && canAskAgain`일 때만 요청 → `accessPrivileges === 'limited'` 매핑
     * (마지막 매핑은 어댑터 몫 — §3.3).
     *
     * ⚠ raw `requestPermission()`은 **공개하지 않는다**. `canAskAgain`을 무시하는 재요청이
     * 정확히 iOS UI 데드록(재요청해도 아무 일도 일어나지 않아 화면이 영원히 기다린다)의 원인이며,
     * 골든패스에 그 문을 두면 반드시 누군가 그 문으로 들어간다. 필요한 소비자는
     * `DeviceLibraryAdapter.requestPermission()`을 직접 쓴다.
     */
    ensurePermission(): Promise<MediaPermission>;
    fetchPage(input?: {
        readonly albumId?: string | null | undefined;
        readonly after?: string | undefined;
        readonly pageSize?: number | undefined;
        readonly kinds?: readonly MediaKind[] | undefined;
    } | undefined): Promise<DeviceAssetPage>;
    /** ⚠ core가 `count > 0` 필터 + count 내림차순 정렬을 **수행한다**(§5.4-④(d)). */
    fetchAlbums(): Promise<readonly DeviceAlbum[]>;
    /**
     * 하드닝된 자산정보 조회 — 그리드/스캐너/업로드가 공유하는 단일 관문(§5.7.5, G9 승격).
     * 기본값은 iCloud 다운로드 없음 + 15s 데드라인, 옵트인 시 60s(§7 하드닝 6).
     * 데드라인 초과는 `MediaError('device-timeout')`이며, 어댑터 실패는 URL·원본 예외를
     * 신뢰하지 않고 새 `MediaError('device-library-failed')`로 정규화한다.
     *
     * ⚠ 이 메서드를 공개하지 않으면 동기화 스캐너가 자체 조회를 짜게 되고, 그 순간 15초 데드라인과
     * `downloadFromNetwork: false` 기본값이 **스캔 경로에서만** 사라진다 — 하드닝 6의 조용한 절반 소멸.
     */
    getAssetInfo(assetId: string, options?: {
        readonly downloadFromICloud?: boolean | undefined;
        readonly infoTimeoutMs?: number | undefined;
        readonly downloadTimeoutMs?: number | undefined;
    } | undefined): Promise<DeviceAssetInfo>;
    /**
     * 원본 바이트 위치만 필요한 경로(동기화 엔진)용. 전신 `resolveDeviceAssetSourceForUpload`.
     * iCloud 가드 · 이중 타임아웃 · iOS 캐시 실체화(§7 하드닝 2·6).
     */
    resolveForUpload(asset: DeviceAssetRef, options?: DeviceResolveOptions | undefined): Promise<ResolvedDeviceAsset>;
    /**
     * 화면 경로용. 전신 `resolveDeviceAssetForUpload`(G4).
     *
     * ⚠ 후보 목록에 `asset.uri`를 **자동으로 덧붙인다**(전신 devicePhotoLibrary.ts:355-359).
     *   최종 순서: `[info.localUri, info.uri, asset.uri, ...options.extraCandidates]`
     *   이 자동 후보가 §7.1 「정보 조회 실패 시 폴백 후보 생존」 규칙을 실제로 발화시키는 값이다 —
     *   전신 주석 "the picker keeps the original asset.uri"(286-288)가 가리키는 정확한 경로다.
     *   저장된 `asset.uri`는 업로드 파이프라인이 읽을 수 없는 `ph://` 참조일 수 있으므로 원본
     *   바이트와 EXIF를 다시 해석한 뒤 피커 형태로 넘긴다(전신 341-343 주석).
     */
    resolvePickedAsset(asset: DeviceAsset, options?: DeviceResolveOptions | undefined): Promise<ResolvedPickedAsset>;
}

interface DeviceLibraryAdapter {
    /**
     * ⚠ Android 13+에서 granular 목록(`['photo','video']`)을 **반드시** 지정할 것. 생략하면
     * 매니페스트의 모든 권한이 대상이 되어, 거부된 `READ_MEDIA_AUDIO`가 유효한 사진·동영상 허용을
     * 거부처럼 보이게 만든다(Android의 "선택한 사진" 접근 모드 포함) — §7 하드닝 5.
     *
     * ⚠ **순수 위임이다.** "언제 요청할 것인가"(현재 권한 조회 → `!granted && canAskAgain`일 때만
     * 요청)는 어댑터가 아니라 core가 소유한다 — `DeviceLibrary.ensurePermission()`(§5.4-④(c), G17).
     * 어댑터에 두면 (i) 3자 어댑터마다 규칙이 갈리고, (ii) iOS에서 `canAskAgain=false`인데 재요청해
     * 아무 일도 일어나지 않는 **UI 데드록**이 재발한다.
     * 어댑터의 몫은 네이티브 응답을 `MediaPermission`으로 매핑하는 것까지다
     * (`accessPrivileges === 'limited'` → `limited: true` 포함).
     */
    requestPermission(): Promise<MediaPermission>;
    /** 순수 조회 — 요청하지 않는다. 합성 규칙은 core가 갖는다(위 참조). */
    getPermission(): Promise<MediaPermission>;
    /**
     * ⚠ **정렬 계약: creationTime 내림차순(최신 우선).** 전신 `devicePhotoLibrary.ts:220`
     *   `sortBy: [[SortBy.creationTime, false]]`.
     * core는 재정렬하지 않는다 — 페이지 단위 재정렬은 전역 순서를 보장하지 못하면서
     * (다음 페이지가 이전 페이지보다 최신일 수 있다) `endCursor`는 여전히 어댑터 순서를 따라가
     * **커서와 표시 순서가 어긋난다**(§5.4-④(d)). 이 계약을 어기면 그리드 순서와 무한스크롤
     * 커서가 함께 깨지며, **타입도 가드도 그것을 잡지 못한다**.
     *
     * ⚠ 자산별 `getAssetInfo` 호출 금지 — 60개 원본을 직렬 해석하면 페이지당 ~20초다.
     * 그리드는 raw uri(iOS `ph://`)를 그대로 그린다. 네이티브 이미지 로더가 PHImageManager에
     * 뷰 크기 썸네일을 요청하므로 시스템 사진 그리드와 같은 방식이 된다. 원본 바이트는
     * 업로드 시점의 resolve에서만 해석한다(§7.1).
     */
    listAssets(input: {
        readonly albumId?: string | null | undefined;
        readonly after?: string | undefined;
        readonly pageSize: number;
        readonly kinds: readonly MediaKind[];
    }): Promise<DeviceAssetPage>;
    /**
     * 원본 목록을 **그대로** 반환한다 — 필터·정렬 금지.
     * `count > 0` 필터와 count 내림차순 정렬은 core가 수행하므로
     * (전신 `devicePhotoLibrary.ts:243-250`의 정책을 core로 승격) 어댑터가 중복 수행할 이유가 없다.
     * 전량을 한 번에 반환하는 in-memory 목록이라 core가 전역 순서를 보장할 수 있다는 점이
     * `listAssets`와의 차이다(§5.4-④(d)).
     */
    listAlbums(): Promise<readonly DeviceAlbum[]>;
    /**
     * ⚠ `downloadFromNetwork`는 **필수 인자**다(§6.1-④). 옵셔널로 두면 어댑터 구현자가
     * 플랫폼 기본값(Expo legacy API는 `true`)을 흘려 iCloud 원본을 무단으로 셀룰러 다운로드한다 —
     * 전신이 실제로 겪은 사고다.
     * 타임아웃(15s / 60s)도 core가 건다 — 어댑터는 순수 위임(§7 하드닝 6).
     */
    getAssetInfo(assetId: string, input: {
        readonly downloadFromNetwork: boolean;
    }): Promise<DeviceAssetInfo>;
}

/**
 * 기기 자산 해석 옵션(§5.4-④).
 *
 * ⚠ `downloadFromICloud` 기본 false — 전신 주석(devicePhotoLibrary.ts:48-50) 그대로다:
 * "사용자가 직접 시작한 수동 업로드만 iCloud 전용 원본 가져오기에 옵트인할 수 있다.
 *  백그라운드 동기화는 예기치 않은 셀룰러 전송을 절대 시작하지 않도록 기본값 false를 유지한다."
 */
type DeviceResolveOptions = {
    readonly downloadFromICloud?: boolean | undefined;
    readonly onICloudDownload?: ((downloading: boolean) => void) | undefined;
    readonly extraCandidates?: readonly (string | null | undefined)[] | undefined;
    readonly infoTimeoutMs?: number | undefined;
    readonly downloadTimeoutMs?: number | undefined;
};

interface DeviceUploads<TAsset, TCollectionId extends string = string> {
    /**
     * ⚠ 순차 실행 고정(위 참조). 업로드 성공·실패와 무관하게 finally에서 `staging.cleanup`을 호출한다 —
     * 누락하면 업로드한 **모든** 사진의 원본 사본이 앱 컨테이너에 영구 축적된다(§7 하드닝 7).
     */
    uploadDeviceAssets(assets: readonly DeviceAssetRef[], options?: (DeviceResolveOptions & {
        readonly collectionId?: TCollectionId | null | undefined;
        readonly max?: number | undefined;
    }) | undefined): Promise<readonly UploadResult<TAsset>[]>;
}

type DurableFile = {
    readonly uri: string;
    readonly sizeBytes: number;
};

/** A URI-safe error emitted by durable attachment storage. */
declare class DurableFileError extends Error {
    readonly code: DurableFileErrorCode;
    constructor(code: DurableFileErrorCode);
}

interface DurableFileStore {
    /** True only for a safe, non-empty file path rooted in this store. */
    owns(uri: string | null | undefined): boolean;
    /** Atomically-enough copy: a failed, empty, or size-mismatched destination is removed before rejection. */
    copy(input: DurableFileStoreCopyInput): Promise<DurableFile>;
    /** Copy a picker result while retaining a supported, validated media extension. */
    copyPickedAsset(input: DurablePickedAssetCopyInput): Promise<DurablePickedAssetFile>;
    /** Best-effort no-op for paths outside this store. */
    remove(uri: string | null | undefined): Promise<void>;
}

/**
 * App-owned persistent-file storage seam.
 *
 * This is deliberately separate from `FileSystemAdapter`: upload code needs a
 * cache directory plus base64 reads, whereas an application attachment store
 * needs a durable root plus directory creation. Keeping the contracts apart
 * avoids making every upload-only adapter pretend it can persist user files.
 */
interface DurableFileStoreAdapter {
    /** App-owned durable root URI. It must identify a directory, or return null when unavailable. */
    rootDirectory(): string | null;
    /** Creates a directory and all missing parents. Repeating the call must be safe. */
    ensureDirectory(uri: string): Promise<void>;
    /** Same discriminated stat contract as the upload file-system seam. */
    stat(uri: string): Promise<FileStat>;
    copy(input: {
        readonly from: string;
        readonly to: string;
    }): Promise<void>;
    /** Idempotent best-effort removal. */
    remove(uri: string): Promise<void>;
}

type DurableFileStoreCopyInput = {
    readonly sourceUri: string;
    /** Nested folders below the configured root. Every segment is validated independently. */
    readonly directory?: readonly string[] | undefined;
    /** The final file name, including any extension the host chose. */
    readonly fileName: string;
};

/**
 * Copy a picker result with a caller-owned stable filename stem.
 *
 * The source filename is metadata, not a safe destination path. The store
 * validates `fileNameStem` as a path segment and appends an extension from the
 * selected asset's supported content type. This prevents an app from silently
 * relabeling every picked asset as `.jpg` while retaining its own stable ID.
 */
type DurablePickedAssetCopyInput = {
    readonly asset: PickedAsset;
    /** Nested folders below the configured root. Every segment is validated independently. */
    readonly directory?: readonly string[] | undefined;
    /** Safe, caller-owned destination filename stem; the store adds the validated extension. */
    readonly fileNameStem: string;
};

type DurablePickedAssetFile = DurableFile & {
    readonly fileName: string;
    readonly contentType: MediaContentType;
};

type ExifCapturedAtOptions = {
    /**
     * Offset saved with the event in minutes east of UTC (KST = 540). When this
     * is omitted, the historical device-local behaviour of
     * `mediaMetadataFromExif` is preserved.
     */
    readonly timeZoneOffsetMinutes?: number | undefined;
};

/**
 * A timezone-less EXIF wall clock. EXIF itself carries no offset, so this is
 * deliberately not a `Date`: callers must choose the policy for mapping it to
 * an instant.
 */
type ExifWallClock = {
    readonly year: number;
    readonly month: number;
    readonly day: number;
    readonly hour: number;
    readonly minute: number;
    readonly second: number;
    readonly millisecond: number;
};

/** 저장 플로우 전용 — 업로드만 하는 소비자는 구현할 필요가 없다. */
interface FileDownloadAdapter {
    download(input: {
        readonly url: string;
        readonly to: string;
    }): Promise<{
        readonly uri: string;
        readonly status: number;
    }>;
}

/**
 * 전신의 `{exists, isDirectory, size}`를 판별 유니언으로 교체.
 * `info.exists && !info.isDirectory ? info.size : 0` 패턴 5중복이 좁히기 한 번으로 소멸한다
 * (§7 하드닝 3).
 */
type FileStat = {
    readonly kind: 'file';
    readonly sizeBytes: number;
} | {
    readonly kind: 'directory';
} | {
    readonly kind: 'missing';
};

interface FileSystemAdapter {
    /** 앱 소유 캐시 디렉토리 URI(끝에 '/'). 없으면 documentDirectory, 그것도 없으면 null. */
    cacheDirectory(): string | null;
    /** ⚠ throw 금지 — 코어가 후보 URI를 순회한다. 없거나 디렉토리면 그 kind를 반환. */
    stat(uri: string): Promise<FileStat>;
    copy(input: {
        readonly from: string;
        readonly to: string;
    }): Promise<void>;
    /** 멱등 삭제. 실패해도 throw 금지 — 스테이징 누수는 디스크 비용일 뿐이다. */
    remove(uri: string): Promise<void>;
    /**
     * `[position, position+length)` 구간을 base64로 반환.
     * ⚠ 코어는 length를 **항상 3의 배수**로 준다(§7 하드닝 9 — 3바이트가 base64 4문자에 대응하므로
     * 3의 배수가 아니면 윈도우 경계에 패딩이 끼어 **해시가 조용히 틀린다**).
     * 어댑터가 범위를 재정렬·병합·확장하면 그 하드닝이 무력화된다.
     */
    readBase64(uri: string, range: ChunkRange): Promise<string>;
}

/** 전신 `PhotoGeoPoint`. */
type GeoPoint = {
    readonly latitude: number;
    readonly longitude: number;
};

/**
 * 기본 구현은 core 내장 순수 TS 증분 SHA-256(§9) — `js-sha256` 제거, 런타임 의존성 0.
 * 네이티브 가속이 필요한 호스트만 교체한다.
 *
 * ⚠ 해시는 dedup **최적화**일 뿐이므로 실패가 업로드를 막지 않는다(§7.1). 그 정책은 코어의
 * `hashSafely()`가 갖는다 — 어댑터는 그냥 throw해도 된다.
 */
interface HashAdapter {
    hashLocalFile(uri: string): Promise<string>;
    hashBinary(source: BinarySource): Promise<string>;
}

/**
 * `instanceof` 대신 이것을 쓴다(§5.2). 엔트리마다 복제된 코어 사본이 만든 에러도 인식한다.
 */
declare function isMediaError(error: unknown): error is MediaError;

/**
 * ⚠ **계약: 파일 바이트를 JS 힙으로 읽지 말 것.** 네이티브 스트리밍 업로드여야 한다.
 *
 * 근거(§7 하드닝 1): `FileSystem.uploadAsync`(레거시 URLSession 브리지)가 iOS 26에서 파일 기반
 * 업로드를 **시작하는 중 프로세스를 종료시킨다** — promise가 reject될 기회조차 없으므로
 * 재시도 로직도 에러 보고도 발화하지 않는다. 크래시 리포트에도 앱 코드 프레임이 남지 않아
 * 원인 추적에만 수일이 걸렸다.
 *
 * expo 기본 어댑터는 `new File(uri).upload(url, { sessionType: 'foreground',
 * uploadType: BINARY_CONTENT })`를 쓴다. `hardening-guard`가 `uploadAsync` 문자열의
 * 재등장을 `src/**` 전역에서 정적 차단한다.
 */
interface LocalFileTransport {
    putLocalFile(input: PutRequest & {
        readonly uri: string;
    }): Promise<{
        readonly status: number;
    }>;
}

/**
 * The only per-item failures this local saver exposes. These are batch
 * outcomes, rather than thrown `MediaError`s: one bad file must not stop later
 * files from being saved. Adapter errors and URIs never escape.
 */
type LocalMediaSaveFailureCode = 'save-local-file-unavailable' | 'save-local-file-failed';

/**
 * The local save path only needs an existence/size check. Requiring the full
 * upload `FileSystemAdapter` would make a save-only consumer implement unused
 * cache, copy, base64-read, and download capabilities.
 */
interface LocalMediaSaveFileAdapter {
    stat(uri: string): Promise<FileStat>;
}

type LocalMediaSaveItemResult = {
    readonly index: number;
    readonly id?: string | undefined;
    readonly status: 'saved';
} | {
    readonly index: number;
    readonly id?: string | undefined;
    readonly status: 'unavailable';
    readonly errorCode: 'save-local-file-unavailable';
} | {
    readonly index: number;
    readonly id?: string | undefined;
    readonly status: 'failed';
    readonly errorCode: 'save-local-file-failed';
};

interface LocalMediaSaver {
    /**
     * Saves app-owned local files in input order. A missing/empty source and an
     * OS save failure are reported per item so one bad item never prevents later
     * files from being attempted. A write-permission failure rejects once with a
     * user-safe `MediaError('save-permission-denied')` before any save attempt.
     */
    saveLocalToDevice(media: readonly LocalSaveableMedia[]): Promise<LocalMediaSaveResult>;
}

type LocalMediaSaveResult = {
    /** Input order is preserved, including unavailable sources. */
    readonly items: readonly LocalMediaSaveItemResult[];
    readonly savedCount: number;
    readonly unavailableCount: number;
    readonly failedCount: number;
