 * 브랜드·phantom 각인 없이 오배치가 차단된다.
 */
interface LocalPosterAdapter {
    /** ⚠ 실패는 `null`. 포스터 실패가 동영상 업로드를 막지 않는다(§7.1). */
    posterFromLocalFile(input: {
        readonly uri: string;
        readonly atMs: number;
