}

/** A host-owned local artifact. `id` is only returned for caller-side correlation. */
type LocalSaveableMedia = {
    readonly uri: string;
    readonly id?: string | undefined;
};

type LocalUploadInput<TCollectionId extends string = string> = {
    readonly uri: string;
    readonly fileName?: string | undefined;
    readonly contentType?: MediaContentType | undefined;
    readonly sizeBytes?: number | undefined;
    /**
     * ⚠ **주어지면 hasher를 호출하지 않는다**(§7.1 신설 행). 전신 `uploadLocalUriToIntent`는 해시를
     * 계산하지 않고 호출자 값을 그대로 전달했다(uploader.ts:57-69의 필드 정의, 440의 전달).
     * 동기화 큐가 재시도 간 해시를 캐시하기 때문이다:
     *   `src/sync/uploadAsset.ts:45-46` — "Reuse the cached hash across retries; only compute
     *   on first attempt" / `item.contentHash ?? (await hash(source.uri))`.
     * 이 필드가 없으면 재시도마다 15MB 파일을 다시 해시한다(순수 TS SHA-256 위에서는 §12-3의
     * Hermes 성능 리스크와 곱해진다).
     *
     * ⚠ 바로 아래 `hashSafely`의 "해시 실패는 업로드를 막지 않는다"와 **나란히** 읽어야 한다 —
     *    한쪽만 보면 정반대 구현이 나온다(§7.1의 경고 그대로).
     */
    readonly contentHash?: string | undefined;
    readonly collectionId?: TCollectionId | null | undefined;
    readonly photo?: MediaMetadata | undefined;
    readonly durationMs?: number | undefined;
    readonly width?: number | undefined;
    readonly height?: number | undefined;
};

interface LocalUploads<TAsset, TCollectionId extends string = string> {
    uploadLocalFile(input: LocalUploadInput<TCollectionId>): Promise<UploadResult<TAsset>>;
    /**
     * 피커 자산 1건 — `PickerFlows`·`DeviceUploads`가 위임한다.
     * ⚠ **네이티브 전용이다.** `platform.os === 'web'`이면 `MediaError('platform-unsupported')`
     * — 로컬 파일 스트리밍은 웹에 존재하지 않는다. 웹 피커 자산의 정본 경로는 §5.7.4다.
     */
    uploadPickedAsset(asset: PickedAsset, options?: {
        readonly collectionId?: TCollectionId | null | undefined;
    } | undefined): Promise<UploadResult<TAsset>>;
}

/**
 * 하나의 스팬. 정확히 한 번만 종료되어야 한다(라이브러리 내부 규율 — 소비자 검증 대상 아님).
 *
 * `cancel`은 "실패가 아닌 중단"이다: 빈 포스터(전신 uploader.ts:268-271)처럼 사용자에게
 * 오류로 보고하면 안 되지만 성공으로 세어서도 안 되는 **3번째 종료 상태**다.
 * 이 상태가 없으면 포스터 추출이 빈 결과를 낸 경우가 성공률 지표에 섞여 들어간다.
 */
interface MediaActivity {
    succeed(finish?: MediaActivityFinish | undefined): void;
    fail(error: unknown, finish?: MediaActivityFinish | undefined): void;
    cancel(finish?: MediaActivityFinish | undefined): void;
}

type MediaActivityFinish = {
    readonly extra?: Readonly<Record<string, unknown>> | undefined;
};

/**
 * 전신 `PhotoDebugLogger`(debug.ts:39-47)를 그대로 계승한다. 초안은 반환 타입만 있고 멤버가 없어
 * 구현자가 임의로 정할 수 있었다 — 그러면 하드닝 8의 새니타이즈 지점이 구현마다 달라진다(G14).
 */
interface MediaDebugLogger {
    log(event: string, details?: Readonly<Record<string, unknown>> | undefined): void;
    /** `errorName` + **새니타이즈된** `errorMessage`를 details에 병합해 기록한다(전신 동작 보존). */
    error(event: string, error: unknown, details?: Readonly<Record<string, unknown>> | undefined): void;
}

/**
 * 디버그 로거 설정. 전신 `PhotoUploaderConfig`의 `debugTag`/`debugContext`에 1:1 대응한다.
 * ⚠ core에는 `__DEV__`가 없으므로 기본값은 **비활성**이다. 실제 게이트는
 * `createMediaDebugLogger`가 `platform.isDev && platform.os !== 'web'`로 건다(§7 하드닝 8).
 */
type MediaDebugOptions = {
    readonly enabled: boolean;
    readonly tag?: string | undefined;
    readonly context?: (() => Record<string, unknown>) | undefined;
};

/**
 * 저장 파일명 = `` `${prefix}-${id || index + 1}.${ext}` `` (전신 saveImages.ts:71).
 *
 * 확장자 우선순위 — **저장된 fileName → contentType → URL 경로 → `'jpg'`**.
 * 전신 주석(saveImages.ts:56-58) 그대로의 근거: "저장된 원본 이름을 우선한다 — 다운로드 URL은
 * 흔히 경로에 확장자가 없는 토큰화된 프록시라, URL을 스니핑하면 모든 PNG/HEIC/동영상
 * 다운로드가 `<prefix>-<id>.jpg`가 되어버린다."
 *
 * ⚠ `index`는 **0-base 필수 인자**다(G8). `id`가 없거나 빈 문자열일 때 `index + 1`이
 * 유일한 구분자이며, 이것이 없으면 여러 장을 저장할 때 파일명이 전부 같아진다 —
 * 브라우저는 `(1)` 접미사로 얼버무리고, MediaLibrary 경로는 캐시 파일을 덮어쓴다.
 */
declare function mediaDownloadFileName(input: {
    readonly url: string;
    readonly index: number;
    readonly id?: string | undefined;
    readonly fileName?: string | undefined;
    readonly contentType?: MediaContentType | undefined;
    readonly prefix?: string | undefined;
}): string;

declare class MediaError extends Error {
    readonly code: MediaErrorCode;
    constructor(code: MediaErrorCode, message: string);
}

/**
 * 전신 `photoErrorUserMessage`.
 * `MediaError`의 message는 이미 사용자 노출 가능 문구다(`MediaStrings` 주입 결과 — §4).
 * 화면은 일반 실패 문구 대신 이 값을 그대로 표시해도 된다.
 */
declare function mediaErrorUserMessage(error: unknown): string | null;

/**
 * 전신의 `defaultMediaFileName`·`inferFileName`·`inferWebFileName` **3종을 하나로 통합**(§5.7.2-③).
 *
 * `fileName`이 있으면 그대로 쓰고, 없으면 `${prefix}-${now}.${ext}`(전신 규칙 보존).
 * ⚠ `now`는 결정론적 테스트를 위한 주입구다 — 생략 시 `Date.now()`로 전신과 동일하게 동작한다
 * (§5.4.1-15). 전신은 `Date.now()`를 직접 호출해 파일명 규칙에 테스트가 없었다.
 * ⚠ `prefix` 기본값은 `'media'`다 — 전신 `'photo'`에서 바꿨다(§5.4.1-13). 호스트는 항상 자기
 * 프리픽스를 주입하므로 이관 영향이 0이며, 라이브러리 이름과의 일관성을 택했다.
 */
declare function mediaFileName(input: {
    readonly fileName?: string | null | undefined;
    readonly contentType: MediaContentType;
    readonly prefix?: string | undefined;
    readonly now?: number | undefined;
}): string;

/**
 * 전신 `isVideoContentType`의 자리를 잇는다(그쪽은 §5.7.2-③에서 내부화 —
 * 동치 대체가 `mediaKindOf(ct) === 'video'`다).
 */
declare function mediaKindOf(contentType: MediaContentType): MediaKind;

/**
 * 골든패스 킷. expo 기본 어댑터(platform·files·localTransport·binaryTransport·hasher·staging)가
 * 이미 채워져 있다.
 *
 * ⚠ 선택 능력은 **구체 킷을 반환하는 `with*`**로 부착한다(§3.1). `with*`는 자기 자신을 넓히지
 * 않고 새 객체를 반환하므로 조건부 타입이 0이다 — V3가 실측한 "타입 애노테이션 한 번에 전 기능이
 * 소멸하는" 붕괴가 **표현 불가능**하다.
 */
interface MediaKit<TAsset, TCollectionId extends string = string> extends LocalUploads<TAsset, TCollectionId>, BinaryUploads<TAsset, TCollectionId> {
    readonly platform: PlatformAdapter;
    readonly files: FileSystemAdapter;
    readonly staging: StagingCache;
    /**
     * ⚠ **공개 필드다**(V9 요구). memorylog2 `src/sync/hashFile.ts`가 `hashLocalFile`을 재export하고
     * `src/sync/uploadAsset.ts:14,22`가 그것을 쓴다. 이 필드가 없으면 앱 어댑터가 위임할 대상이
     * 없어 동기화 엔진이 해시 함수를 잃는다(§5.7.2-⑦).
     */
    readonly hasher: HashAdapter;
    withPicker(picker: PickerAdapter, 
    /**
     * 웹에서 피커 자산을 업로드하는 앱은 `loader`만 주면 된다 — `uploads`는 킷 자신
     * (`BinaryUploads`)이 채운다. 생략 시 웹 피커 업로드는 `platform-unsupported`다(§5.7.4).
     */
    options?: {
        readonly web?: {
            readonly loader: BinarySourceLoader;
        } | undefined;
    } | undefined): PickerFlows<TAsset, TCollectionId>;
    withDeviceLibrary(adapter: DeviceLibraryAdapter): DeviceKit<TAsset, TCollectionId>;
    withDeviceSave(adapter: MediaLibrarySaveAdapter): MediaSaver;
}

type MediaKitConfig<TAsset, TCollectionId extends string = string> = Omit<MediaUploadConfig<TAsset, TCollectionId>, 'platform'> & {
    /**
     * expo 기본 어댑터 위의 **선택 오버라이드**. 각 필드는 개별 교체이며 부분 객체가 아니다 —
     * `platform`만 갈아끼우고 나머지는 기본값을 그대로 쓰는 조합이 정상이다.
     */
    readonly platform?: PlatformAdapter | undefined;
    readonly files?: FileSystemAdapter | undefined;
    readonly localTransport?: LocalFileTransport | undefined;
    readonly binaryTransport?: BinaryTransport | undefined;
    readonly hasher?: HashAdapter | undefined;
    /** 네이티브 경로(로컬 URI → 포스터). 보통 `expoVideoPoster()`(`"./video"`). */
    readonly poster?: LocalPosterAdapter | undefined;
    /**
     * 바이너리 경로(Blob → 포스터). 보통 `webCanvasVideoPoster()`(`"./web"`).
     *
     * ⚠ `poster`와 **입력 타입이 달라 자리를 바꿔 끼우면 컴파일 에러**가 나는 것이 설계다(§6.1-⑥).
     *   그래서 필드도 둘로 나뉜다 — 하나로 합치면 그 검출력이 사라진다.
     * ⚠ 주지 않으면 **웹 동영상에 포스터가 붙지 않는다.** 전신 uploader.ts:566-569는
     *   `posterBlob === undefined`일 때 `createWebVideoPosterBlob(blob)`으로 자동 추출했으므로,
     *   웹 업로드 경로가 있는 앱이 이 필드를 비우면 그 동작이 조용히 사라진다.
     *   (호출자가 `uploadBinary({ poster })`로 직접 주는 경로는 이 필드와 무관하게 항상 동작한다.)
     */
    readonly binaryPoster?: BinaryPosterAdapter | undefined;
    readonly posterAtMs?: number | undefined;
    /** 스테이징 네임스페이스. 기본 `'gj-media'`. `/^[a-z0-9][a-z0-9-]{1,30}$/`(§5.3). */
    readonly namespace?: string | undefined;
};

interface MediaLibrarySaveAdapter {
    requestWritePermission(): Promise<MediaPermission>;
    saveToLibrary(uri: string): Promise<void>;
    /**
     * Android Expo Go는 사진 권한 요청 자체가 불가 — 그 판정을 어댑터가 정적으로 노출한다
     * (전신 saveImages.ts:96). `expo-constants` 의존을 라이브러리에서 완전히 제거하는 지점(§0.2):
     * `Constants.appOwnership === 'expo'` 판정은 호스트가 하고 값만 넘긴다.
     */
    readonly skipPermissionRequest: boolean;
}

/**
 * 전신 `extractPhotoMetadataFromBlob(blob, fallbackExif, contentType)`(photoMetadata.ts:265-290).
 * 초안이 지웠던 인자 2개를 `options`로 **복원**한다(G6 · §7.1). **4규칙이 계약이다**:
 *   ① 비-JPEG 스킵 — `(contentType ?? source.type)`이 'jpeg'/'jpg'를 포함하지 않으면 파싱하지 않고
 *      fallback을 그대로 반환한다.
 *   ② **필드 단위 병합** — `parsed?.X ?? fallback?.X`. 객체 단위 폴백이 아니다.
 *      capturedAt만 파싱되고 geoPoint는 fallback에서 오는 조합이 **정상 결과**다.
 *   ③ 파싱 예외 시 fallback 반환 — throw 금지. 메타데이터 때문에 업로드가 죽어선 안 된다.
 *   ④ ①②③ 이후에도 유효값이 없으면 `undefined`(빈 객체 금지 — `mediaMetadataFromExif`와 동일).
 *
 * ⚠ 인자를 지우면 웹 피커 경로(`fallbackExif: asset.exif`)에서 JPEG 파싱이 실패했을 때 피커가 준
 * EXIF가 통째로 버려져 촬영시각·위치가 유실된다. 그 유실은 컴파일도 테스트도 통과한다.
