type MediaOrphanedUpload = MediaUploadObject & {
    readonly storageState: 'uploaded' | 'possibly-uploaded';
};

type MediaPermission = {
    readonly granted: boolean;
    readonly canAskAgain: boolean;
    /** iOS "선택된 사진" — 일부만 보인다. */
