}

interface MediaTelemetry {
    /**
     * `run()`을 감싸 성공/예외를 자동 보고한다. 구현은 `run()`의 결과·예외를 그대로
     * return/rethrow해야 한다. 라이브러리는 호스트 텔레메트리를 관측자로 취급하므로,
     * 구현 자체의 예외는 실제 업로드·저장 결과를 바꾸지 않는다.
