interface MediaUploadApi<TAsset, TCollectionId extends string = string> extends MediaUploadIntentApi<TCollectionId> {
    completeUpload(input: MediaUploadCompletion<TCollectionId>): Promise<UploadResult<TAsset>>;
}

/** 바이트가 스토리지에 올라간 뒤 보내는 등록 페이로드. */
type MediaUploadCompletion<TCollectionId extends string = string> = {
    readonly fileName: string;
    readonly contentType: MediaContentType;
    readonly sizeBytes: number;
    readonly objectName: string;
    readonly contentHash?: string | undefined;
    /**
     * 불투명 그룹 id — 킷은 해석하지 않고 전달만 한다(§6.2 기각: `CollectionId` 브랜드).
     * memorylog2는 이것을 `albumId`로 매핑한다. 빈 문자열은 런타임 차단(§6.1-⑪) —
     * falsy 스프레드로 조용히 탈락해 앨범 없이 저장되는 경로를 막는다.
     */
    readonly collectionId?: TCollectionId | undefined;
    readonly photo?: MediaMetadata | undefined;
    readonly durationMs?: number | undefined;
    readonly width?: number | undefined;
    readonly height?: number | undefined;
    readonly poster?: UploadedPoster | undefined;
};

type MediaUploadConfig<TAsset, TCollectionId extends string = string> = MediaUploadBaseConfig<TCollectionId> & {
    readonly api: MediaUploadApi<TAsset, TCollectionId>;
};

/**
 * `mediaUploadFailureInfo(error)`가 돌려주는, cross-entry-safe 실패 복구 정보.
 *
 * 이 정보는 에러에 전역 심볼로 비열거형 각인되므로 code splitting으로 코어 사본이 갈린
 * 엔트리에서도 검사할 수 있다. `orphanedObjects`는 attachment/등록이 끝나기 전에 남은
 * 정리 후보이며, 앱은 자신의 권한 있는 cleanup API로만 처리해야 한다.
 */
type MediaUploadFailureInfo = {
    readonly stage: MediaUploadFailureStage;
    readonly orphanedObjects: readonly MediaOrphanedUpload[];
};

/** 백엔드가 발급한 단일 오브젝트 presigned 업로드 슬롯. */
type MediaUploadIntent = {
    readonly uploadUrl: string;
    readonly method: 'PUT';
    readonly headers: Readonly<Record<string, string>>;
    readonly objectName: string;
};

/**
 * Presign-only backend seam.
 *
 * Some products deliberately attach the uploaded object in a later domain
 * transaction (for example, after creating a record). They must not pretend
 * that a registration endpoint exists just to use the local streaming path.
 * `MediaUploadApi` extends this narrower contract for the usual
 * presign → PUT → complete flow.
 */
interface MediaUploadIntentApi<TCollectionId extends string = string> {
    createUploadIntent(input: MediaUploadIntentRequest<TCollectionId>): Promise<MediaUploadIntent>;
}

type MediaUploadIntentRequest<TCollectionId extends string = string> = {
    readonly fileName: string;
    /** ⚠ 전신은 `string`이었다. 닫힌 8종 유니언으로 좁혀 서버 zod와 클라이언트가 어긋나지 않게 한다. */
    readonly contentType: MediaContentType;
    readonly sizeBytes: number;
    /**
     * 업로드를 시작하기 전에 백엔드가 권한·용량을 확인해야 하는 경우의 불투명 그룹 id.
     * 완료 단계의 `collectionId`와 같은 값이며, 킷은 해석하거나 생성하지 않고 그대로 전달한다.
     * 선택적 필드라 기존 presign-only 소비자는 변경 없이 동작한다.
     */
    readonly collectionId?: TCollectionId | undefined;
};

/**
 * 백엔드 정책을 반영한 클라이언트 크기 캡. 같은 문구로 **빨리** 실패시켜 사용자가 전체 업로드를
 * 마친 뒤 413을 받는 일을 없앤다.
 */
type MediaUploadLimit = {
    readonly maxBytes: number;
    readonly message?: string | undefined;
};

/**
 * ⚠ 팩토리에서 이 값은 **생략 불가**다(§6.1-③). 무제한 업로드는 명시적 결정이어야 한다.
 * 서버만 검증하는 정책도 정당하므로 팩토리 설정은 `MediaUploadLimits | 'server-enforced'`를 받는다
 * (`Number.POSITIVE_INFINITY`는 JSON 직렬화 불가라 기각 — §0.4 기각 8).
 */
type MediaUploadLimits = {
    readonly image?: MediaUploadLimit | undefined;
    readonly video?: MediaUploadLimit | undefined;
};

/**
 * 스토리지에 쓸 수 있는 이름으로 발급된 오브젝트의 안전한 식별 정보.
 *
 * URL·헤더·서명은 의도적으로 없다. 앱은 이 값만 자기 cleanup API에 넘겨, 실패한
 * 업로드가 남긴 object를 best-effort로 정리할 수 있다. `objectName`의 권한 검증은
 * 언제나 서버가 다시 해야 하며, 이 타입은 클라이언트 권한 증명이 아니다. 런타임에서는
 * 1024자 이하 ASCII unreserved 경로 세그먼트(`[A-Za-z0-9._~-]`)와 `/`만 허용한다.
 * URL/query/percent-encoding/공백을 받지 않으므로, 서버는 그 문법을 발급 키에도 맞춰야 한다.
 */
type MediaUploadObject = {
    readonly objectName: string;
    readonly contentType: MediaContentType;
    readonly sizeBytes: number;
};

/** 웹 File의 구조적 최소치 — DOM lib 없이 `isSupportedMediaFile`을 쓰기 위해(§7 하드닝 10). */
interface NamedBinarySource extends BinarySource {
    readonly name: string;
}

type PendingAddResult = {
    /** The next state. Same reference as the input when nothing was added. */
    readonly state: PendingSelectionState;
    /** Items that entered the selection, in input order. */
    readonly added: readonly PendingMediaItem[];
    /**
     * Items that did not enter the selection, in input order, with the reason. Use it for messaging.
     * A `duplicate` entry can be the very object that is already staged (the host re-added it), so
     * do not release this list directly — release `releasable`.
     */
    readonly rejected: readonly PendingRejection[];
    /**
     * Rejected items that are safe to hand to `release`: every rejected item that is not the same
     * object as an item in `state`, each object once, in input order. Their `revoke` has not been
     * called. Picked items and binaries without `revoke` may appear here; `release` ignores them.
     */
    readonly releasable: readonly PendingMediaItem[];
};

/**
 * A binary (web `File`, `Blob`, or any `NamedBinarySource`) staged for a later upload.
 *
 * Core never touches DOM APIs, so the preview resource is injected: `previewUri` is whatever the
 * host can render (typically an object URL) and `revoke` releases it. On web,
 * `pendingItemFromFile` from `@gj-kit/expo-media/web` builds this shape from a DOM `File`.
 */
type PendingBinaryItem = {
    readonly kind: 'binary';
    readonly source: NamedBinarySource;
    /** Renderable preview URI (for example an object URL). Omit when none exists. */
    readonly previewUri?: string | undefined;
    /**
     * Releases the preview resource. The selection calls it **at most once per item object**, when
     * the item leaves a selection through `remove`/`clear`, or when the host passes it to `release`.
     */
    readonly revoke?: (() => void) | undefined;
    /**
     * Modification timestamp (ms epoch) folded into the dedup key, e.g. DOM `File.lastModified`.
     * Without it two binaries with the same name and size are considered the same file.
     */
    readonly lastModified?: number | undefined;
};

/** A picker, camera, or device-library asset staged for a later upload. */
type PendingPickedItem = {
    readonly kind: 'picked';
    readonly asset: PickedAsset;
};

type PendingRejection = {
    readonly item: PendingMediaItem;
    readonly reason: PendingRejectionReason;
};

/**
 * Why an item did not enter the selection.
 * - `duplicate`: an item with the same `keyOf` is already staged (or appeared earlier in the batch).
 * - `over-limit`: the selection already holds `max` items.
 */
type PendingRejectionReason = 'duplicate' | 'over-limit';

interface PendingSelection {
    /** The configured cap. */
    readonly max: number;
    /**
     * Stable identity of an item: `asset:<assetId>` (falling back to the URI when the picker gave
     * no asset id) for picked items, `binary:<name>:<size>:<lastModified>` for binaries.
     */
    keyOf(item: PendingMediaItem): string;
    /**
     * Stage items. Duplicates (by `keyOf`, including duplicates within `items`) are rejected before
     * the cap is checked, so a re-selected photo reports `duplicate` even when the selection is full.
     * Nothing is revoked here; pass the result's `releasable` to `release`. Neither `state` nor
     * `items` is mutated, and the result object and its arrays are frozen.
     */
    add(state: PendingSelectionState, items: readonly PendingMediaItem[]): PendingAddResult;
    /**
     * Drop every item whose `keyOf` equals `key`, calling `revoke` on removed binaries. Returns the
     * same reference when no item matched.
     */
    remove(state: PendingSelectionState, key: string): PendingSelectionState;
    /** Drop every item, calling `revoke` on each binary that still holds a preview resource. */
    clear(state: PendingSelectionState): PendingSelectionState;
    /**
     * Call `revoke` on binaries that are not staged — typically `PendingAddResult.releasable`.
     * Idempotent per item object; picked items and binaries without `revoke` are ignored. Passing an
     * item that is still staged kills its live preview, which is why `rejected` is not the input here.
     */
    release(items: readonly PendingMediaItem[]): void;
    /** Picked assets in selection order — the input of `uploadPickedAsset` / device resolve paths. */
    toPickedAssets(state: PendingSelectionState): readonly PickedAsset[];
    /** Binary sources in selection order — the input of `uploadBinary` / `uploadDropped`. */
    toBinarySources(state: PendingSelectionState): readonly NamedBinarySource[];
    /**
     * URI the host can render, or `null`. Picked assets always preview through their own URI. A binary
     * previews only when it has a `previewUri` **and** is not HEIC/HEIF — browsers cannot decode those,
     * and an `<img>` that never loads looks like a broken upload.
     */
    previewUriOf(item: PendingMediaItem): string | null;
    /** `previewUriOf(item) !== null`. */
    canPreview(item: PendingMediaItem): boolean;
    /**
     * Capture time as an ISO string, or `null`. Picked items read the picker EXIF dictionary; binaries
     * parse the JPEG APP1 segment from bytes (the same parsers the upload path uses). Never throws.
     */
    capturedAtOf(item: PendingMediaItem): Promise<string | null>;
}

type PendingSelectionOptions = {
    /** Maximum number of staged items. Must be a positive integer; otherwise `MediaError('config-invalid')`. */
    readonly max: number;
};

type PickedAsset = {
    readonly uri: string;
    /**
     * 기기 라이브러리 원본 식별자(iOS PhotoKit localIdentifier / Android MediaStore id).
     * 없을 수 있다(웹 File 드롭, 카메라 캡처).
     *
     * ⚠ **왜 필요한가**: 소비자의 dedup 1차 키다 —
     *   `apps/mobile/src/photos/pendingPhotos.ts:43`
     *   ``pickerAssetDedupKey = `asset:${asset.assetId ?? asset.uri}` ``
     * uri 폴백만 남으면 스테이징 사본 uri가 resolve마다 재생성되므로(§7 하드닝 2) 같은 사진을
     * 두 번 선택했을 때 dedup이 통과해버린다. 전신은 `resolveDeviceAssetForUpload`가
     * `assetId: asset.id`를 채워 device 자산과 picker 자산의 동일성을 유지했다
     *   — devicePhotoLibrary.ts:364. 새 설계에서는 `toPickedAsset`이 그 역할을 한다(§5.4-④).
     */
    readonly assetId?: string | undefined;
    readonly fileName?: string | undefined;
    readonly mimeType?: string | undefined;
    readonly width?: number | undefined;
    readonly height?: number | undefined;
    /**
     * ⚠ 어댑터는 **원시값 그대로** 넘긴다. 네이티브는 ms, 웹은 s이며 정규화는 core가 한다
     * (§7 하드닝 4 — 정규화 지점을 하나로 고정. 어댑터가 변환하면 이중 변환이 된다).
     *
     * 전신 사고: expo-image-picker 웹이 `HTMLVideoElement.duration`(초)을 그대로 전달해
     * 20분 영상이 1200ms로 저장됐고, 어떤 길이 캡도 그것을 통과시켰다.
     */
    readonly durationRaw?: number | undefined;
    readonly exif?: Readonly<Record<string, unknown>> | undefined;
    /**
     * 어댑터가 "실제로 스트리밍될 파일"을 stat해 확인한 크기. 있으면 최우선.
     * 전신의 뒷문 프로퍼티 `__photoKitVerifiedSizeBytes`를 정식 필드로 승격(§7 하드닝 3).
     */
    readonly verifiedSizeBytes?: number | undefined;
    /**
     * ⚠ 신뢰 금지 — 최후 폴백이다(§7 하드닝 3).
     * Android가 `quality < 1`로 재인코딩할 때 `asset.fileSize`는 **원본** 크기를 보고하므로
     * 스토리지가 실제로 받은 바이트와 어긋나 서버가 업로드를 거절한다.
     * 필드명이 곧 신뢰도다: `verifiedSizeBytes`(실측) > file-system stat > `reportedSizeBytes`(자칭).
     */
    readonly reportedSizeBytes?: number | undefined;
};

interface PickerAdapter {
    requestLibraryPermission(kinds: readonly MediaKind[]): Promise<MediaPermission>;
    requestCameraPermission(): Promise<MediaPermission>;
    /**
     * ⚠ iOS 원본 fast path 고정 조합(§7.1): `quality: 1` · `exif: true` ·
     * `allowsEditing: false` · `preferredAssetRepresentationMode: Current`.
     * **단일선택/다중선택이 달라지면 안 된다** — 한쪽만 재인코딩 경로로 빠지면 같은 사진이
     * 선택 방식에 따라 다른 바이트로 업로드된다.
     */
    pickFromLibrary(input: {
        readonly kinds: readonly MediaKind[];
        readonly max: number;
    }): Promise<readonly PickedAsset[]>;
    /**
     * 카메라 캡처.
     * ⚠ 상위 플로우(`captureAndUpload`)는 **항상 최대 1건**으로 자른다
     * (전신 uploader.ts:1008 `result.assets.slice(0, 1)`).
     */
    capture(input: {
        readonly kind: MediaKind;
    }): Promise<readonly PickedAsset[]>;
}

interface PickerFlows<TAsset, TCollectionId extends string = string> {
    pick(options?: {
        readonly max?: number | undefined;
        readonly kinds?: readonly MediaKind[] | undefined;
    } | undefined): Promise<readonly PickedAsset[]>;
    pickAndUpload(options?: PickUploadOptions<TCollectionId> | undefined): Promise<readonly UploadResult<TAsset>[]>;
    /**
     * ⚠ 항상 **최대 1건**이다(전신 uploader.ts:1008 `result.assets.slice(0, 1)`).
     * 무시되는 옵션은 그 자체로 함정이므로 옵션 타입에서 `max`를 Omit한다(§5.4.1-12).
     */
    captureAndUpload(options?: (Omit<PickUploadOptions<TCollectionId>, 'max'> & {
        readonly kind?: MediaKind | undefined;
    }) | undefined): Promise<readonly UploadResult<TAsset>[]>;
}

type PickUploadOptions<TCollectionId extends string = string> = {
    readonly collectionId?: TCollectionId | null | undefined;
    readonly max?: number | undefined;
    readonly kinds?: readonly MediaKind[] | undefined;
};

/**
 * core에서 `react-native` import를 제거하는 유일한 이유. 필드 2개뿐인 것이 정상이다.
 *
 * 전신 `debug.ts`는 `Platform`을 직접 import했고, 그 한 줄 때문에 서명 URL 새니타이저
 * (§7 하드닝 8)를 순수 유닛으로 검증할 수 없었다. 주입으로 바꾸면서 debug 모듈이 core로 하강했다.
 */
interface PlatformAdapter {
    readonly os: MediaPlatform;
    /** `__DEV__` 상당. 디버그 로거 게이트(§7 하드닝 8). expo 기본값: `__DEV__ && NODE_ENV !== 'test'`. */
    readonly isDev: boolean;
}

type PutRequest = {
    readonly url: string;
    readonly method: 'PUT';
    readonly headers: Readonly<Record<string, string>>;
};

/**
 * `DeviceLibrary.resolveForUpload`의 결과 — 업로드 가능한 바이트의 위치(§5.4-④).
 * 전신 `DeviceAssetUploadSource`(devicePhotoLibrary.ts:255-259).
 */
type ResolvedDeviceAsset = {
    readonly uri: string;
    readonly verifiedSizeBytes?: number | undefined;
    /** ⚠ 전신 그대로 `null` 가능이다. `PickedAsset.exif`로 옮길 때 undefined 정규화가 필요하다. */
    readonly exif: Readonly<Record<string, unknown>> | null;
    /** 스테이징 사본이면 true — 업로드 후 `StagingCache.cleanup` 대상(§7 하드닝 7). */
    readonly staged: boolean;
};

/** `DeviceLibrary.resolvePickedAsset` / `toPickedAsset`의 결과(§5.4-④). */
type ResolvedPickedAsset = PickedAsset & {
    readonly staged: boolean;
};

/**
 * 세 후보 중 가장 신뢰도 높은 것을 고른다. 전부 없으면 `null` —
 * 호출자가 `imageSizeUnknown`/`videoSizeUnknown` 문구로 실패시킨다(§6.1-⑮, 전신 유지).
 *
 * ⚠ 순서를 바꾸면 Android 재인코딩 자산이 다시 원본 크기로 presign된다.
 */
declare function resolveUploadSize(input: {
    /** 어댑터가 "실제로 스트리밍될 파일"을 stat해 확인한 크기(§3.3 `PickedAsset.verifiedSizeBytes`). */
    readonly verifiedSizeBytes?: number | undefined;
    /** 코어가 `FileSystemAdapter.stat`으로 방금 읽은 크기. */
    readonly statSizeBytes?: number | undefined;
    /** ⚠ 피커 자칭(`asset.fileSize`). 최후 폴백이며 단독으로는 신뢰하지 않는다. */
    readonly reportedSizeBytes?: number | undefined;
}): {
    readonly sizeBytes: number;
    readonly source: UploadSizeSource;
} | null;

type SaveableMedia = {
    /**
     * 안정 파일명의 1차 소스(G8). 없거나 빈 문자열이면 배열 인덱스+1로 폴백한다 —
     * 전신 규칙 `${prefix}-${image.id || index + 1}.${ext}`(saveImages.ts:71) 보존.
     */
    readonly id?: string | undefined;
    /**
     * ⚠ **단일 진실이다.** `originalUrl || thumbnailUrl` 같은 폴백은 호스트 DTO 지식이므로
     * 라이브러리가 아니라 앱이 소유한다(전신 `imageDownloadUrl` 폐지 — §5.7.3).
     */
    readonly url: string;
    readonly fileName?: string | undefined;
    readonly contentType?: MediaContentType | undefined;
};

type SaveResult = {
    readonly savedCount: number;
    readonly mode: SaveTarget['kind'];
};

/**
 * 저장 타깃(§6.1-⑦).
 * 전신은 `platformOS:'web'` + `mediaLibrary` 동시 주입이 통과했고, 결과로 보고되는 `mode`와
 * 실제 동작이 어긋날 수 있었다. 판별 유니언이면 무효 조합이 **표현 불가능**해지고
 * `SaveResult.mode`가 `target.kind`에서 파생되므로 보고와 실동작이 어긋날 수 없다.
 */
type SaveTarget = {
    readonly kind: 'media-library';
    readonly files: FileSystemAdapter & FileDownloadAdapter;
    readonly library: MediaLibrarySaveAdapter;
} | {
    readonly kind: 'browser-download';
    readonly browser: BrowserSaveAdapter;
};

/**
 * 증분 해셔. `js-sha256`의 `sha256.create()`와 같은 형태라 전신 호출부가 그대로 옮겨진다.
 *
 * ⚠ `hex()`는 **종료 연산**이다(패딩을 상태에 써 넣는다). 두 번 이상 부르면 같은 값을 돌려주고,
 * 종료 후의 `update()`는 무시한다 — 부분적으로 갱신된 다이제스트를 돌려주는 것보다 낫다.
 */
interface Sha256Hasher {
    update(bytes: Uint8Array): void;
    hex(): string;
}

interface StagingCache extends Brand<'StagingCache'> {
    /** `${namespace}-upload-`. */
    readonly prefix: string;
    /**
     * cleanup의 유일한 판정 근거.
     *
     * 전신은 `uri.includes(PREFIX)` 한 줄이었다(deviceUploadCache.ts:29). 그 술어는
     * `file:///other/dir/memorylog-upload-x.jpg`처럼 **우리가 만들지 않은 경로**도 참으로 만들고,
     * 프리픽스가 중간에 낀 임의의 경로까지 삭제 대상에 넣는다. 3조건으로 좁힌다:
     *   (i) 앱 캐시 디렉토리로 시작 (ii) 파일명이 prefix로 **시작** (iii) 하위 경로 없음
     */
    owns(uri: string | null | undefined): boolean;
    /** 스테이징 사본이 놓일 자리. 캐시 디렉토리가 없으면 `null`. */
    uriFor(asset: DeviceAssetRef): string | null;
    /**
     * 스테이징 사본 삭제. `owns()`가 false면 **no-op**이다.
     * 실패는 삼킨다 — 누수의 대가는 디스크 비용뿐이고, 정리 실패로 업로드 결과를 뒤집을 이유가 없다.
     */
    cleanup(uri: string | null | undefined): Promise<void>;
}

/**
 * ⚠ **원문 URI를 절대 로깅하지 않는다.** 서명 업로드 URL은 쿼리에 임시 자격증명을 담고,
 * 사진 보관함 경로는 사용자의 미디어를 식별한다. 모양(scheme·확장자·길이·종류)만 남긴다.
 *
 * `hardening-guard`가 로거 인자에 `uri`/`url` 원문을 넘기는 것을 정적으로 차단한다 —
 * 이 함수를 **경유하지 않은** 전달은 실패다(§10.3).
 */
declare function summarizeUri(uri?: string | null): {
    readonly scheme: string;
    readonly extension: string | null;
    readonly length: number;
    readonly isFile: boolean;
    readonly isContent: boolean;
    readonly isPhotoKit: boolean;
} | null;

/**
 * 구 `posterObjectName` / `posterSizeBytes` 2필드를 쌍 객체로 통합(§6.1-②).
 * 한쪽만 채워 보내면 서버가 반쪽 메타로 등록해 **썸네일이 영구 누락**된다 — 그 상태를
 * 표현 불가능하게 만든다.
 */
type UploadedPoster = {
    readonly objectName: string;
    readonly sizeBytes: number;
};

/**
 * 전신 `CompletedPhotoUpload<TAsset>`.
 * ⚠ `duplicate`는 **필수**다(§6.1-⑯). 옵셔널이면 호스트가 중복 판정을 반환하지 않을 때
 * 킷이 "새로 만들어졌다"로 오독하고, 중복 취소 경로가 **사용자의 예전 사진을 지운다**.
 */
type UploadResult<TAsset> = {
    readonly asset: TAsset;
    readonly duplicate: boolean;
};

/**
 * switch의 `default`에서 호출하면, 라이브러리가 코드를 추가할 때 소비자에게 컴파일 에러가 난다.
 * ⚠ 강제하지 않는다 — 제공만 한다(§6.1-⑫). 코드 추가는 비파괴 변경이어야 하므로
 * 라이브러리가 소비자에게 exhaustive 분기를 요구할 수는 없다.
 */
declare function assertNeverMediaError(code: never): never;

/** 바이너리 → 포스터 바이너리. 기본 구현은 `"./web"`의 canvas 포스터. */
interface BinaryPosterAdapter {
    /** ⚠ 실패는 `null`. 근거는 `LocalPosterAdapter`와 동일. */
    posterFromBinary(input: {
        readonly source: BinarySource;
        readonly atMs: number;
    }): Promise<BinarySource | null>;
}

/**
 * DOM lib 없이 Blob/File을 받기 위한 구조적 최소 타입.
 * 브라우저 Blob·RN Blob·Node Blob이 전부 구조적으로 만족하며,
 * vitest에서 plain object로 전 경로를 도는 것을 가능하게 한다(§10.1).
 */
interface BinarySource {
    readonly size: number;
    readonly type?: string | undefined;
    arrayBuffer(): Promise<ArrayBuffer>;
}

/**
 * uri → 바이너리. 웹 피커가 주는 `blob:`/`data:` URI를 업로드 가능한 소스로 바꾼다.
 * 기본 구현은 `"./web"`의 `createFetchBinarySourceLoader`(peer 0). 경로 전문은 §5.7.4.
 *
 * 이 seam이 없으면 웹에서 피커 자산을 업로드하는 유일한 방법이 로컬 파일 스트리밍인데,
 * 그 경로는 웹에 존재하지 않는다 — `LocalUploads.uploadPickedAsset`이
 * `MediaError('platform-unsupported')`를 던지는 이유다.
 */
interface BinarySourceLoader {
    fromUri(input: {
        readonly uri: string;
        readonly fileName: string;
    }): Promise<NamedBinarySource>;
}

/** 웹 Blob PUT · 포스터 PUT. fetch 기반 기본 구현은 `"./web"`이 제공한다. */
interface BinaryTransport {
    putBinary(input: PutRequest & {
        readonly body: BinarySource;
    }): Promise<{
        readonly status: number;
    }>;
}

interface BinaryUploads<TAsset, TCollectionId extends string = string> {
    uploadBinary(input: {
        readonly source: NamedBinarySource;
        readonly collectionId?: TCollectionId | null | undefined;
        /**
         * JPEG APP1 파싱이 실패했을 때 **필드 단위로** 병합될 EXIF(§5.3 `mediaMetadataFromJpeg` 규칙 ②).
         * 웹 피커 경로가 `asset.exif`를 여기로 넘긴다(전신 uploader.ts:709 · §5.7.4).
         * 없으면 촬영 시각과 위치가 조용히 유실된다 — 이 인자가 복원된 이유다(G6).
         */
        readonly fallbackExif?: Readonly<Record<string, unknown>> | undefined;
        /**
         * 동영상 포스터. **3상태를 보존한다**(전신 `BlobVideoUploadInput.posterBlob`, uploader.ts:566-569):
         *   `undefined` = 어댑터로 자동 추출 / `null` = 포스터 없음(추출 시도 금지) / 값 = 주어진 포스터.
         * 이 3상태를 2상태로 접으면 "포스터를 일부러 안 만든다"를 표현할 방법이 사라진다.
         */
        readonly poster?: BinarySource | null | undefined;
        /**
         * 동영상 재생시간(**밀리초**). 이미지에는 무시된다.
         * ⚠ 초 단위를 넣지 마라 — 웹의 `HTMLVideoElement.duration`은 **초**다. 호출자가
         *   `normalizeDurationMs`(§7 하드닝 4)를 거쳐 넘겨야 한다. 20분 동영상이 1200ms로
         *   저장되면 어떤 duration 상한도 통과한다. `createPickerFlows`의 웹 경로는 이미 거친다.
         */
        readonly durationMs?: number | null | undefined;
        /**
         * 동영상 픽셀 치수. 이미지에는 무시된다(이미지 치수는 서버가 바이트에서 읽는다).
         * ⚠ `BinarySource`만으로는 DOM 없이 복원할 수 없으므로 **호출자가 주지 않으면 영구 유실**이다 —
         *   전신 `BlobVideoUploadInput.width/height`(uploader.ts:86-87)가 완료 페이로드로 가던 값이다.
         */
        readonly dimensions?: {
            readonly width?: number | null | undefined;
            readonly height?: number | null | undefined;
        } | undefined;
    }): Promise<UploadResult<TAsset>>;
    /**
     * 웹 드롭 다건.
     * ⚠ 첫 presign **이전에** 배치 전체를 검증한다 — 혼합 드롭 부분 업로드 방지(§7 하드닝 10).
     * ⚠ 검증은 `maxFiles` slice **이후**에 수행한다(전신 uploader.ts:623→630 순서 보존).
     * 규칙의 거처는 `webBatch.ts`다.
     */
    uploadDropped(files: readonly NamedBinarySource[], options?: {
        readonly collectionId?: TCollectionId | null | undefined;
        readonly maxFiles?: number | undefined;
    } | undefined): Promise<readonly UploadResult<TAsset>[]>;
}

interface BrowserSaveAdapter {
    /**
     * DOM 접근을 어댑터 안에 가둔다. `document`/`fetch`는 `"./web"`에서 **필수 주입**(§6.1-⑬) —
     * 전신은 미주입 시 `globalThis.document`로 폴백해 네이티브에서도 조용히 생성됐다.
     */
    saveByDownload(input: {
        readonly url: string;
        readonly fileName: string;
    }): Promise<void>;
}

type ChunkRange = {
    readonly position: number;
    readonly length: number;
};

declare function createBinaryUploads<TAsset, TCollectionId extends string = string>(config: MediaUploadConfig<TAsset, TCollectionId> & {
    readonly transport: BinaryTransport;
    /** 생략 = core 내장 순수 TS SHA-256(§9). `FileSystemAdapter`가 없으므로 바이너리 경로만 쓴다. */
    readonly hasher?: HashAdapter | undefined;
    /** 생략 = 자동 포스터 추출 없음. 호출자가 `poster` 값을 직접 줄 수는 있다. */
    readonly poster?: BinaryPosterAdapter | undefined;
    readonly posterAtMs?: number | undefined;
}): BinaryUploads<TAsset, TCollectionId>;

/**
 * Presign → 네이티브 스트리밍 PUT까지만 수행하고, 나중의 도메인 트랜잭션에 연결할 attachment를 반환한다.
 *
 * `api`에는 `createUploadIntent`만 있으면 된다. 이 함수는 `completeUpload`를 흉내 내거나 호출하지 않는다.
 */
declare function createDeferredLocalUploads<TCollectionId extends string = string>(config: DeferredLocalUploadConfig<TCollectionId>): DeferredLocalUploads<TCollectionId>;

declare function createDeviceLibrary(input: {
    readonly adapter: DeviceLibraryAdapter;
    readonly files: FileSystemAdapter;
    /**
     * ⚠ **필수 인자다**(§3.1 · §7 하드닝 7). 스테이징 사본을 만드는 주체가 지우는 주체를 반드시
     * 갖게 하려는 것이다. 옵셔널로 두면 "카피는 하는데 지우는 사람이 없는" 조립이 컴파일을 통과하고,
     * 업로드한 모든 사진의 원본 사본이 앱 컨테이너에 영구 축적된다 — 타입도 테스트도 못 잡는다.
     */
    readonly staging: StagingCache;
    readonly platform: PlatformAdapter;
    readonly strings?: MediaStrings | undefined;
    readonly debug?: MediaDebugOptions | undefined;
}): DeviceLibrary;

declare function createDeviceUploads<TAsset, TCollectionId extends string = string>(input: {
    readonly device: DeviceLibrary;
    readonly uploads: LocalUploads<TAsset, TCollectionId>;
    readonly staging: StagingCache;
}): DeviceUploads<TAsset, TCollectionId>;

/**
 * Create a durable, app-owned file store from a host storage adapter.
 *
 * The store never trusts caller-supplied paths as complete URIs. It constructs
 * them from individually validated segments, so a cleanup request cannot turn
 * into deletion of a sibling app file through `..`, encoded separators, or a
 * prefix collision.
 */
declare function createDurableFileStore(input: {
    readonly root: string;
    readonly files: DurableFileStoreAdapter;
}): DurableFileStore;

/**
 * `FileSystemAdapter` 위에 base64 창 스트리밍 해시를 조립한다. 기본 `HashAdapter` 구현이다.
 *
 * 해시는 **원본 바이트**에 대해 계산되므로 같은 기기 사진이면 실행 간에도 값이 안정적이다
 * (전신 주석 보존) — 그것이 dedup 키로 쓸 수 있는 이유다.
 */
declare function createFileHasher(input: {
    readonly files: FileSystemAdapter;
}): HashAdapter;

/**
 * Create a saver for files that are already owned by the application.
 *
 * Unlike the remote `createMediaSaver`, this never downloads or deletes source
 * files. It asks the OS for write permission at most once per non-empty batch,
 * and only after confirming that at least one non-empty `file://` source is
 * available.
 */
declare function createLocalMediaSaver(input: {
    readonly files: LocalMediaSaveFileAdapter;
    readonly library: MediaLibrarySaveAdapter;
    readonly strings?: MediaStrings | undefined;
    readonly telemetry?: MediaTelemetry | undefined;
}): LocalMediaSaver;

/**
 * 게이트: `platform.isDev && platform.os !== 'web'` (전신 `debugEnabled()` 보존).
 *
 * 전신의 세 번째 조건이던 "테스트 환경 제외"는 `PlatformAdapter.isDev`가 흡수한다
 * (기본 어댑터가 `__DEV__ && NODE_ENV !== 'test'`로 채운다 — §3.3). 코어에는 그 전역이 없다.
 * `options.enabled`는 호스트의 명시적 스위치이며, 생략하면 전신과 동일하게 플랫폼 게이트만 남는다.
 *
 * ⚠ 게이트가 닫혀 있으면 두 메서드 모두 **완전 no-op**이다 — details를 만드는 비용도 치르지 않는다.
 */
declare function createMediaDebugLogger(input: {
    readonly platform: PlatformAdapter;
    readonly options?: MediaDebugOptions | undefined;
}): MediaDebugLogger;

/**
 * Build an upload-independent camera and library picker flow.
 *
 * This is the right boundary for app-owned workflows such as crop, image analysis, and OCR:
 * it owns OS permissions and untrusted picker-result normalization, while the app owns what it
 * does with the returned local URI.
 */
declare function createMediaPickerActions(input: {
    readonly picker: PickerAdapter;
    readonly strings?: MediaStrings | undefined;
}): MediaPickerActions;

declare function createMediaSaver(input: {
    readonly target: SaveTarget;
    readonly fileNamePrefix?: string | undefined;
    readonly strings?: MediaStrings | undefined;
    readonly telemetry?: MediaTelemetry | undefined;
}): MediaSaver;

declare function createPickerFlows<TAsset, TCollectionId extends string = string>(input: {
    readonly picker: PickerAdapter;
    readonly uploads: LocalUploads<TAsset, TCollectionId>;
    readonly platform: PlatformAdapter;
    readonly strings?: MediaStrings | undefined;
    /**
     * 웹 경로에서 `asset.fileName`이 없을 때 생성되는 폴백 파일명의 접두사.
     * 전신은 uploader의 `fileNamePrefix`를 썼다(uploader.ts:701) — 생략하면 `mediaFileName`
     * 기본값(`'media'`)이 되어 호스트 접두사가 웹 경로에서만 달라진다.
     * 네이티브 경로는 `uploads`가 이미 자기 접두사를 갖고 있으므로 영향받지 않는다.
     */
    readonly fileNamePrefix?: string | undefined;
    /**
     * ⚠ `platform.os === 'web'`에서 피커 자산을 업로드하려면 **필수**. 없으면
     * `MediaError('platform-unsupported')`. 조건부 타입 0 — 런타임 분기다(§3.1).
     *
     * 실측 근거(§5.7.4/V9-d): memorylog2 `app/profile-edit.tsx:137`의 `pickAndUploadPhoto()`에는
     * **플랫폼 게이트가 없다**. 웹에서 그 호출은 전신 uploader.ts:692-710으로 들어가
     * `fetch(asset.uri)` → Blob → `uploadImageBlob({ fallbackExif: asset.exif })`를 탔다.
     * 그 경로를 잃지 않으려면 변환 담당자(`loader`)와 업로더(`uploads`)가 여기 주입돼야 한다.
     */
    readonly web?: {
        readonly uploads: BinaryUploads<TAsset, TCollectionId>;
        readonly loader: BinarySourceLoader;
    } | undefined;
}): PickerFlows<TAsset, TCollectionId>;

declare function createStagingCache(input: {
    /** `/^[a-z0-9][a-z0-9-]{1,30}$/` — 위반 시 `MediaError('config-invalid')`. 부팅 시 즉사. */
    readonly namespace: string;
    readonly files: FileSystemAdapter;
}): StagingCache;

/**
 * PUT에 성공한 뒤, 나중의 앱 트랜잭션에 연결할 수 있도록 돌려주는 오브젝트 메타데이터.
 * `MediaUploadCompletion`과 같은 형태를 써서 앱이 별도 변환 없이 자기 API에 전달할 수 있다.
 */
type DeferredLocalUpload<TCollectionId extends string = string> = MediaUploadCompletion<TCollectionId>;

/**
 * `completeUpload` 없이 presign → 네이티브 PUT까지만 수행하는 설정.
 *
 * 반환된 `DeferredLocalUpload`은 서버 등록 요청처럼 보이게 만든 가짜 값이 아니다. 호출자가
 * 자기 도메인 트랜잭션에서 `objectName`과 메타데이터를 연결할 수 있는 완료 페이로드다.
 */
type DeferredLocalUploadConfig<TCollectionId extends string = string> = MediaUploadBaseConfig<TCollectionId> & LocalStreamingUploadAdapters & {
    readonly api: MediaUploadIntentApi<TCollectionId>;
};

/** `createDeferredLocalUploads`의 최소 능력. 피커 흐름이나 앱 자산 등록은 의도적으로 포함하지 않는다. */
interface DeferredLocalUploads<TCollectionId extends string = string> {
    uploadLocalFile(input: LocalUploadInput<TCollectionId>): Promise<DeferredLocalUpload<TCollectionId>>;
}

type DeviceAlbum = {
    readonly id: string;
    readonly title: string;
    readonly count: number;
};

type DeviceAsset = DeviceAssetRef & {
    readonly uri: string;
    readonly width: number;
    readonly height: number;
    readonly mediaType: MediaKind;
    readonly creationTime?: number | undefined;
};

/**
 * 촬영 시각(ms 에폭) → ISO 문자열. 전신 `deviceAssetCapturedAt`(devicePhotoLibrary.ts:372-378).
 *
 * peer 0인 순수 함수이므로 `"./device"`가 아니라 `"./core"`에 둔다(§5.7.5).
 * ⚠ `creationTime`이 0이면 null이다 — 전신의 falsy 판정을 그대로 보존한다. 에폭 0(1970-01-01)은
 *   기기가 시각을 모른다는 뜻이지 실제 촬영 시각이 아니며, 이것을 ISO로 흘리면 서버의
 *   타임라인 정렬이 1970년으로 끌려간다.
 */
declare function deviceAssetCapturedAt(asset: {
    readonly creationTime?: number | undefined;
}): string | null;

type DeviceAssetInfo = {
    /** 앱 컨테이너 밖(iOS Photos 컨테이너)일 수 있다 — core가 캐시로 실체화한다(§7 하드닝 2). */
    readonly localUri?: string | undefined;
    readonly uri?: string | undefined;
    readonly exif?: Readonly<Record<string, unknown>> | undefined;
    /** true면 원본이 iCloud에만 있다. core 기본 정책은 여기서 중단(§7 하드닝 6). */
    readonly isNetworkAsset: boolean;
};

type DeviceAssetPage = {
    readonly assets: readonly DeviceAsset[];
    /**
     * §1-7 규약(`?: T | undefined`)을 따른다 — 초안은 필수-undefined였다(G20-14).
     * 필수로 두면 3자 어댑터 구현자가 값 없는 마지막 페이지에서도 키를 명시해야 한다.
     */
    readonly endCursor?: string | undefined;
    readonly hasNextPage: boolean;
    readonly totalCount: number;
};

/**
 * 하드닝된 업로드 resolve가 필요로 하는 최소 정체성. 전체 `MediaLibrary.Asset`이 이것을
 * 구조적으로 만족하며, 동기화 큐는 이 두 필드만 저장해 두고 넘길 수 있다
 * (전신 devicePhotoLibrary.ts:21-24 주석 계승).
 */
type DeviceAssetRef = {
    readonly id: string;
    readonly filename: string;
};

interface DeviceLibrary {
    /** 순수 조회. 요청하지 않는다. */
    getPermission(): Promise<MediaPermission>;
    /**
     * 권한 합성 규칙의 **유일한 거처**(§5.4-④(c), G17):
     * 조회 → `!granted && canAskAgain`일 때만 요청 → `accessPrivileges === 'limited'` 매핑
     * (마지막 매핑은 어댑터 몫 — §3.3).
     *
     * ⚠ raw `requestPermission()`은 **공개하지 않는다**. `canAskAgain`을 무시하는 재요청이
     * 정확히 iOS UI 데드록(재요청해도 아무 일도 일어나지 않아 화면이 영원히 기다린다)의 원인이며,
     * 골든패스에 그 문을 두면 반드시 누군가 그 문으로 들어간다. 필요한 소비자는
     * `DeviceLibraryAdapter.requestPermission()`을 직접 쓴다.
     */
    ensurePermission(): Promise<MediaPermission>;
    fetchPage(input?: {
        readonly albumId?: string | null | undefined;
        readonly after?: string | undefined;
        readonly pageSize?: number | undefined;
        readonly kinds?: readonly MediaKind[] | undefined;
    } | undefined): Promise<DeviceAssetPage>;
    /** ⚠ core가 `count > 0` 필터 + count 내림차순 정렬을 **수행한다**(§5.4-④(d)). */
    fetchAlbums(): Promise<readonly DeviceAlbum[]>;
    /**
     * 하드닝된 자산정보 조회 — 그리드/스캐너/업로드가 공유하는 단일 관문(§5.7.5, G9 승격).
     * 기본값은 iCloud 다운로드 없음 + 15s 데드라인, 옵트인 시 60s(§7 하드닝 6).
     * 데드라인 초과는 `MediaError('device-timeout')`이며, 어댑터 실패는 URL·원본 예외를
     * 신뢰하지 않고 새 `MediaError('device-library-failed')`로 정규화한다.
     *
     * ⚠ 이 메서드를 공개하지 않으면 동기화 스캐너가 자체 조회를 짜게 되고, 그 순간 15초 데드라인과
     * `downloadFromNetwork: false` 기본값이 **스캔 경로에서만** 사라진다 — 하드닝 6의 조용한 절반 소멸.
     */
    getAssetInfo(assetId: string, options?: {
        readonly downloadFromICloud?: boolean | undefined;
        readonly infoTimeoutMs?: number | undefined;
        readonly downloadTimeoutMs?: number | undefined;
    } | undefined): Promise<DeviceAssetInfo>;
    /**
     * 원본 바이트 위치만 필요한 경로(동기화 엔진)용. 전신 `resolveDeviceAssetSourceForUpload`.
     * iCloud 가드 · 이중 타임아웃 · iOS 캐시 실체화(§7 하드닝 2·6).
     */
    resolveForUpload(asset: DeviceAssetRef, options?: DeviceResolveOptions | undefined): Promise<ResolvedDeviceAsset>;
    /**
     * 화면 경로용. 전신 `resolveDeviceAssetForUpload`(G4).
     *
     * ⚠ 후보 목록에 `asset.uri`를 **자동으로 덧붙인다**(전신 devicePhotoLibrary.ts:355-359).
     *   최종 순서: `[info.localUri, info.uri, asset.uri, ...options.extraCandidates]`
     *   이 자동 후보가 §7.1 「정보 조회 실패 시 폴백 후보 생존」 규칙을 실제로 발화시키는 값이다 —
     *   전신 주석 "the picker keeps the original asset.uri"(286-288)가 가리키는 정확한 경로다.
     *   저장된 `asset.uri`는 업로드 파이프라인이 읽을 수 없는 `ph://` 참조일 수 있으므로 원본
     *   바이트와 EXIF를 다시 해석한 뒤 피커 형태로 넘긴다(전신 341-343 주석).
     */
    resolvePickedAsset(asset: DeviceAsset, options?: DeviceResolveOptions | undefined): Promise<ResolvedPickedAsset>;
}

interface DeviceLibraryAdapter {
    /**
     * ⚠ Android 13+에서 granular 목록(`['photo','video']`)을 **반드시** 지정할 것. 생략하면
     * 매니페스트의 모든 권한이 대상이 되어, 거부된 `READ_MEDIA_AUDIO`가 유효한 사진·동영상 허용을
     * 거부처럼 보이게 만든다(Android의 "선택한 사진" 접근 모드 포함) — §7 하드닝 5.
     *
     * ⚠ **순수 위임이다.** "언제 요청할 것인가"(현재 권한 조회 → `!granted && canAskAgain`일 때만
     * 요청)는 어댑터가 아니라 core가 소유한다 — `DeviceLibrary.ensurePermission()`(§5.4-④(c), G17).
     * 어댑터에 두면 (i) 3자 어댑터마다 규칙이 갈리고, (ii) iOS에서 `canAskAgain=false`인데 재요청해
     * 아무 일도 일어나지 않는 **UI 데드록**이 재발한다.
     * 어댑터의 몫은 네이티브 응답을 `MediaPermission`으로 매핑하는 것까지다
     * (`accessPrivileges === 'limited'` → `limited: true` 포함).
     */
    requestPermission(): Promise<MediaPermission>;
    /** 순수 조회 — 요청하지 않는다. 합성 규칙은 core가 갖는다(위 참조). */
    getPermission(): Promise<MediaPermission>;
    /**
     * ⚠ **정렬 계약: creationTime 내림차순(최신 우선).** 전신 `devicePhotoLibrary.ts:220`
     *   `sortBy: [[SortBy.creationTime, false]]`.
     * core는 재정렬하지 않는다 — 페이지 단위 재정렬은 전역 순서를 보장하지 못하면서
     * (다음 페이지가 이전 페이지보다 최신일 수 있다) `endCursor`는 여전히 어댑터 순서를 따라가
     * **커서와 표시 순서가 어긋난다**(§5.4-④(d)). 이 계약을 어기면 그리드 순서와 무한스크롤
     * 커서가 함께 깨지며, **타입도 가드도 그것을 잡지 못한다**.
     *
     * ⚠ 자산별 `getAssetInfo` 호출 금지 — 60개 원본을 직렬 해석하면 페이지당 ~20초다.
     * 그리드는 raw uri(iOS `ph://`)를 그대로 그린다. 네이티브 이미지 로더가 PHImageManager에
     * 뷰 크기 썸네일을 요청하므로 시스템 사진 그리드와 같은 방식이 된다. 원본 바이트는
     * 업로드 시점의 resolve에서만 해석한다(§7.1).
     */
    listAssets(input: {
        readonly albumId?: string | null | undefined;
        readonly after?: string | undefined;
        readonly pageSize: number;
        readonly kinds: readonly MediaKind[];
    }): Promise<DeviceAssetPage>;
    /**
     * 원본 목록을 **그대로** 반환한다 — 필터·정렬 금지.
     * `count > 0` 필터와 count 내림차순 정렬은 core가 수행하므로
     * (전신 `devicePhotoLibrary.ts:243-250`의 정책을 core로 승격) 어댑터가 중복 수행할 이유가 없다.
     * 전량을 한 번에 반환하는 in-memory 목록이라 core가 전역 순서를 보장할 수 있다는 점이
     * `listAssets`와의 차이다(§5.4-④(d)).
     */
    listAlbums(): Promise<readonly DeviceAlbum[]>;
    /**
     * ⚠ `downloadFromNetwork`는 **필수 인자**다(§6.1-④). 옵셔널로 두면 어댑터 구현자가
     * 플랫폼 기본값(Expo legacy API는 `true`)을 흘려 iCloud 원본을 무단으로 셀룰러 다운로드한다 —
     * 전신이 실제로 겪은 사고다.
     * 타임아웃(15s / 60s)도 core가 건다 — 어댑터는 순수 위임(§7 하드닝 6).
     */
    getAssetInfo(assetId: string, input: {
        readonly downloadFromNetwork: boolean;
    }): Promise<DeviceAssetInfo>;
}

/**
 * 기기 자산 해석 옵션(§5.4-④).
 *
 * ⚠ `downloadFromICloud` 기본 false — 전신 주석(devicePhotoLibrary.ts:48-50) 그대로다:
 * "사용자가 직접 시작한 수동 업로드만 iCloud 전용 원본 가져오기에 옵트인할 수 있다.
 *  백그라운드 동기화는 예기치 않은 셀룰러 전송을 절대 시작하지 않도록 기본값 false를 유지한다."
 */
type DeviceResolveOptions = {
    readonly downloadFromICloud?: boolean | undefined;
    readonly onICloudDownload?: ((downloading: boolean) => void) | undefined;
    readonly extraCandidates?: readonly (string | null | undefined)[] | undefined;
    readonly infoTimeoutMs?: number | undefined;
    readonly downloadTimeoutMs?: number | undefined;
};

interface DeviceUploads<TAsset, TCollectionId extends string = string> {
    /**
     * ⚠ 순차 실행 고정(위 참조). 업로드 성공·실패와 무관하게 finally에서 `staging.cleanup`을 호출한다 —
     * 누락하면 업로드한 **모든** 사진의 원본 사본이 앱 컨테이너에 영구 축적된다(§7 하드닝 7).
     */
    uploadDeviceAssets(assets: readonly DeviceAssetRef[], options?: (DeviceResolveOptions & {
        readonly collectionId?: TCollectionId | null | undefined;
        readonly max?: number | undefined;
    }) | undefined): Promise<readonly UploadResult<TAsset>[]>;
}

type DurableFile = {
    readonly uri: string;
    readonly sizeBytes: number;
};

/** A URI-safe error emitted by durable attachment storage. */
declare class DurableFileError extends Error {
    readonly code: DurableFileErrorCode;
    constructor(code: DurableFileErrorCode);
}

interface DurableFileStore {
    /** True only for a safe, non-empty file path rooted in this store. */
    owns(uri: string | null | undefined): boolean;
    /** Atomically-enough copy: a failed, empty, or size-mismatched destination is removed before rejection. */
    copy(input: DurableFileStoreCopyInput): Promise<DurableFile>;
    /** Copy a picker result while retaining a supported, validated media extension. */
    copyPickedAsset(input: DurablePickedAssetCopyInput): Promise<DurablePickedAssetFile>;
    /** Best-effort no-op for paths outside this store. */
    remove(uri: string | null | undefined): Promise<void>;
}

/**
 * App-owned persistent-file storage seam.
 *
 * This is deliberately separate from `FileSystemAdapter`: upload code needs a
 * cache directory plus base64 reads, whereas an application attachment store
 * needs a durable root plus directory creation. Keeping the contracts apart
 * avoids making every upload-only adapter pretend it can persist user files.
 */
interface DurableFileStoreAdapter {
    /** App-owned durable root URI. It must identify a directory, or return null when unavailable. */
    rootDirectory(): string | null;
    /** Creates a directory and all missing parents. Repeating the call must be safe. */
    ensureDirectory(uri: string): Promise<void>;
    /** Same discriminated stat contract as the upload file-system seam. */
    stat(uri: string): Promise<FileStat>;
    copy(input: {
        readonly from: string;
        readonly to: string;
    }): Promise<void>;
    /** Idempotent best-effort removal. */
    remove(uri: string): Promise<void>;
}

type DurableFileStoreCopyInput = {
    readonly sourceUri: string;
    /** Nested folders below the configured root. Every segment is validated independently. */
    readonly directory?: readonly string[] | undefined;
    /** The final file name, including any extension the host chose. */
    readonly fileName: string;
};

/**
 * Copy a picker result with a caller-owned stable filename stem.
 *
 * The source filename is metadata, not a safe destination path. The store
 * validates `fileNameStem` as a path segment and appends an extension from the
 * selected asset's supported content type. This prevents an app from silently
 * relabeling every picked asset as `.jpg` while retaining its own stable ID.
 */
type DurablePickedAssetCopyInput = {
    readonly asset: PickedAsset;
    /** Nested folders below the configured root. Every segment is validated independently. */
    readonly directory?: readonly string[] | undefined;
    /** Safe, caller-owned destination filename stem; the store adds the validated extension. */
    readonly fileNameStem: string;
};

type DurablePickedAssetFile = DurableFile & {
    readonly fileName: string;
    readonly contentType: MediaContentType;
};

type ExifCapturedAtOptions = {
    /**
     * Offset saved with the event in minutes east of UTC (KST = 540). When this
     * is omitted, the historical device-local behaviour of
     * `mediaMetadataFromExif` is preserved.
     */
    readonly timeZoneOffsetMinutes?: number | undefined;
};

/**
 * A timezone-less EXIF wall clock. EXIF itself carries no offset, so this is
 * deliberately not a `Date`: callers must choose the policy for mapping it to
 * an instant.
 */
type ExifWallClock = {
    readonly year: number;
    readonly month: number;
    readonly day: number;
    readonly hour: number;
    readonly minute: number;
    readonly second: number;
    readonly millisecond: number;
};

/** 저장 플로우 전용 — 업로드만 하는 소비자는 구현할 필요가 없다. */
interface FileDownloadAdapter {
    download(input: {
        readonly url: string;
        readonly to: string;
    }): Promise<{
        readonly uri: string;
        readonly status: number;
    }>;
}

/**
 * 전신의 `{exists, isDirectory, size}`를 판별 유니언으로 교체.
 * `info.exists && !info.isDirectory ? info.size : 0` 패턴 5중복이 좁히기 한 번으로 소멸한다
 * (§7 하드닝 3).
 */
type FileStat = {
    readonly kind: 'file';
    readonly sizeBytes: number;
} | {
    readonly kind: 'directory';
} | {
    readonly kind: 'missing';
};

interface FileSystemAdapter {
    /** 앱 소유 캐시 디렉토리 URI(끝에 '/'). 없으면 documentDirectory, 그것도 없으면 null. */
    cacheDirectory(): string | null;
    /** ⚠ throw 금지 — 코어가 후보 URI를 순회한다. 없거나 디렉토리면 그 kind를 반환. */
    stat(uri: string): Promise<FileStat>;
    copy(input: {
        readonly from: string;
        readonly to: string;
    }): Promise<void>;
    /** 멱등 삭제. 실패해도 throw 금지 — 스테이징 누수는 디스크 비용일 뿐이다. */
    remove(uri: string): Promise<void>;
    /**
     * `[position, position+length)` 구간을 base64로 반환.
     * ⚠ 코어는 length를 **항상 3의 배수**로 준다(§7 하드닝 9 — 3바이트가 base64 4문자에 대응하므로
     * 3의 배수가 아니면 윈도우 경계에 패딩이 끼어 **해시가 조용히 틀린다**).
     * 어댑터가 범위를 재정렬·병합·확장하면 그 하드닝이 무력화된다.
     */
    readBase64(uri: string, range: ChunkRange): Promise<string>;
}

/** 전신 `PhotoGeoPoint`. */
type GeoPoint = {
    readonly latitude: number;
    readonly longitude: number;
};

/**
 * 기본 구현은 core 내장 순수 TS 증분 SHA-256(§9) — `js-sha256` 제거, 런타임 의존성 0.
 * 네이티브 가속이 필요한 호스트만 교체한다.
 *
 * ⚠ 해시는 dedup **최적화**일 뿐이므로 실패가 업로드를 막지 않는다(§7.1). 그 정책은 코어의
 * `hashSafely()`가 갖는다 — 어댑터는 그냥 throw해도 된다.
 */
interface HashAdapter {
    hashLocalFile(uri: string): Promise<string>;
    hashBinary(source: BinarySource): Promise<string>;
}

/**
 * `instanceof` 대신 이것을 쓴다(§5.2). 엔트리마다 복제된 코어 사본이 만든 에러도 인식한다.
 */
declare function isMediaError(error: unknown): error is MediaError;

/**
 * ⚠ **계약: 파일 바이트를 JS 힙으로 읽지 말 것.** 네이티브 스트리밍 업로드여야 한다.
 *
 * 근거(§7 하드닝 1): `FileSystem.uploadAsync`(레거시 URLSession 브리지)가 iOS 26에서 파일 기반
 * 업로드를 **시작하는 중 프로세스를 종료시킨다** — promise가 reject될 기회조차 없으므로
 * 재시도 로직도 에러 보고도 발화하지 않는다. 크래시 리포트에도 앱 코드 프레임이 남지 않아
 * 원인 추적에만 수일이 걸렸다.
 *
 * expo 기본 어댑터는 `new File(uri).upload(url, { sessionType: 'foreground',
 * uploadType: BINARY_CONTENT })`를 쓴다. `hardening-guard`가 `uploadAsync` 문자열의
 * 재등장을 `src/**` 전역에서 정적 차단한다.
 */
interface LocalFileTransport {
    putLocalFile(input: PutRequest & {
        readonly uri: string;
    }): Promise<{
        readonly status: number;
    }>;
}

/**
 * The only per-item failures this local saver exposes. These are batch
 * outcomes, rather than thrown `MediaError`s: one bad file must not stop later
 * files from being saved. Adapter errors and URIs never escape.
 */
type LocalMediaSaveFailureCode = 'save-local-file-unavailable' | 'save-local-file-failed';

/**
 * The local save path only needs an existence/size check. Requiring the full
 * upload `FileSystemAdapter` would make a save-only consumer implement unused
 * cache, copy, base64-read, and download capabilities.
 */
interface LocalMediaSaveFileAdapter {
    stat(uri: string): Promise<FileStat>;
}

type LocalMediaSaveItemResult = {
    readonly index: number;
    readonly id?: string | undefined;
    readonly status: 'saved';
} | {
    readonly index: number;
    readonly id?: string | undefined;
    readonly status: 'unavailable';
    readonly errorCode: 'save-local-file-unavailable';
} | {
    readonly index: number;
    readonly id?: string | undefined;
    readonly status: 'failed';
    readonly errorCode: 'save-local-file-failed';
};

interface LocalMediaSaver {
    /**
     * Saves app-owned local files in input order. A missing/empty source and an
     * OS save failure are reported per item so one bad item never prevents later
     * files from being attempted. A write-permission failure rejects once with a
     * user-safe `MediaError('save-permission-denied')` before any save attempt.
     */
    saveLocalToDevice(media: readonly LocalSaveableMedia[]): Promise<LocalMediaSaveResult>;
}

type LocalMediaSaveResult = {
    /** Input order is preserved, including unavailable sources. */
    readonly items: readonly LocalMediaSaveItemResult[];
    readonly savedCount: number;
    readonly unavailableCount: number;
    readonly failedCount: number;
};

/**
 * 로컬 URI → 포스터 프레임. 기본 구현은 `"./video"`(expo-video-thumbnails).
 * `BinaryPosterAdapter`와 입력 타입이 다르므로 자리를 바꿔 끼우면 컴파일 에러가 난다 —
 * 브랜드·phantom 각인 없이 오배치가 차단된다.
 */
interface LocalPosterAdapter {
    /** ⚠ 실패는 `null`. 포스터 실패가 동영상 업로드를 막지 않는다(§7.1). */
    posterFromLocalFile(input: {
        readonly uri: string;
        readonly atMs: number;
    }): Promise<{
        readonly uri: string;
    } | null>;
}

/** A host-owned local artifact. `id` is only returned for caller-side correlation. */
type LocalSaveableMedia = {
    readonly uri: string;
    readonly id?: string | undefined;
};

type LocalUploadInput<TCollectionId extends string = string> = {
    readonly uri: string;
    readonly fileName?: string | undefined;
    readonly contentType?: MediaContentType | undefined;
    readonly sizeBytes?: number | undefined;
    /**
     * ⚠ **주어지면 hasher를 호출하지 않는다**(§7.1 신설 행). 전신 `uploadLocalUriToIntent`는 해시를
     * 계산하지 않고 호출자 값을 그대로 전달했다(uploader.ts:57-69의 필드 정의, 440의 전달).
     * 동기화 큐가 재시도 간 해시를 캐시하기 때문이다:
     *   `src/sync/uploadAsset.ts:45-46` — "Reuse the cached hash across retries; only compute
     *   on first attempt" / `item.contentHash ?? (await hash(source.uri))`.
     * 이 필드가 없으면 재시도마다 15MB 파일을 다시 해시한다(순수 TS SHA-256 위에서는 §12-3의
     * Hermes 성능 리스크와 곱해진다).
     *
     * ⚠ 바로 아래 `hashSafely`의 "해시 실패는 업로드를 막지 않는다"와 **나란히** 읽어야 한다 —
     *    한쪽만 보면 정반대 구현이 나온다(§7.1의 경고 그대로).
     */
    readonly contentHash?: string | undefined;
    readonly collectionId?: TCollectionId | null | undefined;
    readonly photo?: MediaMetadata | undefined;
    readonly durationMs?: number | undefined;
    readonly width?: number | undefined;
    readonly height?: number | undefined;
};

interface LocalUploads<TAsset, TCollectionId extends string = string> {
    uploadLocalFile(input: LocalUploadInput<TCollectionId>): Promise<UploadResult<TAsset>>;
    /**
     * 피커 자산 1건 — `PickerFlows`·`DeviceUploads`가 위임한다.
     * ⚠ **네이티브 전용이다.** `platform.os === 'web'`이면 `MediaError('platform-unsupported')`
     * — 로컬 파일 스트리밍은 웹에 존재하지 않는다. 웹 피커 자산의 정본 경로는 §5.7.4다.
     */
    uploadPickedAsset(asset: PickedAsset, options?: {
        readonly collectionId?: TCollectionId | null | undefined;
    } | undefined): Promise<UploadResult<TAsset>>;
}

/**
 * 하나의 스팬. 정확히 한 번만 종료되어야 한다(라이브러리 내부 규율 — 소비자 검증 대상 아님).
 *
 * `cancel`은 "실패가 아닌 중단"이다: 빈 포스터(전신 uploader.ts:268-271)처럼 사용자에게
 * 오류로 보고하면 안 되지만 성공으로 세어서도 안 되는 **3번째 종료 상태**다.
 * 이 상태가 없으면 포스터 추출이 빈 결과를 낸 경우가 성공률 지표에 섞여 들어간다.
 */
interface MediaActivity {
    succeed(finish?: MediaActivityFinish | undefined): void;
    fail(error: unknown, finish?: MediaActivityFinish | undefined): void;
    cancel(finish?: MediaActivityFinish | undefined): void;
}

type MediaActivityFinish = {
    readonly extra?: Readonly<Record<string, unknown>> | undefined;
};

/**
 * 전신 `PhotoDebugLogger`(debug.ts:39-47)를 그대로 계승한다. 초안은 반환 타입만 있고 멤버가 없어
 * 구현자가 임의로 정할 수 있었다 — 그러면 하드닝 8의 새니타이즈 지점이 구현마다 달라진다(G14).
 */
interface MediaDebugLogger {
    log(event: string, details?: Readonly<Record<string, unknown>> | undefined): void;
    /** `errorName` + **새니타이즈된** `errorMessage`를 details에 병합해 기록한다(전신 동작 보존). */
    error(event: string, error: unknown, details?: Readonly<Record<string, unknown>> | undefined): void;
}

/**
 * 디버그 로거 설정. 전신 `PhotoUploaderConfig`의 `debugTag`/`debugContext`에 1:1 대응한다.
 * ⚠ core에는 `__DEV__`가 없으므로 기본값은 **비활성**이다. 실제 게이트는
 * `createMediaDebugLogger`가 `platform.isDev && platform.os !== 'web'`로 건다(§7 하드닝 8).
 */
type MediaDebugOptions = {
    readonly enabled: boolean;
    readonly tag?: string | undefined;
    readonly context?: (() => Record<string, unknown>) | undefined;
};

/**
 * 저장 파일명 = `` `${prefix}-${id || index + 1}.${ext}` `` (전신 saveImages.ts:71).
 *
 * 확장자 우선순위 — **저장된 fileName → contentType → URL 경로 → `'jpg'`**.
 * 전신 주석(saveImages.ts:56-58) 그대로의 근거: "저장된 원본 이름을 우선한다 — 다운로드 URL은
 * 흔히 경로에 확장자가 없는 토큰화된 프록시라, URL을 스니핑하면 모든 PNG/HEIC/동영상
 * 다운로드가 `<prefix>-<id>.jpg`가 되어버린다."
 *
 * ⚠ `index`는 **0-base 필수 인자**다(G8). `id`가 없거나 빈 문자열일 때 `index + 1`이
 * 유일한 구분자이며, 이것이 없으면 여러 장을 저장할 때 파일명이 전부 같아진다 —
 * 브라우저는 `(1)` 접미사로 얼버무리고, MediaLibrary 경로는 캐시 파일을 덮어쓴다.
 */
declare function mediaDownloadFileName(input: {
    readonly url: string;
    readonly index: number;
    readonly id?: string | undefined;
    readonly fileName?: string | undefined;
    readonly contentType?: MediaContentType | undefined;
    readonly prefix?: string | undefined;
}): string;

declare class MediaError extends Error {
    readonly code: MediaErrorCode;
    constructor(code: MediaErrorCode, message: string);
}

/**
 * 전신 `photoErrorUserMessage`.
 * `MediaError`의 message는 이미 사용자 노출 가능 문구다(`MediaStrings` 주입 결과 — §4).
 * 화면은 일반 실패 문구 대신 이 값을 그대로 표시해도 된다.
 */
declare function mediaErrorUserMessage(error: unknown): string | null;

/**
 * 전신의 `defaultMediaFileName`·`inferFileName`·`inferWebFileName` **3종을 하나로 통합**(§5.7.2-③).
 *
 * `fileName`이 있으면 그대로 쓰고, 없으면 `${prefix}-${now}.${ext}`(전신 규칙 보존).
 * ⚠ `now`는 결정론적 테스트를 위한 주입구다 — 생략 시 `Date.now()`로 전신과 동일하게 동작한다
 * (§5.4.1-15). 전신은 `Date.now()`를 직접 호출해 파일명 규칙에 테스트가 없었다.
 * ⚠ `prefix` 기본값은 `'media'`다 — 전신 `'photo'`에서 바꿨다(§5.4.1-13). 호스트는 항상 자기
 * 프리픽스를 주입하므로 이관 영향이 0이며, 라이브러리 이름과의 일관성을 택했다.
 */
declare function mediaFileName(input: {
    readonly fileName?: string | null | undefined;
    readonly contentType: MediaContentType;
    readonly prefix?: string | undefined;
    readonly now?: number | undefined;
}): string;

/**
 * 전신 `isVideoContentType`의 자리를 잇는다(그쪽은 §5.7.2-③에서 내부화 —
 * 동치 대체가 `mediaKindOf(ct) === 'video'`다).
 */
declare function mediaKindOf(contentType: MediaContentType): MediaKind;

interface MediaLibrarySaveAdapter {
    requestWritePermission(): Promise<MediaPermission>;
    saveToLibrary(uri: string): Promise<void>;
    /**
     * Android Expo Go는 사진 권한 요청 자체가 불가 — 그 판정을 어댑터가 정적으로 노출한다
     * (전신 saveImages.ts:96). `expo-constants` 의존을 라이브러리에서 완전히 제거하는 지점(§0.2):
     * `Constants.appOwnership === 'expo'` 판정은 호스트가 하고 값만 넘긴다.
     */
    readonly skipPermissionRequest: boolean;
}

/**
 * 전신 `extractPhotoMetadataFromBlob(blob, fallbackExif, contentType)`(photoMetadata.ts:265-290).
 * 초안이 지웠던 인자 2개를 `options`로 **복원**한다(G6 · §7.1). **4규칙이 계약이다**:
 *   ① 비-JPEG 스킵 — `(contentType ?? source.type)`이 'jpeg'/'jpg'를 포함하지 않으면 파싱하지 않고
 *      fallback을 그대로 반환한다.
 *   ② **필드 단위 병합** — `parsed?.X ?? fallback?.X`. 객체 단위 폴백이 아니다.
 *      capturedAt만 파싱되고 geoPoint는 fallback에서 오는 조합이 **정상 결과**다.
 *   ③ 파싱 예외 시 fallback 반환 — throw 금지. 메타데이터 때문에 업로드가 죽어선 안 된다.
 *   ④ ①②③ 이후에도 유효값이 없으면 `undefined`(빈 객체 금지 — `mediaMetadataFromExif`와 동일).
 *
 * ⚠ 인자를 지우면 웹 피커 경로(`fallbackExif: asset.exif`)에서 JPEG 파싱이 실패했을 때 피커가 준
 * EXIF가 통째로 버려져 촬영시각·위치가 유실된다. 그 유실은 컴파일도 테스트도 통과한다.
 */
declare function mediaMetadataFromJpeg(source: BinarySource, options?: {
    readonly fallbackExif?: ReadonlyExifRecord | null | undefined;
    readonly contentType?: MediaContentType | string | null | undefined;
} | undefined): Promise<MediaMetadata | undefined>;

/**
 * 실패 시 정리 후보인 스토리지 오브젝트.
 *
 * `uploaded`는 2xx 응답까지 확인한 PUT, `possibly-uploaded`는 응답 유실·전송 예외처럼
 * 서버에는 도달했을 수도 있는 PUT이다. 후자도 cleanup endpoint가 멱등으로 처리해야 한다.
 */
type MediaOrphanedUpload = MediaUploadObject & {
    readonly storageState: 'uploaded' | 'possibly-uploaded';
};

type MediaPermission = {
    readonly granted: boolean;
    readonly canAskAgain: boolean;
    /** iOS "선택된 사진" — 일부만 보인다. */
    readonly limited: boolean;
};

interface MediaPickerActions {
    /** Request library permission and return at most `max` normalized assets. */
    pick(options?: MediaPickOptions | undefined): Promise<readonly PickedAsset[]>;
    /** Request camera permission and return at most one normalized asset. */
    capture(options?: {
        readonly kind?: MediaKind | undefined;
    } | undefined): Promise<readonly PickedAsset[]>;
}

type MediaPickOptions = {
    readonly max?: number | undefined;
    readonly kinds?: readonly MediaKind[] | undefined;
};

interface MediaSaver {
    saveToDevice(images: readonly SaveableMedia[]): Promise<SaveResult>;
}

interface MediaStrings {
    /** 자산 정보 조회 15s 데드라인 초과 — `device-timeout`. */
    readonly deviceInfoTimeout: string;
    /** iCloud 원본 다운로드 60s 데드라인 초과 — `device-timeout`. */
    readonly iCloudDownloadTimeout: string;
    /** 원본이 iCloud에만 있고 다운로드 옵트인이 없음 — `device-icloud-only`. */
    readonly iCloudOnly: string;
    /** 로컬 파일 없음/판독 불가 — `device-not-found`. 전신은 hashFile.ts:71과 문구를 공유했다. */
    readonly fileNotFound: string;
    /** 기기 라이브러리 어댑터/OS 호출 실패 — 원본 예외를 공개하지 않는다. */
    readonly deviceLibraryFailed: string;
    /** 피커 어댑터/웹 바이너리 로더 호출 실패 — 원본 예외를 공개하지 않는다. */
    readonly pickerFailed: string;
    /** 이미지 decoder 또는 transform 실패 — URI와 네이티브 원문은 공개하지 않는다. */
    readonly imageProcessingFailed: string;
    readonly unsupportedFileType: string;
    /** 전신 uploader.ts:625 — 드롭/선택 결과에 업로드 가능한 미디어가 없음. */
    readonly noMediaFiles: string;
    /** 전신 uploader.ts:678 — 피커가 준 사진 자산에 uri가 없음. */
    readonly pickedPhotoInvalid: string;
    /** 전신 uploader.ts:717 — 피커가 준 미디어 자산에 uri가 없음. */
    readonly pickedMediaInvalid: string;
    readonly imageSizeUnknown: string;
    readonly videoSizeUnknown: string;
    readonly imageUploadFailed: string;
    readonly videoUploadFailed: string;
    /** 전신 uploader.ts:237, 295 — 포스터(썸네일) PUT 실패. */
    readonly posterUploadFailed: string;
    readonly photoPermissionRequired: string;
    readonly mediaPermissionRequired: string;
    readonly cameraPermissionRequired: string;
    readonly savePermissionDenied: string;
    readonly saveDownloadFailed: string;
    /**
     * `platform-unsupported` — 비네이티브 포크(web·SSR·RSC)에서 네이티브 전용 경로를 호출했을 때.
     * 전신에는 대응 문구가 없다(전신의 web 포크는 영어 `Error`를 던졌다 —
     * devicePhotoLibrary.web.ts:29). 이 코드는 §5.2에서 신설됐는데 §4의 키 목록이 함께
     * 늘지 않아, 초기 구현이 `pickedMediaInvalid`·`fileNotFound`·`saveDownloadFailed` 셋을
     * 돌려 쓰고 있었다 — 전부 원인과 무관한 문구다("파일을 찾을 수 없습니다"는 사용자를
     * 파일 탐색으로 오도한다). 그래서 전용 키로 분리한다.
     */
    readonly platformUnsupported: string;
    /** 크기 초과 — 단위 표기가 언어마다 다르므로 함수. */
    readonly fileTooLarge: (input: {
        readonly maxBytes: number;
        readonly kind: MediaKind;
    }) => string;
}

interface MediaTelemetry {
    /**
     * `run()`을 감싸 성공/예외를 자동 보고한다. 구현은 `run()`의 결과·예외를 그대로
     * return/rethrow해야 한다. 라이브러리는 호스트 텔레메트리를 관측자로 취급하므로,
     * 구현 자체의 예외는 실제 업로드·저장 결과를 바꾸지 않는다.
     */
    track<T>(operation: MediaOperation, extra: Readonly<Record<string, unknown>>, run: () => Promise<T>): Promise<T>;
    begin(operation: MediaOperation, extra?: Readonly<Record<string, unknown>> | undefined): MediaActivity;
}

/**
 * 백엔드 계약: presigned 슬롯을 발급받고, 올라간 오브젝트를 등록한다.
 * `TAsset`은 호스트 API가 저장된 자산으로 반환하는 무엇이든 된다.
 */
interface MediaUploadApi<TAsset, TCollectionId extends string = string> extends MediaUploadIntentApi<TCollectionId> {
    completeUpload(input: MediaUploadCompletion<TCollectionId>): Promise<UploadResult<TAsset>>;
}

/** 바이트가 스토리지에 올라간 뒤 보내는 등록 페이로드. */
type MediaUploadCompletion<TCollectionId extends string = string> = {
    readonly fileName: string;
    readonly contentType: MediaContentType;
    readonly sizeBytes: number;
    readonly objectName: string;
    readonly contentHash?: string | undefined;
    /**
     * 불투명 그룹 id — 킷은 해석하지 않고 전달만 한다(§6.2 기각: `CollectionId` 브랜드).
     * memorylog2는 이것을 `albumId`로 매핑한다. 빈 문자열은 런타임 차단(§6.1-⑪) —
     * falsy 스프레드로 조용히 탈락해 앨범 없이 저장되는 경로를 막는다.
     */
    readonly collectionId?: TCollectionId | undefined;
    readonly photo?: MediaMetadata | undefined;
    readonly durationMs?: number | undefined;
    readonly width?: number | undefined;
    readonly height?: number | undefined;
    readonly poster?: UploadedPoster | undefined;
};

type MediaUploadConfig<TAsset, TCollectionId extends string = string> = MediaUploadBaseConfig<TCollectionId> & {
    readonly api: MediaUploadApi<TAsset, TCollectionId>;
};

/**
 * `mediaUploadFailureInfo(error)`가 돌려주는, cross-entry-safe 실패 복구 정보.
 *
 * 이 정보는 에러에 전역 심볼로 비열거형 각인되므로 code splitting으로 코어 사본이 갈린
 * 엔트리에서도 검사할 수 있다. `orphanedObjects`는 attachment/등록이 끝나기 전에 남은
 * 정리 후보이며, 앱은 자신의 권한 있는 cleanup API로만 처리해야 한다.
 */
type MediaUploadFailureInfo = {
    readonly stage: MediaUploadFailureStage;
    readonly orphanedObjects: readonly MediaOrphanedUpload[];
};

/** 백엔드가 발급한 단일 오브젝트 presigned 업로드 슬롯. */
type MediaUploadIntent = {
    readonly uploadUrl: string;
    readonly method: 'PUT';
    readonly headers: Readonly<Record<string, string>>;
    readonly objectName: string;
};

/**
 * Presign-only backend seam.
 *
 * Some products deliberately attach the uploaded object in a later domain
 * transaction (for example, after creating a record). They must not pretend
 * that a registration endpoint exists just to use the local streaming path.
 * `MediaUploadApi` extends this narrower contract for the usual
 * presign → PUT → complete flow.
 */
interface MediaUploadIntentApi<TCollectionId extends string = string> {
    createUploadIntent(input: MediaUploadIntentRequest<TCollectionId>): Promise<MediaUploadIntent>;
}

type MediaUploadIntentRequest<TCollectionId extends string = string> = {
    readonly fileName: string;
    /** ⚠ 전신은 `string`이었다. 닫힌 8종 유니언으로 좁혀 서버 zod와 클라이언트가 어긋나지 않게 한다. */
    readonly contentType: MediaContentType;
    readonly sizeBytes: number;
    /**
     * 업로드를 시작하기 전에 백엔드가 권한·용량을 확인해야 하는 경우의 불투명 그룹 id.
     * 완료 단계의 `collectionId`와 같은 값이며, 킷은 해석하거나 생성하지 않고 그대로 전달한다.
     * 선택적 필드라 기존 presign-only 소비자는 변경 없이 동작한다.
     */
    readonly collectionId?: TCollectionId | undefined;
};

/**
 * 백엔드 정책을 반영한 클라이언트 크기 캡. 같은 문구로 **빨리** 실패시켜 사용자가 전체 업로드를
 * 마친 뒤 413을 받는 일을 없앤다.
 */
type MediaUploadLimit = {
    readonly maxBytes: number;
    readonly message?: string | undefined;
};

/**
 * ⚠ 팩토리에서 이 값은 **생략 불가**다(§6.1-③). 무제한 업로드는 명시적 결정이어야 한다.
 * 서버만 검증하는 정책도 정당하므로 팩토리 설정은 `MediaUploadLimits | 'server-enforced'`를 받는다
 * (`Number.POSITIVE_INFINITY`는 JSON 직렬화 불가라 기각 — §0.4 기각 8).
 */
type MediaUploadLimits = {
    readonly image?: MediaUploadLimit | undefined;
    readonly video?: MediaUploadLimit | undefined;
};

/**
 * 스토리지에 쓸 수 있는 이름으로 발급된 오브젝트의 안전한 식별 정보.
 *
 * URL·헤더·서명은 의도적으로 없다. 앱은 이 값만 자기 cleanup API에 넘겨, 실패한
 * 업로드가 남긴 object를 best-effort로 정리할 수 있다. `objectName`의 권한 검증은
 * 언제나 서버가 다시 해야 하며, 이 타입은 클라이언트 권한 증명이 아니다. 런타임에서는
 * 1024자 이하 ASCII unreserved 경로 세그먼트(`[A-Za-z0-9._~-]`)와 `/`만 허용한다.
 * URL/query/percent-encoding/공백을 받지 않으므로, 서버는 그 문법을 발급 키에도 맞춰야 한다.
 */
type MediaUploadObject = {
    readonly objectName: string;
    readonly contentType: MediaContentType;
    readonly sizeBytes: number;
};

/** 웹 File의 구조적 최소치 — DOM lib 없이 `isSupportedMediaFile`을 쓰기 위해(§7 하드닝 10). */
interface NamedBinarySource extends BinarySource {
    readonly name: string;
}

type PendingAddResult = {
    /** The next state. Same reference as the input when nothing was added. */
    readonly state: PendingSelectionState;
    /** Items that entered the selection, in input order. */
    readonly added: readonly PendingMediaItem[];
    /**
     * Items that did not enter the selection, in input order, with the reason. Use it for messaging.
     * A `duplicate` entry can be the very object that is already staged (the host re-added it), so
     * do not release this list directly — release `releasable`.
     */
    readonly rejected: readonly PendingRejection[];
    /**
     * Rejected items that are safe to hand to `release`: every rejected item that is not the same
     * object as an item in `state`, each object once, in input order. Their `revoke` has not been
     * called. Picked items and binaries without `revoke` may appear here; `release` ignores them.
     */
    readonly releasable: readonly PendingMediaItem[];
};

/**
 * A binary (web `File`, `Blob`, or any `NamedBinarySource`) staged for a later upload.
 *
 * Core never touches DOM APIs, so the preview resource is injected: `previewUri` is whatever the
 * host can render (typically an object URL) and `revoke` releases it. On web,
 * `pendingItemFromFile` from `@gj-kit/expo-media/web` builds this shape from a DOM `File`.
 */
type PendingBinaryItem = {
    readonly kind: 'binary';
    readonly source: NamedBinarySource;
    /** Renderable preview URI (for example an object URL). Omit when none exists. */
    readonly previewUri?: string | undefined;
    /**
     * Releases the preview resource. The selection calls it **at most once per item object**, when
     * the item leaves a selection through `remove`/`clear`, or when the host passes it to `release`.
     */
    readonly revoke?: (() => void) | undefined;
    /**
     * Modification timestamp (ms epoch) folded into the dedup key, e.g. DOM `File.lastModified`.
     * Without it two binaries with the same name and size are considered the same file.
     */
    readonly lastModified?: number | undefined;
};

/** A picker, camera, or device-library asset staged for a later upload. */
type PendingPickedItem = {
    readonly kind: 'picked';
    readonly asset: PickedAsset;
};

type PendingRejection = {
    readonly item: PendingMediaItem;
    readonly reason: PendingRejectionReason;
};

/**
 * Why an item did not enter the selection.
 * - `duplicate`: an item with the same `keyOf` is already staged (or appeared earlier in the batch).
 * - `over-limit`: the selection already holds `max` items.
 */
type PendingRejectionReason = 'duplicate' | 'over-limit';

interface PendingSelection {
    /** The configured cap. */
    readonly max: number;
    /**
     * Stable identity of an item: `asset:<assetId>` (falling back to the URI when the picker gave
     * no asset id) for picked items, `binary:<name>:<size>:<lastModified>` for binaries.
     */
    keyOf(item: PendingMediaItem): string;
    /**
     * Stage items. Duplicates (by `keyOf`, including duplicates within `items`) are rejected before
     * the cap is checked, so a re-selected photo reports `duplicate` even when the selection is full.
     * Nothing is revoked here; pass the result's `releasable` to `release`. Neither `state` nor
     * `items` is mutated, and the result object and its arrays are frozen.
     */
    add(state: PendingSelectionState, items: readonly PendingMediaItem[]): PendingAddResult;
    /**
     * Drop every item whose `keyOf` equals `key`, calling `revoke` on removed binaries. Returns the
     * same reference when no item matched.
     */
    remove(state: PendingSelectionState, key: string): PendingSelectionState;
    /** Drop every item, calling `revoke` on each binary that still holds a preview resource. */
    clear(state: PendingSelectionState): PendingSelectionState;
    /**
     * Call `revoke` on binaries that are not staged — typically `PendingAddResult.releasable`.
     * Idempotent per item object; picked items and binaries without `revoke` are ignored. Passing an
     * item that is still staged kills its live preview, which is why `rejected` is not the input here.
     */
    release(items: readonly PendingMediaItem[]): void;
    /** Picked assets in selection order — the input of `uploadPickedAsset` / device resolve paths. */
    toPickedAssets(state: PendingSelectionState): readonly PickedAsset[];
    /** Binary sources in selection order — the input of `uploadBinary` / `uploadDropped`. */
    toBinarySources(state: PendingSelectionState): readonly NamedBinarySource[];
    /**
     * URI the host can render, or `null`. Picked assets always preview through their own URI. A binary
     * previews only when it has a `previewUri` **and** is not HEIC/HEIF — browsers cannot decode those,
     * and an `<img>` that never loads looks like a broken upload.
     */
    previewUriOf(item: PendingMediaItem): string | null;
    /** `previewUriOf(item) !== null`. */
    canPreview(item: PendingMediaItem): boolean;
    /**
     * Capture time as an ISO string, or `null`. Picked items read the picker EXIF dictionary; binaries
     * parse the JPEG APP1 segment from bytes (the same parsers the upload path uses). Never throws.
     */
    capturedAtOf(item: PendingMediaItem): Promise<string | null>;
}

type PendingSelectionOptions = {
    /** Maximum number of staged items. Must be a positive integer; otherwise `MediaError('config-invalid')`. */
    readonly max: number;
