 */
type AuthErrorCode = 'invalid-key-prefix' | 'session-disposed';

/**
 * An auth session (design §3.5): storage binding (signIn/signOut), single-flight refresh with
 * cross-tab adoption, retry-once request wrapping and the proactive refresh scheduler.
 *
 * ⚠ The single flight is **per instance** — create exactly one per app (a module-scope
 * singleton is the recommended shape, §7-6).
 */
interface AuthSession {
    /** The stored access token (bearer injection belongs to the app's HTTP layer — §6-1). */
    getAccessToken(): Promise<string | null>;
    getTokens(): Promise<TokenPair | null>;
    /**
     * Persist tokens and schedule the proactive refresh. (Calling the login API is app-owned.)
     *
     * - `persistence` is **required**: `clearTokens`/`signOut` reset the mode to the
     *   implementation default, so an optional here would let "session login → signOut →
     *   option-less re-login" silently promote to durable — betraying the shared-PC user who
     *   chose a session login. The library does not know the product's persistence policy, so a
     *   default would be a lie (§4.1-⑥). Only internal rotations use the mode-sticky omission
     *   (H14).
     * - `accessTtlSeconds`: the login response's `expires_in` — first-priority TTL source for
     *   the initial schedule (§3.5 priority ①).
     */
    signIn(tokens: TokenPair, options: {
        readonly persistence: TokenPersistence;
        readonly accessTtlSeconds?: number | undefined;
    }): Promise<void>;
    /** Cancel the schedule and clear tokens. Idempotent. */
    signOut(): Promise<void>;
    /**
     * Single flight (H4): concurrent calls on this instance share one in-flight result. With a
     * lock, the critical section is serialized across tabs (H5). After acquiring the lock the
     * storage is re-read: if it was already rotated the pair is adopted without consuming it
     * (H2b), and after a failed request a re-read that finds a rotation also adopts (H2).
     * A `'rotated'` result is persisted only while the attempted pair is still the stored one
     * (the H3 discipline applied to the success path): a signOut/signIn or another tab's write
     * that raced the in-flight request wins — the outcome becomes `'signed-out'`/`'adopted'`
     * and the stale rotation is discarded. `'refreshed'`/`'adopted'` return only after
     * rescheduling completed.
     *
     * Lock-boundary invariant (§3.5): the critical section spans from the post-lock re-read
     * (H2b) through persisting the result — `setTokens` for `'rotated'`, `clearTokens` for a
     * confirmed invalid (H3) — and the lock is NOT released before persistence completes.
     * Releasing earlier would let the next tab's post-lock re-read observe the pre-rotation
     * state and replay a consumed single-use token.
     */
    refresh(): Promise<RefreshOutcome>;
    /**
     * Eager refresh on foreground return (H9). Refreshes only when the remaining lifetime is
     * ≤ `thresholdSeconds` (default 120). When the lifetime is unknown (non-JWT and no strategy)
     * it returns `'not-needed'` — preserving the predecessor's behavior. The return union is the
     * named type {@link EagerRefreshOutcome} (§3.4).
     */
    refreshIfExpiringSoon(options?: {
        readonly thresholdSeconds?: number | undefined;
    }): Promise<EagerRefreshOutcome>;
    /**
     * 401 → refresh → retry exactly once (H6), structurally: the retry execution cannot re-enter
     * the refresh path (the predecessor's `allowRefresh` boolean recursion is unrepresentable).
     * `run` receives the access token current at each attempt (an expired header can never be
     * replayed — H6). Flow: `run(current token)` → it throws `e` → if
     * `shouldRetryAfterRefresh(e)` and a token existed, `refresh()` → on
     * `'refreshed'`/`'adopted'` run once with the new token — that result is final (value or
     * throw). Any other outcome (`'invalid'`/`'transient'`/`'signed-out'`) rethrows the original
     * `e` — on transient the tokens are untouched, so upstream retry policy takes over (H1).
     */
    runAuthorized<T>(run: (accessToken: string | null) => Promise<T>, options: {
        /** Classifies "expired 401" in the app's error vocabulary. Required — no default (§4.1-④). */
        readonly shouldRetryAfterRefresh: (error: unknown) => boolean;
    }): Promise<T>;
    /**
     * (Re)arm the proactive refresh timer from the stored tokens. Hosts call this right after
     * boot restore. Empty storage cancels instead of arming — the fallback TTL applies only to
     * a present token whose expiry is unknown, so a never-signed-in app gets no timer and no
     * spurious background `'signed-out'` outcome.
     */
    scheduleRefresh(): Promise<void>;
    cancelScheduledRefresh(): void;
    /** Release the timer; every later method call throws `AuthError('session-disposed')`. */
    dispose(): void;
}

type AuthSessionOptions = {
    readonly storage: TokenStorage;
    readonly refresh: RefreshRequest;
    /** Cross-tab serialization (H5). When omitted, only the in-instance single flight applies (sufficient on native). */
    readonly lock?: RefreshLock | undefined;
    /** Defaults to the system clock. Tests inject `createManualClock` from `"./testing"` (§5.1). */
    readonly clock?: AuthClock | undefined;
    /**
     * Access token → remaining lifetime in seconds, or null when unknown. Defaults to the
     * strategy based on {@link decodeJwtExpiryEpochSeconds}. Hosts with opaque (non-JWT) tokens
     * supply their own strategy here.
     */
    readonly accessTokenTtlSeconds?: ((accessToken: string) => number | null) | undefined;
    readonly schedule?: RefreshScheduleOptions | undefined;
    /**
     * Notification of outcomes for refreshes the scheduler performed in the background. Not
     * called for caller-initiated `refresh()` (that caller already knows via the return value).
     * On `'invalid'` it is the host's call whether to navigate to sign-in — the library hands an
     * outcome here too, it does not "fire a logout event". `'transient'` carries `cause` (the
     * callback-throw diagnostic, §3.4) — the telemetry's only window into classifier bugs.
     */
    readonly onScheduledOutcome?: ((outcome: RefreshOutcome) => void) | undefined;
};

/**
 * Create an auth session (design §3.5). The name is `createAuthSession`, not
 * `createTokenRefreshCoordinator`: the returned object owns storage binding and the scheduler
 * lifecycle, not just refresh coordination.
 */
declare function createAuthSession(options: AuthSessionOptions): AuthSession;

/**
 * Token summary for logging/telemetry — contains not a single byte of the token itself (§4.2).
 * `expiresAtEpochSeconds` comes from {@link decodeJwtExpiryEpochSeconds} and shares its
 * unverified-decode caveat.
 */
declare function describeAccessToken(accessToken: string): {
    readonly length: number;
    readonly expiresAtEpochSeconds: number | null;
};

/** Result of `refreshIfExpiringSoon` — the named home of the sixth ending, `'not-needed'` (§3.4·§3.5). */
type EagerRefreshOutcome = RefreshOutcome | {
    readonly status: 'not-needed';
};

/**
 * Exhaustive matcher over the five endings. TypeScript does not force exhaustiveness on raw
 * `switch`/`if` (§4.1-③ — `assertNever` is only an opt-in pattern), so the library ships a
 * consumption form where a missing handler key is a **compile error**.
 */
declare function matchRefreshOutcome<T>(outcome: RefreshOutcome, handlers: {
    readonly refreshed: (outcome: Extract<RefreshOutcome, {
        status: 'refreshed';
    }>) => T;
    readonly adopted: (outcome: Extract<RefreshOutcome, {
        status: 'adopted';
    }>) => T;
    readonly 'signed-out': (outcome: Extract<RefreshOutcome, {
        status: 'signed-out';
    }>) => T;
    readonly invalid: (outcome: Extract<RefreshOutcome, {
        status: 'invalid';
    }>) => T;
    readonly transient: (outcome: Extract<RefreshOutcome, {
        status: 'transient';
    }>) => T;
}): T;

/**
 * Serializes the refresh critical section across tabs/instances (H5, design §3.2).
 * The web default implementation is `createWebLocksRefreshLock` from `"./storage"` (§3.8),
 * which falls back to direct execution where the Web Locks API is unavailable.
 */
interface RefreshLock {
    acquire<T>(run: () => Promise<T>): Promise<T>;
}

/**
 * The five endings of `refresh()` (design §3.4). The library cleans storage where required but
 * never navigates or resets app state — that is the caller's decision.
 *
 * - `'refreshed'`: this instance performed the rotation. Persisted and rescheduled.
 * - `'adopted'`: storage now holds a valid pair **different** from the entry snapshot and that
 *   pair was adopted (H2·H2b). Rescheduled. ⚠ Adoption does NOT guarantee the same subject —
 *   another tab's signOut→sign-in-as-someone-else also appears as `'adopted'`. Hosts where
 *   account switching is possible must re-confirm the subject (e.g. re-fetch /me) after
 *   adopting (§7-13).
 * - `'signed-out'`: storage holds no refresh token (already signed out).
 * - `'invalid'`: a definitive server rejection. `tokensCleared` follows the H3 discipline —
 *   `true` only when the attempted token was still the stored one. The caller decides whether
 *   to navigate to the sign-in screen.
 * - `'transient'`: undecidable. Tokens are preserved — never a sign-out (H1). `cause` carries
 *   the value thrown by the refresh callback (§3.3 fail-safe diagnostics channel), or is
 *   `undefined` when the callback reported `'transient'` normally. Retry policy belongs to the
 *   caller (React Query and friends).
 */
type RefreshOutcome = {
    readonly status: 'refreshed';
    readonly tokens: TokenPair;
} | {
    readonly status: 'adopted';
    readonly tokens: TokenPair;
} | {
    readonly status: 'signed-out';
} | {
    readonly status: 'invalid';
    readonly tokensCleared: boolean;
} | {
    readonly status: 'transient';
    readonly cause?: unknown;
};

/** The host-owned refresh callback (design §3.3). */
type RefreshRequest = (input: {
    readonly refreshToken: string;
}) => Promise<RefreshRequestResult>;

/**
 * The host calls its own HTTP stack against its refresh endpoint and translates the response
 * into this three-way classification (design §3.3):
 *
 * - `'rotated'`: the server issued a new token pair. `tokens` is required — omitting it is a
 *   compile error (§4.1-②).
 * - `'invalid'`: a definitive rejection (401/403 — token revoked or expired). The session ended.
 * - `'transient'`: the server could not decide (network error, 5xx, CORS, timeout). The tokens
 *   may still be valid.
 *
 * ⚠ If the callback throws, the core treats it as `{ status: 'transient', cause: <thrown value> }`:
 * a classifier bug must not fail toward signing the user out (fail-safe in the H1 direction),
 * and the thrown value is preserved as `cause` so it is never silently swallowed — it flows to
 * the caller's return value and to `onScheduledOutcome`, letting host telemetry distinguish a
 * classifier bug from network flapping (§3.4). `cause` is a structured field; the library never
 * stringifies it, so this does not conflict with §4.2.
 */
type RefreshRequestResult = {
    readonly status: 'rotated';
    readonly tokens: TokenPair;
    /** Access-token lifetime in seconds, as stated by the server. When present it takes priority over JWT `exp` decoding (§3.6). */
    readonly accessTtlSeconds?: number | undefined;
} | {
    readonly status: 'invalid';
} | {
    readonly status: 'transient';
};

/** Proactive-refresh scheduling knobs (design §3.5). All defaults preserve H7. */
type RefreshScheduleOptions = {
    /** How many seconds before expiry to refresh. Default 90 (H7). */
    readonly leadSeconds?: number | undefined;
    /** Minimum timer delay. Default 30_000 (H7 — prevents instant re-fire storms for nearly expired tokens). */
    readonly minDelayMs?: number | undefined;
    /** Assumed TTL in seconds when the expiry is unknown. Default 840 = 14 minutes (H7). */
    readonly fallbackTtlSeconds?: number | undefined;
    /**
     * Cap (ms) for the exponential backoff of consecutive `'transient'` retries. Default 300_000
     * (5 minutes). The n-th consecutive transient retries after
     * `min(minDelayMs × 2^(n−1), transientMaxDelayMs)`; the counter resets on
     * `'refreshed'`/`'adopted'`/`signIn` — this replaces the predecessor's fixed-30s infinite
     * retry loop, which was a self-DoS against the auth endpoint (§7-8).
     */
    readonly transientMaxDelayMs?: number | undefined;
};

/** An access/refresh token pair. Both members are required — half states never leave storage (H12). */
type TokenPair = {
    readonly accessToken: string;
    readonly refreshToken: string;
};

/**
 * Storage seam (design §3.1). Implementation contract:
 *
 * - `getTokens` returns a pair only when BOTH tokens are present; half states converge to
 *   `null` (H12 — a torn write reads as "signed out", never as corrupt data).
 * - `getTokens` **freshness**: inside the refresh critical section (§3.5) a read must reflect
 *   the last write committed by any other tab/instance — the precondition of the H2b adoption
 *   and the H3 comparison. An in-memory cache is only allowed where no external writer exists
 *   (native single process — §3.8); the web implementation is read-through.
 * - `setTokens` with `persistence` omitted keeps the current mode (H14 — a rotation after a
 *   session login must not silently promote tokens to durable). The initial default is
 *   implementation-defined.
 * - `clearTokens` is idempotent and resets the persistence mode to the implementation default.
 * - No method may throw an error whose message contains a token string (§4.2).
 */
interface TokenStorage {
    getTokens(): Promise<TokenPair | null>;
    setTokens(tokens: TokenPair, options?: {
        readonly persistence?: TokenPersistence | undefined;
    }): Promise<void>;
    clearTokens(): Promise<void>;
}

/**
 * Cross-tab refresh serialization over the Web Locks API (H5). Where `navigator.locks` is
 * unavailable — including native, where this lock is therefore harmless to wire
 * unconditionally (§3.9) — `acquire` executes `run` directly, preserving the predecessor's
 * fallback. On lock-less browsers the tab race on single-use refresh tokens remains and the
 * H2 adoption path cleans up after it (§7-3) — the same exposure the predecessor had.
 */
declare function createWebLocksRefreshLock(options: {
    /** Required. An origin-global name — using the same value as `keyPrefix` is recommended (§4.1-①). */
    readonly name: string;
}): RefreshLock;

/** Options of the platform-neutral `createTokenStorage` factory (design §3.8). */
type TokenStorageOptions = {
    /**
     * Required — e.g. `'myapp.auth'`. The predecessor leaked its host app name through a
     * hardcoded prefix; this library refuses to own any default (§4.1-①). Empty or
     * whitespace-only values throw `AuthError('invalid-key-prefix')` (§4.1-ⓐ).
     */
    readonly keyPrefix: string;
    /** Persistence mode used before any explicit choice exists. Default `'durable'`. */
    readonly defaultPersistence?: TokenPersistence | undefined;
};

/** Create a manual clock (design §5.1). Time starts at `startMs` (default 0) and only moves via `advance`. */
declare function createManualClock(options?: {
    readonly startMs?: number | undefined;
}): ManualClock;

/**
 * Create an in-memory token storage (design §5.1). Reads are always read-through (a
 * `simulateExternalRotation` is visible to the very next `getTokens` — the §3.1 freshness
 * clause), `setTokens` without `persistence` keeps the current mode (H14), and `clearTokens`
 * resets the mode to `'durable'`, the implementation default.
 */
declare function createMemoryTokenStorage(initial?: {
    readonly tokens?: TokenPair | undefined;
    readonly persistence?: TokenPersistence | undefined;
}): MemoryTokenStorage;

/**
 * A {@link RefreshRequest} that answers from a fixed script, recording every call. A call past
 * the end of the script throws — surfacing as a test failure (via the session it appears as a
 * `'transient'` outcome carrying that error as `cause`, §3.3).
 */
declare function createScriptedRefreshRequest(script: readonly RefreshRequestResult[]): {
    readonly request: RefreshRequest;
    readonly calls: readonly {
        readonly refreshToken: string;
    }[];
};

/**
 * An UNSIGNED test JWT (`header.payload.` with an empty signature) — exp fixture generation
 * for the default TTL strategy. The name says it: there is no signature, and
 * `decodeJwtExpiryEpochSeconds` would not verify one anyway (§3.6).
 */
declare function createUnsignedTestJwt(claims: Readonly<Record<string, unknown>>): string;

/** Serialization-observing {@link RefreshLock}; `hold`/`releaseNext` reproduce H2b lock-wait races. */
type FakeRefreshLock = RefreshLock & {
    /** Highest number of concurrently held critical sections observed (H5 asserts === 1). */
    readonly maxObservedConcurrency: number;
    /** After `hold()`, each `acquire` waits at its grant point until `releaseNext()` — the "rotation while waiting for the lock" scenario. */
    hold(): void;
    /** Release one held acquirer (or bank a credit if none is waiting yet). */
    releaseNext(): void;
};

/** Deterministic {@link AuthClock}: `advance` fires elapsed timers and drains microtasks. */
type ManualClock = AuthClock & {
    /** Move time forward, firing due timers in order and letting their async chains settle. */
    advance(ms: number): Promise<void>;
    /** Observability: number of currently armed timers (asserting "timer stopped" outcomes). */
    readonly pendingTimerCount: number;
};

/** In-memory {@link TokenStorage} with cross-tab simulators. Practical in SSR and app tests too. */
type MemoryTokenStorage = TokenStorage & {
    /** Simulate another tab's rotation — the only way to reproduce the H2/H2b/H3 scenarios. */
    simulateExternalRotation(tokens: TokenPair): void;
    /** Simulate another tab clearing storage (sign-out elsewhere). */
    simulateExternalClear(): void;
    /** Observability: the current persistence mode (asserting H14 stickiness). */
    readonly persistence: TokenPersistence;
    /** Observability: number of underlying reads (asserting H2b/H3 re-read counts and H10 caching). */
    readonly readCount: number;
};

/**
 * Android: scope -> `android.permission.health.*`, 방향별로.
 * `'routes'`의 READ는 **절대 포함하지 않는다** — 플랫폼이 조용히 걸러내고 설정 화면이나 per-route
 * 다이얼로그에서만 부여된다(f110, f121). `history`는 READ 쪽에 실린다(D10).
 */
declare function androidRequestPermissions(request: AuthorizationRequest): DirectedPermissions;

/**
 * 런타임 요청 집합. `'routes'`의 READ는 **절대 포함하지 않는다** — 플랫폼이 조용히 걸러내고
 * 설정 화면이나 per-route 다이얼로그에서만 부여된다(f110, f121).
 */
declare function androidRuntimeRequestPermissions(request: AuthorizationRequest): readonly string[];

interface AndroidWorkout extends WorkoutBase {
    readonly platform: 'android';
    readonly platformData: AndroidWorkoutData;
}

/** Raw Android values the common model deliberately does not model. */
interface AndroidWorkoutData {
    /** Raw ExerciseSessionRecord.exerciseType. */
    readonly exerciseType: number;
    readonly packageName: string;
    readonly recordingMethod: number;
    readonly deviceType?: number | undefined;
    /**
     * The writer's own client record id. Foreign apps' values ARE visible here — treat it as PUBLIC
     * data, never as a private namespace.
     */
    readonly clientRecordId?: string | undefined;
    readonly clientRecordVersion?: number | undefined;
    readonly endUtcOffsetMin?: number | undefined;
    /** Foreign-app authored text. This library never writes a title or notes. */
    readonly title?: string | undefined;
    readonly notes?: string | undefined;
    /** Every segment, including REST (44), which `pauses` deliberately excludes. PAUSE is 39. */
    readonly segments: readonly {
        readonly type: number;
        readonly startMs: number;
        readonly endMs: number;
    }[];
}

/**
 * Call it from a `switch` default so a future code becomes a compile error for you.
 * ⚠ This is only honest because the code union is CLOSED for 1.x: adding a code is a major.
 */
declare function assertNeverWorkoutsCode(code: never): never;

/** 스냅샷에서 상태를 도출할 때 필요한 부가 사실. 전부 optional이며 없으면 보수적으로 판정한다. */
interface AuthorizationDerivationFacts {
    /**
     * 방금 끝난 **결론적인** 요청에서 사용자가 실제로 거부한 플랫폼 문자열. `before`/`after` 비교의
     * 결과이며(f120이 강제하는 유일한 정직한 판정 근거), 요청이 `conclusive: false`였다면 **비어
     * 있어야 한다** — 그때 scope 상태는 불변이다.
     */
    readonly denied?: readonly string[] | undefined;
}

/** Input for the pure derivation, so a second consumer can re-derive it from facts it stored earlier. */
interface AuthorizationFacts {
    readonly state: AuthorizationState;
    /** The scopes THIS screen actually needs — may be narrower than everything the build declares. */
    readonly requiredRead: readonly Scope[];
    readonly requiredWrite?: readonly Scope[] | undefined;
    readonly requiresHistory?: boolean | undefined;
}

interface AuthorizationRequest {
    /**
     * Coarse form — one token, and the recipe to copy:
     * `read: [...WORKOUT_TOTALS_SCOPES, 'routes']`.
     * Fine form — name the members: `read: ['workouts', 'heartRate']`.
     *
     * ⚠ A metric scope without `'workouts'` is `invalidArgument`. `read: ['distance']` alone is a
     *   100 % mistake — no API in this library reads distance except through a workout — so `./core`
     *   rejects it before any platform call.
     */
    readonly read: readonly Scope[];
    readonly write?: readonly Scope[] | undefined;
    /**
     * D10, opt-in. Android only. Without it, reads are walled to the last 30 days and a wider window
     * throws `historyRequired`. It ALSO needs the config-plugin `history: true` prop; requesting it
     * without the manifest entry throws `invalidArgument` naming the missing prop.
     */
    readonly history?: boolean | undefined;
}

/**
 * `requestAuthorization`'s result: the state afterwards, plus whether we can attribute it to the
 * user. `conclusive: false` means the OS returned an answer we cannot attribute — on Android,
 * bouncing off Health Connect's first-run onboarding with "Go back" returns an EMPTY permission set
 * after ~20 s, byte-identical to denying everything. Treat it as "ask again later", NEVER as denial.
 */
type AuthorizationResult = AuthorizationState & {
    readonly conclusive: boolean;
};

/**
 * 인가 스냅샷. **판정은 하지 않는다** — 원시 사실만 넘긴다.
 * iOS: `authorizationStatus`(공유) + `statusForAuthorizationRequest`(시트 여부).
 * Android: `getGrantedPermissions()` + `processImportance()` + `declaredPermissions()`.
 */
interface AuthorizationSnapshotDto {
    readonly platform: WorkoutsPlatform;
    readonly availability: AvailabilityDto;
    /** Android: granted permission strings. iOS: share-authorized HK type identifiers. */
    readonly granted: readonly string[];
    /**
     * iOS only, and the reason `write.*` can say `'denied'` rather than a permanent `'undetermined'`:
     * `HKHealthStore.authorizationStatus(for:)` per DECLARED type identifier, already reduced to our
     * vocabulary (`sharingAuthorized` -> `'granted'`, `sharingDenied` -> `'denied'`,
     * `notDetermined` -> `'undetermined'`). It is a SHARE-side fact only — HealthKit never reports a
     * read status, which is exactly why every iOS read scope is permanently `'unknown'`.
     * `null` on Android, where the direction is encoded in the permission string and `granted` is
     * already the whole truth.
     */
    readonly statuses?: Readonly<Record<string, 'granted' | 'denied' | 'undetermined'>> | null | undefined;
    /** Manifest / Info.plist 선언 집합. 선언되지 않은 scope 요청은 `invalidArgument`가 된다. */
    readonly declared: readonly string[];
    /** iOS only: a sheet would still appear for at least one requested type. */
    readonly wouldPrompt: boolean;
    /** Android only: the process is at IMPORTANCE_FOREGROUND (a hard precondition for foreign routes). */
    readonly foreground: boolean;
    /** AOSP `getExerciseRouteReadAccessType`, already reduced to our vocabulary. iOS: always `'all'`. */
    readonly routeAccess: RouteAccess;
    /** Android READ_HEALTH_DATA_HISTORY. `null` on iOS — that platform has no wall. */
    readonly history: boolean | null;
}

/**
 * Availability and authorization fused into ONE union. Reading a scope's status on a platform that
 * has no usable health store is **unrepresentable** rather than merely discouraged.
 */
type AuthorizationState = {
    readonly availability: 'unavailable';
    readonly reason: 'platformTooOld' | 'notSupported';
} | {
    readonly availability: 'updateRequired';
} | {
    readonly availability: 'available';
    /** Every scope is always present — no `undefined` holes to guard. */
    readonly read: Readonly<Record<Scope, ScopeStatus>>;
    readonly write: Readonly<Record<Scope, ScopeStatus>>;
    /** Android READ_HEALTH_DATA_HISTORY. Always `'unknown'` on iOS — that platform has no wall,
     *  and reporting a grant the user never gave would be a lying field. */
    readonly history: ScopeStatus;
    readonly routeAccess: RouteAccess;
};

type Availability = {
    readonly status: 'available';
} | {
    readonly status: 'unavailable';
    readonly reason: 'platformTooOld' | 'notSupported';
}
/** Android 9–13 without the Play Health Connect provider. Pair with `openStoreListing()`. */
 | {
    readonly status: 'updateRequired';
};

type AvailabilityDto = {
    readonly status: 'available';
} | {
    readonly status: 'unavailable';
    readonly reason: 'platformTooOld' | 'notSupported';
} | {
    readonly status: 'updateRequired';
};

/**
 * Concatenate a `getRoute()` stream into one array. Convenience only: a 36 000-point route costs
 * ~15 MB of JS heap, which is why the stream is the default and this is the opt-in.
 */
declare function collectRoute(chunks: AsyncIterable<readonly RoutePoint[]>): Promise<RoutePoint[]>;

/** `createWorkoutsApi`의 주입 지점. 전부 테스트가 시간·예산을 소유하기 위한 것이다. */
interface CreateWorkoutsApiOptions {
    readonly now?: (() => number) | undefined;
    /**
     * 클라이언트측 읽기 페이서. 기본값은 **Android에서만** 켜진 `ReadBudget` 하나이고
     * (f102의 계수는 Health Connect의 것이며 HealthKit에는 대응물이 없다), `null`이면 끈다.
     */
    readonly budget?: ReadBudget | null | undefined;
    /** per-route 동의 다이얼로그 상한 (f104). 테스트가 짧은 값으로 hang을 재현한다. */
    readonly routeConsentTimeoutMs?: number | undefined;
}

interface CursorInfo {
    /** OUR format version, not the platform token's. */
    readonly formatVersion: number;
    readonly platform: WorkoutsPlatform;
    readonly issuedAtMs: number;
}

type CursorResetReason = 
/** `cursor === null` — a fresh start. */
'noCursor'
/** Bad magic / bad base64url / bad JSON / failed shape validation. */
 | 'malformed'
/** Magic ok, format version not in `READABLE_CURSOR_VERSIONS`. */
 | 'formatUnsupported'
/** Minted on the other platform (server-synced cursor, device switch, restore). */
 | 'platformMismatch'
/** Android: `ChangesResponse.changesTokenExpired === true` (30-day idle). */
 | 'expired'
/** The granted-scope fingerprint differs from the one baked into the cursor. */
 | 'scopesChanged';

interface DeleteRefDto {
    readonly nativeId?: string | null | undefined;
    readonly clientId?: string | null | undefined;
}

interface DeleteResult {
    /** `false` for an id that was not there. Deleting something absent is never an error. */
    readonly deleted: boolean;
}

/** `read`/`write` 두 방향의 플랫폼 문자열. `native-contract.ts`의 `PermissionRequestDto`와 같은 모양. */
interface DirectedPermissions {
    readonly read: readonly string[];
    readonly write: readonly string[];
}

/** 드레인 한 배치. `checkpoint`는 **이 배치를 만들기 전에** 잡힌 값이다. */
interface DrainBatchDto {
    readonly added: readonly WorkoutDto[];
    readonly removed: readonly RemovedDto[];
    readonly checkpoint: string;
    readonly hasMore: boolean;
    /** Android `ChangesResponse.changesTokenExpired`. */
    readonly expired: boolean;
}

/**
 * Exact Health Connect record-size model, fitted with residual 0 over six failure samples:
 *   `bytes = 160 + 48·routePoints + 2·(title + notes + clientRecordId chars) + 24·(segments + laps)`
 *
 * The optional route fields are FREE — a 21 000-point route serialises to the byte-identical size
 * with and without altitude and accuracies.
 *
 * Pinned boundary (f99): a 13-char title + 13-char clientRecordId gives `bytes = 212 + 48·points`,
 * and 20 829 points is exactly 1 000 004 B — the first failing size.
 *
 * ⚠ One Mainline build's parcel encoding. A safety margin, not a contract.
 */
declare function estimateAndroidRecordBytes(input: {
    readonly routePoints: number;
    readonly clientRecordIdLength: number;
    readonly titleLength?: number | undefined;
    readonly notesLength?: number | undefined;
    readonly segments?: number | undefined;
    readonly laps?: number | undefined;
}): number;

interface ExistingWorkoutDto {
    readonly nativeId: string;
    readonly version: number;
}

interface GetRouteOptions {
    /**
     * What to do when `routeState === 'consentRequired'` (Android only — HealthKit has no per-route
     * consent).
     * - `'skip'` (default) — throw `consentRequired`. Never shows UI, never blocks.
     * - `'prompt'`         — show the platform's per-route dialog and, if the user allows, stream the
     *   route from that same call. Can block for tens of seconds, so it must be driven by an explicit
     *   user gesture. Only one prompt may be in flight per process; a concurrent call throws `busy`.
     */
    readonly consent?: 'skip' | 'prompt' | undefined;
}

interface HeartRateDto {
    readonly t: number;
    readonly bpm: number;
}

/** One heart-rate reading. The same shape on read and on write. */
interface HeartRateSample {
    /** Epoch MILLISECONDS. */
    readonly t: number;
    /** Integer beats per minute, 1..300. Samples outside that range are dropped on write. */
