/**
 * Byte quantity with an explicit unit system. `system: 'decimal'` divides by
 * 1000 and labels KB/MB; `system: 'binary'` divides by 1024 and labels
 * KiB/MiB — the label always tells the truth about the divisor.
 */
declare function formatBytes<TFallback = string>(value: number | null | undefined, options: FormatBytesOptions<TFallback>): string | TFallback;

type FormatBytesOptions<TFallback = string> = {
    /** Required: `'1.5 GB'` vs `'1.5GB'` — the source apps disagreed. */
    readonly unitSpace: boolean;
    /**
     * Required policy for zero and negative input — the source apps disagreed and
     * the difference is visible: admin renders `'0 B'`/`'-5 B'`, mobile treats
     * anything `<= 0` as "size unknown" and hides the chip.
     * `'render'` formats the value; `'fallback'` returns `fallback`.
     */
    readonly nonPositive: 'render' | 'fallback';
    /**
     * How trailing zeros are handled. Default `'keep'`.
     * - `'keep'`       renders `'1.0 GB'` — fixed column width (`toFixed`).
     * - `'trim'`       renders `'1GB'` — drops trailing zeros after rounding.
     * - `'trim-exact'` drops the fraction only when the value was an exact
     *                  integer *before* rounding, so `1.04 GB` still renders
     *                  `'1.0GB'`. This is not the same as `'trim'`; it is what
     *                  `Number.isInteger(v) ? v : v.toFixed(1)` does.
     */
    readonly trailingZeros?: 'keep' | 'trim' | 'trim-exact' | undefined;
    /** Values >= this (in the chosen unit) render as integers (e.g. 10 gives `'12MB'`). */
    readonly wholeNumberFrom?: number | undefined;
    /** Rendered for null/undefined/non-finite input, and for non-positive input
     *  when `nonPositive` is `'fallback'`. Default `'-'`. */
    readonly fallback?: TFallback | undefined;
} & ({
    /** Decimal SI: 1 KB = 1000 B. Unit labels KB/MB/.../PB. */
    readonly system: 'decimal';
    /**
     * Exact fraction digits above the B unit — a single value, or a per-unit
     * map when the policy differs by unit. Default 1.
     * The per-unit form exists because a real source app rounds MB to whole
     * numbers while giving GB/TB one decimal, and no numeric threshold can
     * separate those two ranges (both span 1-999 in their own unit).
     */
    readonly fractionDigits?: ByteFractionDigits | Partial<Record<FormatDecimalByteUnit, ByteFractionDigits>> | undefined;
    readonly minUnit?: FormatDecimalByteUnit | undefined;
    readonly maxUnit?: FormatDecimalByteUnit | undefined;
} | {
    /** Binary: 1 KiB = 1024 B. Unit labels KiB/MiB/.../PiB. */
    readonly system: 'binary';
    readonly fractionDigits?: ByteFractionDigits | Partial<Record<FormatBinaryByteUnit, ByteFractionDigits>> | undefined;
    readonly minUnit?: FormatBinaryByteUnit | undefined;
    readonly maxUnit?: FormatBinaryByteUnit | undefined;
});

interface FormatDateOptions<TFallback = string> {
    /** Required. See {@link FormatTimeZone} — omission is a compile error. */
    readonly timeZone: FormatTimeZone;
    /**
     * Required separator between year/month/day segments.
     * The source apps disagreed (`2026-06-08` vs `2026.06.08`), so neither
     * spelling is a silent default.
     */
    readonly separator: '-' | '.';
    /**
     * Rendered for null/undefined/invalid input and for instants outside the
     * supported window `0001-01-01T14:00:00Z … 9999-12-31T09:59:59.999Z`.
     *
     * That window — not "years 1–9999" — is the actual guard: it is the set of
     * instants every zone this package accepts (-12:00…+14:00) renders as a year
     * between 1 and 9999, so the IANA path and the `'UTC'`/`'device'` paths agree
     * byte for byte on where the range ends. `2026-06-08` in any zone is far
     * inside it; only the two end years are narrowed by a day.
     *
     * Default `'-'`.
     */
    readonly fallback?: TFallback | undefined;
}

/**
 * Elapsed milliseconds as Korean text: `'0.8초'`, `'5분'`, `'1.2시간'`.
 * Takes a duration, not two timestamps — clock-free like the rest of the family.
 */
declare function formatDurationKo<TFallback = string>(milliseconds: number, options?: FormatDurationKoOptions<TFallback>): string | TFallback;

/**
 * Elapsed-time copy. The admin source took two timestamps and parsed them; this
 * takes the duration itself, so the family stays clock-free and the subtraction
 * stays at the call site where the two instants already are.
 */
interface FormatDurationKoOptions<TFallback = string> {
    /** Rendered for NaN/negative/non-finite input. Default `'-'`. */
    readonly fallback?: TFallback | undefined;
}

/**
 * Thrown for configuration and environment errors only. Data problems — null,
 * invalid dates, NaN, unparsable strings — never throw; they render `fallback`.
 */
declare class FormatError extends Error {
    readonly code: FormatErrorCode;
    constructor(code: FormatErrorCode, message: string);
}

/** Stable machine-readable codes. Never emitted for data problems. */
type FormatErrorCode = 
/** Configuration error: `timeZone` is not 'UTC' | 'device' | a zone name the
 *  runtime's Intl accepts. A programmer can fix this. */
'ERR_TIMEZONE_INVALID'
/** Configuration error: `locale` is not a tag the runtime's Intl accepts
 *  (`'ko_KR'`, `'en US'`, `'ko-KR-'`). `FormatLocale` accepts any string, so
 *  this is the runtime half of that axis. A programmer can fix this. */
 | 'ERR_LOCALE_INVALID'
/** Configuration error: `minimumFractionDigits`/`maximumFractionDigits` is not
 *  an integer in 0–100, or the minimum exceeds the maximum. A programmer can
 *  fix this. */
 | 'ERR_FRACTION_DIGITS_INVALID'
/** Environment error: the runtime's Intl failed this package's self-test —
 *  it ignores the `timeZone` option, or ignores `hourCycle`/`hour12`.
 *  A programmer cannot fix this; ask {@link canFormatTimeZone} up front. */
 | 'ERR_INTL_UNUSABLE'
/** Environment error: a single-field formatter produced a non-numeric or
 *  out-of-range string for this specific zone. */
 | 'ERR_INTL_FIELD_OUTPUT';

interface FormatKrwOptions<TFallback = string> {
    /**
     * Required rendering style — the source apps disagreed:
     * `'symbol'` renders `'₩1,000'`, `'suffix-ko'` renders `'1,000원'`.
     */
    readonly style: 'symbol' | 'suffix-ko';
    /**
     * Required **grouping** locale; `'device'` is the explicit opt-in to the
     * runtime default. It selects grouping and the decimal separator only — the
     * `₩` glyph, its position and the `원` suffix are fixed by this package and
     * never vary with the locale.
     */
    readonly locale: FormatLocale;
    /** Rendered for null/undefined/non-finite input. Default `'-'`. */
    readonly fallback?: TFallback | undefined;
}

interface FormatNumberOptions<TFallback = string> {
    /** Required grouping locale; `'device'` opts into the runtime default. */
    readonly locale: FormatLocale;
    /** Default: Intl's own default (max 3). */
    readonly maximumFractionDigits?: number | undefined;
    readonly minimumFractionDigits?: number | undefined;
    /** Rendered for null/undefined/non-finite input. Default `'-'`. */
    readonly fallback?: TFallback | undefined;
}

interface FormatPercentOptions<TFallback = string> {
    /** Required grouping locale — grouping and decimal separator only. */
    readonly locale: FormatLocale;
    /** Exact fraction digits. Default 0 (`'63%'`). */
    readonly fractionDigits?: 0 | 1 | 2 | undefined;
    /** Rendered for null/undefined/non-finite input. Default `'-'`. */
    readonly fallback?: TFallback | undefined;
}

/** Structured relative-time classification; render copy yourself or via formatRelativeKo. */
type FormatRelativeBucket = 
/** `ms` counts milliseconds *until* the value, always positive. */
{
    readonly kind: 'future';
    readonly ms: number;
} | {
    readonly kind: 'just-now';
    readonly seconds: number;
} | {
    readonly kind: 'minutes';
    readonly count: number;
} | {
    readonly kind: 'hours';
    readonly count: number;
} | {
    readonly kind: 'days';
    readonly count: number;
} | {
    readonly kind: 'months';
    readonly count: number;
} | {
    readonly kind: 'years';
    readonly count: number;
};

type FormatRelativeKoOptions = {
    /** Required explicit clock — this family never reads the system clock itself. */
    readonly now: Date;
    /** Required: `true` → `'3분 전'`, `false` → `'3분전'`. The apps disagreed. */
    readonly suffixSpace: boolean;
    /** Required: rendered for null/invalid input. The apps disagreed (`''` vs `'-'`). */
    readonly fallback: string;
    /**
     * Required policy for timestamps after `now`:
     * `'empty'` returns `''`; a function renders an absolute form instead.
     */
    readonly onFuture: 'empty' | ((date: Date) => string);
    /** Label for the <60s bucket. Default `'방금'`. */
    readonly justNowLabel?: string | undefined;
    /** When set, the 1-day bucket renders this literal (e.g. `'어제'`) instead of `'1일 전'`. */
    readonly yesterdayLabel?: string | undefined;
} & ({
    readonly maxDays?: undefined;
    readonly onOverflow?: undefined;
} | {
    /** Elapsed days >= maxDays switch to onOverflow (e.g. 7 → absolute date). */
    readonly maxDays: number;
    /** Required together with maxDays — there is no built-in absolute rendering. */
    readonly onOverflow: (date: Date) => string;
});

/** Usage as a 0-1 fraction, or null when the limit is missing/zero/invalid.
 *  Arithmetic, not rendering — pair it with {@link formatPercent}. */
declare function storageRatio(used: number | null | undefined, limit: number | null | undefined): number | null;

/**
 * Heterogeneous collection element type. `any` is deliberate: `run` is
 * contravariant in `Input`, so `OperationsJob<unknown>` would reject every
 * concrete job. Consumers never construct this type; the registry does.
 */
type AnyOperationsJob = OperationsJob<any>;

/**
 * Adapts Nest's `LoggerService` (message-first) to the `JobLogger` port
 * (fields-first). The structured fields are passed through as an extra
 * parameter, which Nest's own console logger prints alongside the message.
 */
declare function fromNestLogger(logger: LoggerService, context?: string): JobLogger;

interface JobCatalogEntry {
    readonly key: string;
    readonly description: string;
    readonly schedule: JobSchedule | null;
    readonly schedulerHttpSync: boolean;
    readonly overlapPolicy: JobOverlapPolicy;
    /** Effective timeout: the job's own value or the supplied default. */
    readonly timeoutMs: number;
    readonly acceptsInput: boolean;
}

/**
 * Injected time source. Every runner decision that depends on time — the
 * deadline, the heartbeat cadence, how long a failing heartbeat is tolerated,
 * and `durationMs` — reads this and nothing else. `now()` is epoch milliseconds
 * because that is what the store port carries, so no date object is ever
 * constructed outside this module. Staleness is not on this list: the cutoff
 * belongs to the store's clock, not the runner's (obligation S6).
 *
 * This is the only module in the package allowed to touch ambient time or timers.
 */
interface JobClock {
    /** Epoch milliseconds. */
    now(): number;
    /** Fires once after `delayMs`. */
    after(delayMs: number, handler: () => void): JobTimerCancel;
    /** Fires repeatedly every `intervalMs`. */
    every(intervalMs: number, handler: () => void): JobTimerCancel;
}

interface JobExecuteOptions {
    /**
     * Aborts the job in addition to the deadline — e.g. graceful shutdown.
     *
     * A signal that is **already aborted** short-circuits before the reap and the
     * claim: `execute` throws `ERR_JOB_ABORTED`, no row is written and the body
     * never runs. Work the host explicitly declined to start must not produce side
     * effects, nor a FAILED run row for an operator to chase.
     */
    readonly signal?: AbortSignal | undefined;
}

type JobExecutionResult = (JobExecutionBase & {
    readonly status: 'SUCCEEDED';
    readonly summary?: JobSummary | undefined;
}) | (JobExecutionBase & {
    readonly status: 'FAILED';
    readonly summary?: JobSummary | undefined;
    readonly error: OperationsJobsError;
}) | (JobExecutionBase & {
    readonly status: 'TIMED_OUT';
    readonly error: OperationsJobsError;
}) | (JobExecutionBase & {
    readonly status: 'SKIPPED';
    readonly reason: JobSkipReason;
});

/**
 * Structural input validator. A Zod schema satisfies this shape as-is
 * (`ZodType.parse(value: unknown): Output`), and so do valibot wrappers,
 * ArkType morphs and hand-written functions. The library never imports a
 * validation library: it only calls `parse` and treats any throw as invalid input.
 */
interface JobInputValidator<Input> {
    parse(value: unknown): Input;
}

/**
 * Structured logging port. The argument order is fields-first, matching pino
 * and nestjs-pino, so a `PinoLogger` instance satisfies this port as-is.
 * Nest's own message-first `LoggerService` is adapted by `fromNestLogger`
 * on the `.` subpath.
 */
interface JobLogger {
    info(fields: Record<string, unknown>, message: string): void;
    warn(fields: Record<string, unknown>, message: string): void;
    error(fields: Record<string, unknown>, message: string): void;
}

interface JobRegistry extends JobRegistryView {
    /** Rejects malformed keys, duplicate keys and malformed schedule metadata. */
    register(job: AnyOperationsJob): void;
}

/** Read side used by the runner and by catalog projections. */
interface JobRegistryView {
    get(key: string): AnyOperationsJob | undefined;
    /** Sorted by key, so catalogs and admin listings are stable. */
    list(): readonly AnyOperationsJob[];
}

interface JobRunClaim {
    readonly runId: string;
}

interface JobRunClaimRequest {
    readonly jobKey: string;
    /**
     * Opaque overlap token. The store must treat it as a bare string: uniqueness
     * among RUNNING rows is the entire contract, and the runner owns how it is
     * derived from the job's overlap policy.
     */
    readonly overlapKey: string;
    readonly trigger: JobTrigger;
    /** Already validated by the runner. Persist as JSON, or `null` when absent. */
    readonly input: unknown;
    /**
     * Epoch milliseconds from the runner's injected clock, recorded verbatim (S6).
     * The store additionally initialises the run's liveness watermark from its own
     * clock, which is the value `reapStale` compares against — see S6.
     */
    readonly startedAt: number;
    readonly serviceRevision?: string | null | undefined;
}

interface JobRunCompleteRequest {
    readonly runId: string;
    readonly status: JobTerminalStatus;
    /** Epoch milliseconds from the runner's injected clock, recorded verbatim (S6). */
    readonly finishedAt: number;
    readonly durationMs: number;
    readonly summary?: JobSummary | undefined;
    /** Already truncated by the runner. Never returned to an HTTP caller. */
    readonly error?: string | undefined;
}

/**
 * Deliberately carries no timestamp: the liveness watermark is the store's own
 * clock (S6). A caller-supplied instant would sit on one of N runner clocks
 * while the reaper compares it on another — the one comparison that decides
 * whether a job body runs twice.
 */
interface JobRunHeartbeatRequest {
    readonly runId: string;
    readonly progress?: JobSummary | undefined;
}

interface JobRunner {
    /**
     * Run one job end to end.
     *
     * Throws only when this runner will not finalise a row: unknown key
     * (`ERR_JOB_UNKNOWN`), rejected input (`ERR_JOB_INPUT_INVALID` /
     * `ERR_JOB_INPUT_UNEXPECTED`), a caller signal that was already aborted before
     * the run started (`ERR_JOB_ABORTED`) or a store failure while claiming
     * (`ERR_JOB_STORE`). The first three leave no row at all; a claim that committed
     * before its response was lost can leave an orphan RUNNING row that the next
     * reap settles. Every outcome that ran the body — including failure and
     * timeout — is returned, never thrown, with `recorded` saying whether the
     * stored row agrees with the returned `status`.
     */
    execute(jobKey: string, body: unknown, trigger: JobTrigger, options?: JobExecuteOptions): Promise<JobExecutionResult>;
    /**
     * Abandon stale RUNNING rows across every key, using the runner's
     * `staleRunAfterMs`. For a host-owned sweeper job: `execute` only reaps around
     * the key it is about to claim, so a job that is never triggered again needs
     * this to release its orphaned rows.
     *
     * A store failure raises `ERR_JOB_STORE`, like every other store call in this
     * package — the driver's own error never escapes.
     */
    reapStaleRuns(options?: {
        readonly limit?: number | undefined;
    }): Promise<number>;
}

interface JobRunnerOptions {
    readonly registry: JobRegistryView;
    readonly store: JobRunStore;
    /** Required: a silent runner hides exactly the failures this package exists to surface. */
    readonly logger: JobLogger;
    readonly clock?: JobClock | undefined;
    /**
     * Beat cadence, defaulting to {@link DEFAULT_HEARTBEAT_INTERVAL_MS}.
     *
