type JobTriggerSource = 'SCHEDULER' | 'CLI' | 'ADMIN' | (string & {});

/**
 * Host-provided token verification. The library ships no cloud SDK: an adapter
 * over `google-auth-library`'s `verifyIdToken`, a JWKS client or an internal
