 * `./testing`의 `jobRunStoreContractCases()`가 그 문장을 실행 가능한 검사로 바꾼다.
 */
type JobRunStatus = 'RUNNING' | 'SUCCEEDED' | 'FAILED' | 'TIMED_OUT' | 'SKIPPED';

/** Cron metadata. Documentation and scheduler-sync input; the runner never reads it. */
interface JobSchedule {
    /** 5 or 6 whitespace-separated fields. Shape-checked at boot, not semantically parsed. */
    readonly cron: string;
    /** IANA time zone name. Validated at boot with `Intl.DateTimeFormat`. */
    readonly timeZone: string;
}

interface JobTrigger {
    readonly source: JobTriggerSource;
    readonly triggeredBy?: string | null | undefined;
}

interface JobTriggerAuthOptions {
    /** Shared secret. At least 32 characters; shorter values are a construction error. */
    readonly secret?: string | undefined;
    readonly tokenVerifier?: JobTriggerTokenVerifier | undefined;
}

interface JobTriggerIdentity {
    readonly method: 'secret' | 'token';
    /** Who the token proved the caller to be, e.g. a service account email. */
    readonly subject?: string | undefined;
}

/**
 * Who triggered the run. The listed values are conventions with completion
 * support; any other string is accepted because trigger sources are host facts.
 */
type JobTriggerSource = 'SCHEDULER' | 'CLI' | 'ADMIN' | (string & {});

/**
 * Host-provided token verification. The library ships no cloud SDK: an adapter
 * over `google-auth-library`'s `verifyIdToken`, a JWKS client or an internal
 * mTLS-derived identity all satisfy this port.
 *
 * Return `null` for "not authenticated". Throwing is reserved for verifier
 * outages, which the guard reports as 503 rather than 401.
 */
interface JobTriggerTokenVerifier {
    verify(token: string): Promise<JobTriggerIdentity | null>;
}

/**
 * Operations job contract. A job owns business logic only — authentication,
 * overlap prevention, timeouts, run records and logging belong to the runner.
 *
 * Returning a summary whose `ok` is exactly `false` marks the run FAILED while
 * preserving the summary, so an external scheduler retries and alerting fires.
 * Any other value of `ok` (including `0`, `''`, `undefined`) is a success.
 */
interface OperationsJob<Input = void> {
    /** Unique key shaped `domain.action`, lower-case and hyphenated, at most 100 chars. */
    readonly key: string;
    readonly description: string;
    /** Absent means the job takes no input; a non-empty request body is then rejected. */
    readonly inputSchema?: JobInputValidator<Input> | undefined;
    /** Defaults to {@link DEFAULT_JOB_TIMEOUT_MS}. */
    readonly timeoutMs?: number | undefined;
    /**
     * Defaults to `'forbid'`: a second trigger while one run holds the key is SKIPPED.
     *
     * Overlap prevention buys liveness with a bounded safety gap: a runner that is
     * stalled rather than dead has its row reaped, and a second body then starts.
     * The window is one heartbeat interval plus the job's abort reaction time, and
     * while the store itself is unreachable it widens to `staleRunAfterMs` plus
     * that reaction time. Only the job's own domain-level idempotency closes it.
     */
    readonly overlapPolicy?: JobOverlapPolicy | undefined;
    /** Documentation and scheduler-sync metadata only. `null` means "no declared cron". */
    readonly schedule?: JobSchedule | null | undefined;
    /** Defaults to true. False means an external non-HTTP trigger owns this schedule. */
    readonly schedulerHttpSync?: boolean | undefined;
    run(input: Input, context: OperationsJobContext): Promise<JobSummary | void>;
}

interface OperationsJobContext {
    readonly runId: string;
    readonly jobKey: string;
    readonly trigger: JobTrigger;
    readonly logger: JobLogger;
    /**
     * Aborted when the deadline passes, when the runner loses its claim, or when
     * the caller's own signal aborts. The abort reason is an
     * `OperationsJobsError`. Long batch loops must check it.
     *
     * The library guarantees that the signal aborts at the right instant, that the
     * settling record is written exactly once, and that a body outliving its
     * deadline cannot corrupt that record. It cannot guarantee that side effects
     * stop: a job that ignores this signal keeps writing.
     */
    readonly signal: AbortSignal;
    /** Epoch milliseconds at which the run times out, from the injected clock. */
    readonly deadlineAt: number;
    /**
     * Refresh the heartbeat immediately, optionally recording intermediate progress.
     *
     * Resolves `false` when this run no longer holds its claim — it was reaped as
     * stale or already settled — and the job should stop. After the runner has
     * settled the run this is a no-op that resolves `false` without touching the
     * store, so a job that outlives its deadline can never overwrite the record.
     *
     * A failed store write is logged and resolves `true`: one transient error must
     * not be read as "claim lost". Sustained failure is not forgiven, though —
     * once nothing has been written for `staleRunAfterMs`, the runner aborts the
     * run with `ERR_JOB_ABORTED` exactly as if the store had answered `false`,
     * because by then another instance is entitled to reap this run's row.
     */
    heartbeat(progress?: JobSummary): Promise<boolean>;
}

/**
 * The only error type this package throws.
 *
 * `message` carries the job key and the reason and nothing else — consumer data,
 * stack traces and validation-library output live on `cause`, which never
 * reaches an HTTP response.
 */
declare class OperationsJobsError extends Error {
    readonly code: OperationsJobsErrorCode;
    readonly jobKey?: string | undefined;
    readonly runId?: string | undefined;
    constructor(code: OperationsJobsErrorCode, message: string, options?: OperationsJobsErrorContext & {
        readonly cause?: unknown;
    });
}

/**
 * 에러 코드 체계 — HTTP 매핑(`src/nest/http.ts`)과 CLI exit code의 유일한 입력.
 * 코드는 공개 계약이므로 추가는 additive, 제거·의미 변경은 breaking change다.
 */
/** Stable error codes. Every failure this package reports carries exactly one. */
type OperationsJobsErrorCode = 
/** No job registered under this key. */
'ERR_JOB_UNKNOWN'
/** Jobs are still being collected (Nest bootstrap has not finished). */
 | 'ERR_JOB_REGISTRY_NOT_READY'
/** Malformed or over-long job key (boot). */
 | 'ERR_JOB_KEY_INVALID'
/** Two jobs claim the same key (boot). */
 | 'ERR_JOB_DUPLICATE_KEY'
/** Malformed job object (boot). */
 | 'ERR_JOB_INVALID'
/** Malformed cron shape or unknown time zone (boot). */
 | 'ERR_JOB_SCHEDULE_INVALID'
/** The job's validator rejected the body. */
 | 'ERR_JOB_INPUT_INVALID'
/** A body was sent to a job that takes none. */
 | 'ERR_JOB_INPUT_UNEXPECTED'
/** The deadline passed. */
 | 'ERR_JOB_TIMEOUT'
/** Claim lost or unverifiable, or the caller's signal aborted. */
 | 'ERR_JOB_ABORTED'
/** The body threw, or reported `ok: false`. */
 | 'ERR_JOB_FAILED'
/** The run store failed. */
 | 'ERR_JOB_STORE'
/** Trigger authentication failed. */
 | 'ERR_JOB_UNAUTHORIZED'
/** No authentication configured (wiring). */
 | 'ERR_JOB_AUTH_MISCONFIGURED';

interface OperationsJobsErrorContext {
    readonly jobKey?: string | undefined;
    readonly runId?: string | undefined;
}

interface SchedulerHttpTarget {
    readonly key: string;
    readonly description: string;
    /** `${baseUrl}/${routePrefix}/${key}/run` with duplicate slashes collapsed. */
    readonly uri: string;
    readonly httpMethod: 'POST';
    readonly cron: string;
    readonly timeZone: string;
    /**
     * `ceil(timeoutMs / 1000) + margin` — the job must finish first.
     *
     * Never clamped down to `maxAttemptDeadlineSeconds`: a target that gives up
     * before the runner does is a contradiction, not a compromise, so
     * {@link schedulerHttpTargets} raises `ERR_JOB_INVALID` instead of emitting one.
     */
    readonly attemptDeadlineSeconds: number;
}

interface SchedulerHttpTargetOptions {
    /** Absolute http(s) origin, no trailing slash required. */
    readonly baseUrl: string;
    /** Defaults to `'internal/jobs'`; must match the trigger controller's path. */
    readonly routePrefix?: string | undefined;
    /** Defaults to 60_000. Head room between the job deadline and the HTTP deadline. */
    readonly attemptDeadlineMarginMs?: number | undefined;
    /**
     * Defaults to 1_800 seconds. That number is the most common documented ceiling
     * rather than a statement about any one scheduler — hosts on a different
     * platform pass their own.
     *
     * A job whose deadline plus margin does not fit under it raises
     * `ERR_JOB_INVALID` naming the key: either lower that job's `timeoutMs` or
     * raise this ceiling to whatever the platform actually allows.
     */
    readonly maxAttemptDeadlineSeconds?: number | undefined;
}

/**
 * Node timers plus the ambient wall clock. Timers are unref'd where the runtime
 * supports it, so a pending heartbeat never keeps a CLI process alive.
 */
declare function systemJobClock(): JobClock;

/**
 * Deterministic clock. `advance` fires every timer due in the interval, in order.
 * `startMs` defaults to a fixed literal, never to the ambient wall clock: this
 * package reads ambient time in `src/core/clock.ts` and nowhere else.
 */
declare function fakeJobClock(startMs?: number): FakeJobClock;

interface FakeJobClock extends JobClock {
    /** Fires every timer due within the interval, in order, awaiting microtasks between. */
    advance(ms: number): Promise<void>;
    readonly pendingTimers: number;
}

interface JobRunStoreContractCase {
    /** e.g. `'S1: a second claim on the same overlap key returns null'`. */
    readonly name: string;
    readonly obligation: JobRunStoreObligation;
    /** Throws with a message naming the violated obligation. */
    readonly run: (store: JobRunStore) => Promise<void>;
}

interface JobRunStoreContractOptions {
    /** Skip cases an implementation legitimately cannot support, with a reason. */
    readonly skip?: readonly JobRunStoreObligation[] | undefined;
    /**
     * Read one row back. `JobRunStore` has no reader, so the cases that can only
     * be observed through stored values — S6's recorded timestamps, S7's JSON
     * round trip — are omitted unless a host supplies this. Everything else,
     * including all of S1-S4, is observable through the port alone.
     */
    readonly inspect?: ((runId: string) => Promise<StoredJobRun | undefined>) | undefined;
    /**
     * How many concurrent calls the S1 burst case issues. Defaults to 8. The host
     * must point this suite at a connection pool of at least 2: a single-connection
     * client serialises the burst and hides a non-atomic claim.
     */
    readonly concurrency?: number | undefined;
}

/**
 * S1–S7 의무의 실행 가능한 형태. 스키마를 소유하지 않는 대가 — 호스트 구현이 계약을
 * 어겨도 라이브러리가 모른다 — 를 **호스트의 테스트 스위트 안에서** 닫는 장치다.
 */
type JobRunStoreObligation = 'S1' | 'S2' | 'S3' | 'S4' | 'S5' | 'S6' | 'S7';

interface MemoryJobRunStore extends JobRunStore {
    /** Side-effect-free inspection; returns defensive copies. */
    runs(): readonly StoredJobRun[];
    runOf(runId: string): StoredJobRun | undefined;
}

interface MemoryJobRunStoreOptions {
    readonly newId?: (() => string) | undefined;
    /**
     * The store's own clock — the liveness axis of S6. Defaults to the system
     * clock. Pass the same `fakeJobClock` the runner uses to make staleness
     * deterministic, or a second one to simulate clock skew.
     */
    readonly clock?: JobClock | undefined;
}

interface RecordedLogEntry {
    readonly level: 'info' | 'warn' | 'error';
    readonly fields: Record<string, unknown>;
    readonly message: string;
}

interface RecordingJobLogger extends JobLogger {
    readonly entries: readonly RecordedLogEntry[];
}

interface StoredJobRun {
    readonly runId: string;
    readonly jobKey: string;
    readonly overlapKey: string | null;
    readonly status: JobRunStatus;
    readonly trigger: JobTrigger;
    readonly input: unknown;
    readonly summary: JobSummary | undefined;
    readonly error: string | undefined;
    /** Epoch ms, exactly as the runner supplied it (S6, recording axis). */
    readonly startedAt: number;
    /**
     * Epoch ms on the **store's** clock (S6, liveness axis): set when the run is
     * claimed, advanced by every accepted heartbeat, compared by `reapStale`.
     * Never null — a null watermark is unreapable and holds the overlap key forever.
     */
    readonly heartbeatAt: number;
    /** Epoch ms. The runner's value for a completed run, the store's for a reaped one. */
    readonly finishedAt: number | undefined;
    readonly durationMs: number | undefined;
    readonly serviceRevision: string | null;
}

interface AppendItemInput {
    readonly applicationKey: string;
    readonly deliveryId: string;
    readonly sourceOutboxId: string;
    readonly at: Date;
}

/** The five columns whose combination must be unique per delivery (R5). */
interface BatchIdentity {
    readonly applicationKey: string;
    readonly recipientRef: string;
    readonly batchKey: string;
    readonly batchWindowStartedAt: Date;
    readonly batchPolicyKey: string;
}

interface ClaimedNotificationCommand {
    readonly id: string;
    readonly applicationKey: string;
    readonly recipientRef: string;
    readonly actorRef: string | null;
    readonly targetRef: string | null;
    readonly category: string;
    /** A plain string: narrow it with `notificationPriorityFrom`. */
    readonly priority: string;
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
    readonly eventKey: string;
    readonly batchKey: string | null;
    readonly batchLabel: string | null;
    readonly batchItemCount: number;
    readonly timing: NotificationTiming;
    /**
     * When this row entered the ingress outbox. The library never writes it: it has
     * no staging method (staging belongs to the host's `NotificationPublisher`), so
     * this timestamp comes from the host's staging path (R13). It is also the input
     * to the batch bucket, which is why R13 makes it an obligation rather than a
     * field description.
     */
    readonly createdAt: Date;
    /** How many times a worker has claimed this row, including this claim (R13). */
    readonly attempts: number;
}

interface ClaimedNotificationDelivery {
    readonly id: string;
    readonly applicationKey: string;
    readonly recipientRef: string;
    readonly actorRef: string | null;
    readonly category: string;
    readonly priority: string;
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
    readonly batchCount: number;
    readonly batchItemCount: number;
    readonly aggregationLabel: string | null;
    /** How many times a worker has claimed this delivery, including this claim (D9). */
    readonly attempts: number;
}

interface CreateDeliveryInput {
    readonly applicationKey: string;
    readonly recipientRef: string;
    readonly actorRef: string | null;
    readonly category: string;
    readonly priority: NotificationPriority;
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
    /** Null for a standalone delivery: the batch unique constraint then does not apply. */
    readonly batchKey: string | null;
    readonly batchWindowStartedAt: Date | null;
    readonly batchPolicyKey: string | null;
    readonly aggregationLabel: string | null;
    readonly batchCount: number;
    readonly batchItemCount: number;
    /** Not dispatchable before this instant (D5). */
    readonly deliverAfter: Date;
    readonly createdAt: Date;
}

/**
 * `created: false` means a delivery with this batch identity already existed and
 * `id` is that row. It is NOT an error and MUST NOT throw (R11): the caller falls
 * back to `mergeIntoBatch`, and to the follow-up route when that fails.
 * Appending an item to a delivery you did not create can bind it to a
 * presentation-locked row, which loses the notification silently (design 0.3-7).
 */
interface CreateDeliveryResult {
    readonly id: string;
    readonly created: boolean;
}

interface DispatchClaimRequest {
    readonly applicationKey: string;
    readonly limit: number;
    /** From the injected clock. Also the due cutoff for `deliverAfter` (D5). */
    readonly at: Date;
    /** A duration; the store compares it against its own clock (D8). */
    readonly claimStaleMs: number;
    /** Same predicate and the same "pass count, not duration" caveat as R13 (D9). */
    readonly maxAttempts?: number | undefined;
    readonly claimToken: string;
}

interface DispatchCompleteRequest {
    readonly applicationKey: string;
    readonly deliveryId: string;
    readonly claimToken: string;
    readonly at: Date;
}

interface DispatchReleaseRequest {
    readonly applicationKey: string;
    readonly deliveryId: string;
    readonly claimToken: string;
    /** Already redacted: a stable short code, never an exception message. */
    readonly errorCode: string | null;
}

interface DispatchTransactionRequest {
    readonly applicationKey: string;
    readonly deliveryId: string;
    readonly claimToken: string;
    readonly at: Date;
}

interface EnsureMessageInput {
    readonly applicationKey: string;
    readonly deliveryId: string;
    readonly recipientRef: string;
    readonly actorRef: string | null;
    readonly category: string;
    readonly priority: NotificationPriority;
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
    readonly at: Date;
}

/**
 * Adapts Nest's `LoggerService` (message-first) to the `NotificationLogger` port
 * (fields-first). The structured fields are passed through as an extra
 * parameter, which Nest's own console logger prints alongside the message.
 */
declare function fromNestLogger(logger: LoggerService, context?: string): NotificationLogger;

interface MergeBatchInput {
    readonly applicationKey: string;
    readonly deliveryId: string;
    /** Added to `batchCount`. Always 1 today; a parameter so a store never guesses. */
    readonly addedCount: number;
    readonly addedItemCount: number;
    readonly aggregationLabel: string | null;
    readonly at: Date;
}

interface NestNotificationsAsyncOptions {
    readonly imports?: DynamicModule['imports'] | undefined;
    readonly inject?: readonly InjectionToken[] | undefined;
    readonly useFactory: (...deps: readonly any[]) => NestNotificationsOptions | Promise<NestNotificationsOptions>;
}

/**
 * The notification pipeline as a Nest module.
 *
 * Deliberately not `@Global()`: a host that wants these providers everywhere says
 * so itself. Everything the pipeline needs is a required option, because a
 * silently working default would mean the library chose someone's product policy
 * — the store trio, the presenter, the policy and the application key have no
 * defaults for exactly that reason.
 */
declare class NestNotificationsModule {
    /**
     * Synchronous wiring. Configuration is validated here, at assembly time: an
     * empty `applicationKey` or `providers` list fails to boot rather than failing
     * on the scheduler's first call.
     */
    static forRoot(options: NestNotificationsOptions): DynamicModule;
    /**
     * Asynchronous wiring, for hosts whose stores or policy come from other
     * providers. The same assembly-time validation runs immediately after the
     * factory resolves, so the boot-failure guarantee survives this path.
     */
    static forRootAsync(options: NestNotificationsAsyncOptions): DynamicModule;
}

interface NestNotificationsOptions {
    readonly applicationKey: string;
    readonly relayStore: NotificationRelayStore;
    readonly deliveryStore: NotificationDeliveryStore;
    readonly endpointStore: NotificationEndpointStore;
    readonly pushGateway: NotificationPushGateway;
    readonly presenter: NotificationPresenter;
    readonly policy: NotificationSchedulingPolicy;
    /** Which endpoint providers the gateway handles. Must be non-empty. */
    readonly providers: readonly string[];
    /**
     * Exposed through `NOTIFICATION_PUBLISHER` for source-domain code. The pipeline
     * never calls it: staging happens in the host's own transaction.
     */
    readonly publisher?: NotificationPublisher<never> | undefined;
    readonly logger?: NotificationLogger | undefined;
    /**
     * Shared by the relay, the dispatcher and the wakeup hint - one instance, not
     * three. Defaults to `systemNotificationRuntime()`. Without this a consumer
     * wired through `forRoot` cannot fix the clock, so their own quiet-hours and
     * batch-window behaviour is untestable, and `defer` cannot be swapped for a
     * serverless host (design 0.2-12).
     */
    readonly runtime?: NotificationRuntime | undefined;
    readonly wakeup?: {
        readonly enabled?: boolean | undefined;
    } | undefined;
    readonly relay?: Pick<NotificationRelayOptions, 'pageSize' | 'claimStaleMs' | 'maxAttempts'> | undefined;
    readonly dispatch?: Pick<NotificationDispatcherOptions, 'pageSize' | 'claimStaleMs' | 'maxAttempts' | 'disableRejectedEndpoints'> | undefined;
}

/** The client-visible action is intentionally transport and domain agnostic. */
type NotificationAction = {
    readonly href?: string | undefined;
    readonly [key: string]: NotificationJsonValue | undefined;
};

interface NotificationBatch {
    readonly key: string;
    readonly label?: string | undefined;
    readonly itemCount?: number | undefined;
}

/** Half-open aggregation bucket `[startedAt, endsAt)`. Never spans a local midnight. */
interface NotificationBatchWindow {
    readonly startedAt: Date;
    readonly endsAt: Date;
}

/** The single source of "now" for every policy decision the pipeline makes. */
interface NotificationClock {
    now(): Date;
}

/**
 * One source recipient plus one stable event key is the idempotency boundary
 * (design 3.1 G1). `applicationKey` is server-owned configuration: API callers
 * must never choose it.
 *
 * Delivery order between two commands is never guaranteed (G8). Quiet-hours
 * holds, batch windows, scheduled timings, parallel workers and per-item retries
 * all reorder deliveries, so a domain that needs an order must put it in the
 * body.
 */
interface NotificationCommand {
    readonly applicationKey: string;
    readonly recipientRef: string;
    readonly actorRef?: string | null | undefined;
    readonly targetRef?: string | null | undefined;
    readonly category: string;
    readonly priority: NotificationPriority;
    readonly title?: string | null | undefined;
    readonly body: string;
    readonly action?: NotificationAction | null | undefined;
    readonly eventKey: string;
    readonly batch?: NotificationBatch | null | undefined;
    readonly timing?: NotificationTiming | undefined;
}

interface NotificationDeliveryStore {
    /**
     * Atomically claim due deliveries. The claim MUST also stamp the presentation
     * lock in the same statement (D1): split into two statements, a relay can merge
     * an item in between and the user never sees it.
     */
    claimDue(request: DispatchClaimRequest): Promise<readonly ClaimedNotificationDelivery[]>;
    materializeInTransaction<T>(request: DispatchTransactionRequest, work: (tx: NotificationDispatchTransaction) => Promise<T>): Promise<T | null>;
    /** `false` means the claim was lost; `deliveredAt` is unchanged (D3). */
    complete(request: DispatchCompleteRequest): Promise<boolean>;
    /**
     * Release a failed claim. The presentation lock is NOT released: the inbox
     * sentence may already have been shown to the user (D1).
     */
    releaseClaim(request: DispatchReleaseRequest): Promise<void>;
}

interface NotificationDispatcher {
    dispatchDue(): Promise<NotificationDispatchSummary>;
}

interface NotificationDispatcherOptions {
    readonly applicationKey: string;
    readonly store: NotificationDeliveryStore;
    readonly endpoints: NotificationEndpointStore;
    readonly pushGateway: NotificationPushGateway;
    readonly presenter: NotificationPresenter;
    /** Which endpoint providers this gateway handles. Required: no default provider. */
    readonly providers: readonly string[];
    readonly runtime?: NotificationRuntime | undefined;
    readonly logger?: NotificationLogger | undefined;
    /** Defaults to {@link DEFAULT_DISPATCH_PAGE_SIZE}. */
    readonly pageSize?: number | undefined;
    /** A duration; the store compares it against its own clock (D8). */
    readonly claimStaleMs?: number | undefined;
    /**
     * Deliveries already attempted this many times are left out of the page (D9).
     * Same trade-off, same arithmetic and the same silence as
     * `NotificationRelayOptions.maxAttempts` - read that one. The dispatch
     * side loses less on exhaustion (the inbox message is already written, so only
     * the push is lost), but the push is lost for good.
     */
    readonly maxAttempts?: number | undefined;
    /**
     * Disable locally rejected endpoints too. Default false: a local shape check is
     * not a provider confirmation, and the day our check becomes stricter than the
     * provider's it would permanently darken live devices (design 0.2-6).
     */
    readonly disableRejectedEndpoints?: boolean | undefined;
}

/** Injectable wrapper whose `run()` is what a scheduler calls. */
declare class NotificationDispatchRunner {
    #private;
    constructor(dispatcher: NotificationDispatcher);
    /** One dispatch pass. Never throws for a single failed delivery. */
    run(): Promise<NotificationDispatchSummary>;
}

/** A type alias for the same reason `NotificationRelaySummary` is (design 3.6). */
type NotificationDispatchSummary = {
    readonly ok: boolean;
    readonly claimed: number;
    readonly delivered: number;
    readonly failed: number;
    /**
     * Endpoints this pass asked the store to disable. `disable` returns void, so a
     * revision that no longer matches is counted here even though the store made
     * it a no-op (D6). It is a request count, not a row count.
     */
    readonly endpointsDisabled: number;
};

interface NotificationDispatchTransaction {
    readDelivery(): Promise<ClaimedNotificationDelivery | null>;
    /** Conflict-safe insert then read. Never throws on a duplicate (D2). */
    ensureMessage(input: EnsureMessageInput): Promise<{
        readonly id: string;
    }>;
}

interface NotificationEndpointDisableTarget {
    readonly id: string;
    /** Exactly the value `listEnabled` returned for this endpoint. */
    readonly revision: string;
}

interface NotificationEndpointStore {
    listEnabled(input: {
        readonly applicationKey: string;
        readonly recipientRef: string;
        readonly providers: readonly string[];
    }): Promise<readonly ObservedNotificationEndpoint[]>;
    /**
     * Idempotent and stale-safe. An empty list is a no-op, and so is an entry whose
     * `revision` no longer matches the stored row: the device re-registered between
     * `listEnabled` and here, and disabling it would leave a live device dark
     * indefinitely (D6, design 0.2-18).
     */
    disable(input: {
        readonly applicationKey: string;
        readonly endpoints: readonly NotificationEndpointDisableTarget[];
        /** Recorded as the disable instant. From the injected clock (D7). */
        readonly at: Date;
    }): Promise<void>;
}

type NotificationJsonValue = NotificationJsonPrimitive | readonly NotificationJsonValue[] | {
    readonly [key: string]: NotificationJsonValue;
};

/**
 * 구조적 로거 포트 — 소스의 `PinoLogger`(nestjs-pino) 직접 의존을 대체한다(설계 §0.2-⑮).
 * 형제 `nest-operations-jobs`의 `JobLogger`와 같은 형태라 pino 인스턴스가 그대로 대입되고,
 * Nest 내장 `Logger`는 `.` 서브패스의 `fromNestLogger` 어댑터가 흡수한다.
 */
/** Fields-first structured logger. A pino instance satisfies this shape as is. */
interface NotificationLogger {
    info(fields: Record<string, unknown>, message: string): void;
    warn(fields: Record<string, unknown>, message: string): void;
    error(fields: Record<string, unknown>, message: string): void;
}

interface NotificationPresentation {
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
}

/**
 * 표시 포트 — **기본 구현이 없다**(설계 §0.2-② · §3.4.4).
 *
 * 소스는 `새 알림 N건`을 하드코딩했다. 사용자가 실제로 읽는 문장은 제품 카피이고,
 * 기본값을 주면 영어권 소비자가 남의 언어를 배포하며, 중립 폴백을 주면 5건짜리 배치가
 * 첫 항목의 문장으로 나간다(둘 다 거짓말이다). 필수 옵션이면 컴파일 에러가 결정을 강제한다.
 */
interface NotificationPresentationInput {
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
    readonly category: string;
    readonly priority: NotificationPriority;
    /** How many source commands were merged into this delivery. */
    readonly batchCount: number;
    /** Sum of the merged commands' item counts. */
    readonly batchItemCount: number;
    readonly aggregationLabel: string | null;
}

/**
 * Produces the sentence a person actually reads, in the inbox and in the push
 * payload. The library ships no implementation: batch copy is product copy, and
 * a default would ship one product's language to every consumer.
 *
 * A presenter that returns an empty body makes the notification invisible, which
 * the dispatcher treats as a permanent failure
 * (`ERR_NOTIFICATION_MESSAGE_NOT_VISIBLE`) rather than writing a blank inbox card.
 */
interface NotificationPresenter {
    present(input: NotificationPresentationInput): NotificationPresentation;
}

/**
 * The only port source-domain code needs. `Transaction` stays generic because
 * staging happens inside the host's own source transaction — this is the one
 * port in this package that takes a host transaction object (design 3.4.1).
 *
 * Implementations owe obligations I1-I3 (design 3.3.6): conflict-safe insert,
 * a liveness gate acquired before the insert, and a staging timestamp written
 * exactly once.
 */
interface NotificationPublisher<Transaction = unknown> {
    stage(transaction: Transaction, command: NotificationCommand): Promise<NotificationStageResult>;
}

/**
 * 전송 포트 — provider 중립(설계 §3.4.5).
 *
 * 소스가 스스로 "provider port. 저장소도 recipient의 application identity도 모른다"고
 * 적어 둔 경계다. 우리는 그 경계를 지운 게 아니라 지킨다 — 어떤 provider SDK도 dependency,
 * peer, optional peer 중 무엇으로도 들어오지 않는다(설계 §2.2). provider 고유 지식은
 * 별도 서브패스가 무의존 순수 함수로 소유하고, 이 파일은 그 이름조차 모른다(가드가 강제).
 */
interface NotificationPushEndpoint {
    readonly id: string;
    /** Opaque to this library. The dispatcher's `providers` option decides routing. */
    readonly provider: string;
    readonly address: string;
}

interface NotificationPushGateway {
    /** Reject malformed provider addresses before they become durable endpoints. */
    isValidEndpoint(endpoint: Pick<NotificationPushEndpoint, 'provider' | 'address'>): boolean;
    /**
     * Hands one delivery to the transport. Implementations absorb transport
     * failures into `accepted: false` rather than throwing: a rejected handoff is
     * an outcome the dispatcher records, not an exception it has to classify.
     */
    send(endpoints: readonly NotificationPushEndpoint[], payload: NotificationPushPayload): Promise<NotificationPushResult>;
}

interface NotificationPushPayload {
    /** The durable inbox message id. */
    readonly notificationId: string;
    /**
     * Stable across every retry of this delivery. Transports that support
     * de-duplication or collapsing should map it onto their own key: retries are
     * at-least-once (design 3.1 G5), and this is the only lever that reduces
     * duplicates.
     */
    readonly idempotencyKey: string;
    readonly collapseKey?: string | undefined;
    readonly recipientRef: string;
    readonly title: string | null;
    readonly body: string;
    readonly action: NotificationAction | null;
    readonly priority: NotificationPriority;
}

interface NotificationPushResult {
    /** False retains the durable delivery for retry. */
    readonly accepted: boolean;
    /** The provider confirmed these endpoints are gone. Safe to disable. */
    readonly invalidEndpointIds: readonly string[];
    /**
     * Locally malformed addresses. NOT provider-confirmed: the dispatcher logs
     * them and, by default, leaves them enabled (design 0.2-6). Merging the two
     * lists is how the source could permanently disable a live device the day its
     * own regex became stricter than the provider's.
     */
    readonly rejectedEndpointIds: readonly string[];
}

/** Half-open local-clock window `[startHour, endHour)`. `start > end` wraps midnight. */
interface NotificationQuietHours {
    /** 0-23, inclusive. */
    readonly startHour: number;
    /** 0-23, exclusive. */
    readonly endHour: number;
}

interface NotificationRelay {
    relayDue(): Promise<NotificationRelaySummary>;
}

/**
 * 릴레이 — ingress outbox 행을 배달로 물질화한다(설계 §3.6).
 *
 * 소스 로직을 유지하되 저장소 호출만 포트로 바꾼다. 소스와 달라지는 지점은 세 개이고
 * 전부 결함 수정이다: 시각을 행마다 다시 읽고(§0.2-⑦), stale 임계를 기간으로만 넘기며
 * (R12), `createDelivery`의 `created: false`를 병합/follow-up으로 되돌린다(R11 · §0.3-⑦).
 */
interface NotificationRelayOptions {
    readonly applicationKey: string;
    readonly store: NotificationRelayStore;
    readonly policy: NotificationSchedulingPolicy;
    readonly runtime?: NotificationRuntime | undefined;
    readonly logger?: NotificationLogger | undefined;
    /** Defaults to {@link DEFAULT_RELAY_PAGE_SIZE}. */
    readonly pageSize?: number | undefined;
    /**
     * Passed to the store as a duration; the store compares it against its own
     * clock (R12). Defaults to {@link DEFAULT_CLAIM_STALE_MS}.
     */
    readonly claimStaleMs?: number | undefined;
    /**
     * Rows already attempted this many times are left out of the due page (R13).
     * Absent means no bound - a permanently failing row is then re-claimed every
     * pass and, at `pageSize` such rows, starves healthy notifications (design
     * 7-16). The library owns no backoff policy (design 0.4-7); this is the only
     * lever it offers, and choosing a value is an operational decision.
     *
     * **Both settings lose something, so read this before picking one.**
     *
     * - `attempts` counts *claims*, not elapsed time: there is no cooldown between
     *   a `releaseClaim` and the next claim, so the retry window this buys is
     *   `maxAttempts ÷ pass frequency`, not a duration. Every pass counts - a
     *   periodic runner's and a `NotificationPipelineWakeup` pass alike - so with
     *   the wakeup hint enabled a staging burst can spend the whole budget of an
     *   unrelated failing row in seconds.
     * - An exhausted row leaves the due page **permanently**, and nothing in this
     *   package reports it: neither summary type counts it, and the store is asked
     *   for a filtered page rather than for what it filtered out. Watching for
     *   exhausted rows is a host query (design 6-15), and a host that does not run
     *   one converts a transport outage longer than the budget into silent loss.
     */
    readonly maxAttempts?: number | undefined;
}

/**
 * 러너 — 주기 실행자가 부르는 것은 `run()`이다(설계 §3.8.2).
 *
 * 반환 타입이 곧 계약이다: `run(): Promise<Summary>`가 정확성 경로이고
 * `NotificationPipelineWakeup.request(): void`가 지연 경로다. 두 요약 타입이 **type alias**라
 * `Record<string, unknown>`에 구조적으로 대입되므로, 형제 잡 패키지의 어댑터가 12줄이 된다
 * — 그것은 의존이 아니라 구조적 호환의 결과다(설계 §0.4-③).
 */
/** Injectable wrapper whose `run()` is what a scheduler calls. */
declare class NotificationRelayRunner {
    #private;
    constructor(relay: NotificationRelay);
    /** One relay pass. Never throws for a single failed row; the summary reports it. */
    run(): Promise<NotificationRelaySummary>;
}

/**
 * Ingress outbox persistence. The library owns no schema; a host maps these four
 * operations onto its own table. The obligations R1-R13 documented in the design
 * are part of the contract, and `notificationStoreContractCases()` from the
 * `./testing` subpath checks them.
 */
interface NotificationRelayStore {
    /** Atomically claim up to `limit` due rows. Only rows this call actually won are returned (R1). */
    claimDue(request: RelayClaimRequest): Promise<readonly ClaimedNotificationCommand[]>;
    /**
     * Run `work` in one transaction that holds the outbox row lock (R7). Resolves
     * to `null` without running `work` when this worker no longer owns the claim.
     */
    relayInTransaction<T>(request: RelayTransactionRequest, work: (tx: NotificationRelayTransaction) => Promise<T>): Promise<T | null>;
    /** `false` means the claim was lost; the stored outcome is unchanged (R8). */
    completeClaim(request: RelayCompleteRequest): Promise<boolean>;
    /** Release a failed claim so the next pass can retry it. Never throws for a lost claim. */
    releaseClaim(request: RelayReleaseRequest): Promise<void>;
}

/**
 * Declared as a type alias, NOT an interface. Only object type aliases get an
 * implicit index signature, so only this form is assignable to
 * `Record<string, unknown>` - which is exactly the shape a sibling job runner's
 * summary slot has. An interface fails with "Index signature for type 'string'
 * is missing" and the 12-line job adapter in the README stops compiling
 * (measured; design 0.4-3).
 *
 * The outcome counters can sum to less than `claimed`: a claim lost mid-pass is
 * neither an outcome nor a failure, and it is logged rather than counted.
 */
type NotificationRelaySummary = {
    readonly ok: boolean;
    readonly claimed: number;
    readonly relayed: number;
    readonly suppressed: number;
    readonly alreadyRelayed: number;
    readonly noLongerLive: number;
    readonly failed: number;
};

interface NotificationRelayTransaction {
    /** Re-read the locked source row. `null` means it is gone (recipient purge). */
    readCommand(): Promise<ClaimedNotificationCommand | null>;
    /** Category preference gate. Absent rows mean enabled. */
    isCategoryEnabled(input: {
        readonly recipientRef: string;
        readonly category: string;
    }): Promise<boolean>;
    /** Idempotency probe for this source row (G2). */
    findDeliveryBySource(): Promise<{
        readonly deliveryId: string;
    } | null>;
    findOpenBatch(key: BatchIdentity): Promise<OpenBatchDelivery | null>;
    /** Conditional merge. `false` means the batch closed between read and write (R6). */
    mergeIntoBatch(input: MergeBatchInput): Promise<boolean>;
    /** Conflict-safe. Never throws on the batch-identity unique constraint (R11). */
    createDelivery(input: CreateDeliveryInput): Promise<CreateDeliveryResult>;
    /** `false` means an item for this source row already existed (R4). */
    appendItem(input: AppendItemInput): Promise<boolean>;
}

/**
 * Pure scheduling decisions. Implement this interface to vary policy per
 * recipient (their own zone) or per category; {@link createQuietHoursPolicy} is
 * the built-in single-zone implementation.
 */
interface NotificationSchedulingPolicy {
    /** True when `at` falls inside the configured quiet window. */
    isQuietHours(at: Date): boolean;
    /** Earliest instant this command may be delivered. Never earlier than `now`. */
    resolveDeliveryAt(input: ResolveDeliveryInput): Date;
    /** Aggregation bucket that contains `at`. */
    batchWindow(at: Date): NotificationBatchWindow;
}

/**
 * 타입드 에러와 에러 코드 축약.
 *
 * 소스는 `new Error(문자열)`과 Nest 예외를 섞어 던졌다(설계 §0.2-⑧). AGENTS.md §2가
 * 요구하는 것은 안정적인 code 유니언과 type guard이고, 이 파일이 그 둘을 소유한다.
 */
/** Stable, closed set of error codes this package throws. */
type NotificationsErrorCode = 'ERR_NOTIFICATION_COMMAND_INVALID' | 'ERR_NOTIFICATION_APPLICATION_KEY_INVALID' | 'ERR_NOTIFICATION_RECIPIENT_KEY_INPUT' | 'ERR_NOTIFICATION_POLICY_INVALID' | 'ERR_NOTIFICATION_TIMEZONE_INVALID' | 'ERR_NOTIFICATION_PRIORITY_UNSUPPORTED' | 'ERR_NOTIFICATION_PUSH_HANDOFF_REJECTED' | 'ERR_NOTIFICATION_MESSAGE_NOT_VISIBLE' | 'ERR_NOTIFICATION_CONFIG_INVALID';

interface NotificationStageResult {
    /** Null only when the recipient lifecycle has already tombstoned this ref. */
    readonly id: string | null;
    readonly staged: boolean;
    readonly discarded?: boolean | undefined;
}

/**
 * An ISO instant rather than a Date, so a command stays JSON-serialisable while
 * it waits in a durable ingress outbox.
 */
type NotificationTiming = {
    readonly mode: 'IMMEDIATE';
} | {
    readonly mode: 'SCHEDULED';
    readonly at: string;
};

interface NotificationWakeupOptions {
    readonly relay: NotificationRelay;
    readonly dispatcher: NotificationDispatcher;
    /** Set false to make `request()` a no-op (serverless, tests). Default true. */
    readonly enabled?: boolean | undefined;
    readonly runtime?: NotificationRuntime | undefined;
    readonly logger?: NotificationLogger | undefined;
}

/**
 * An endpoint plus the registration revision observed when it was listed. A
 * disable computed from this observation must not survive a re-registration that
 * happened afterwards (D6).
 */
interface ObservedNotificationEndpoint extends NotificationPushEndpoint {
    /**
     * Opaque and compared only for equality. Any value that changes whenever the
     * row is re-registered works: `lastSeenAt.toISOString()`, a version counter, or
     * an xmin/rowversion column.
     */
    readonly revision: string;
}

interface OpenBatchDelivery {
    readonly id: string;
    /** False once the delivery is claimed, presentation-locked or delivered. */
    readonly open: boolean;
}

interface QuietHoursPolicyOptions {
    /**
     * IANA time zone name (for example `'Europe/Paris'`), or `'UTC'`.
     * The library holds no regional default: this field is required.
     */
    readonly timeZone: string;
    /** `null` disables quiet hours entirely. */
    readonly quietHours?: NotificationQuietHours | null | undefined;
    /** Aggregation window length. Must divide 24h evenly. Defaults to {@link DEFAULT_BATCH_WINDOW_MS}. */
    readonly batchWindowMs?: number | undefined;
    /** Priorities held during quiet hours. Defaults to `['NORMAL']`. */
    readonly holdPriorities?: readonly NotificationPriority[] | undefined;
}

interface RelayClaimRequest {
    readonly applicationKey: string;
    readonly limit: number;
    /**
     * From the injected clock. Recorded verbatim on completion stamps and passed to
     * the policy (R9). It is NOT the input to the staleness comparison - see
     * `claimStaleMs`.
     */
    readonly at: Date;
    /**
     * A duration, deliberately not an instant. The store decides staleness on its
     * own clock (`claimedAt < now() - claimStaleMs`, R12): with N workers there are
     * N process clocks, and the only clock they share is the store's.
     */
    readonly claimStaleMs: number;
    /**
     * Skip rows already attempted this many times. Absent means no bound, which
     * lets a permanently failing row occupy the due page forever (R13, design 7-16).
     *
     * The predicate is `attempts < maxAttempts` and nothing else: there is no
     * cooldown column and no `retryAfter` field on this request or on
     * {@link RelayReleaseRequest}, because retry timing has exactly one owner and
     * it is the host's scheduler (design 0.4-7). A released row is therefore due
     * again on the very next pass, so this bound is a pass count, not a duration.
     */
    readonly maxAttempts?: number | undefined;
    /** Opaque token this worker writes onto every row it wins. */
    readonly claimToken: string;
}

interface RelayCompleteRequest {
    readonly applicationKey: string;
    readonly outboxId: string;
    readonly claimToken: string;
    readonly at: Date;
    readonly suppressed: boolean;
}

interface RelayReleaseRequest {
    readonly applicationKey: string;
    readonly outboxId: string;
    readonly claimToken: string;
    /** Already redacted by the relay: a stable short code, never an exception message. */
    readonly errorCode: string | null;
}

interface RelayTransactionRequest {
    readonly applicationKey: string;
    readonly outboxId: string;
    readonly claimToken: string;
    readonly at: Date;
}

interface ResolveDeliveryInput {
    readonly priority: NotificationPriority;
    readonly timing: NotificationTiming | undefined;
    readonly now: Date;
    /** Present so a host implementation can vary policy per recipient or category. */
    readonly recipientRef: string;
    readonly category: string;
}

interface AppendItemInput {
    readonly applicationKey: string;
    readonly deliveryId: string;
    readonly sourceOutboxId: string;
    readonly at: Date;
}

/**
 * Validates a command before it reaches a durable outbox.
 *
 * Throws {@link NotificationsError} with code `ERR_NOTIFICATION_COMMAND_INVALID`;
 * the source threw a bare `Error` (design 0.2-8).
 */
declare function assertNotificationCommand(command: NotificationCommand): void;

