    readonly amountStateChange: PaymentStateValueChange<PaymentAmountState> | null;
    readonly pendingCancellationChange: PaymentStateValueChange<boolean> | null;
    readonly abortedCancellationChange: PaymentStateValueChange<boolean> | null;
    readonly cancelableChange: PaymentStateValueChange<boolean> | null;
    readonly partiallyCancelableChange: PaymentStateValueChange<boolean> | null;
    readonly cancelChanges: PaymentCancelChanges;
    readonly warnings: readonly PaymentStateDiffWarning[];
}

type PaymentStateDiffWarning = {
    /** 환불 취소·입금 오류 등 정상적인 역전이일 수도 있으므로 오류로 차단하지 않는다. */
    readonly kind: "balance-increased";
    readonly previousBalanceAmount: number;
    readonly nextBalanceAmount: number;
    readonly delta: number;
} | {
    /** 제공자 응답의 취소 배열에서 이전 transactionKey가 사라졌다. */
    readonly kind: "cancel-removed";
    readonly transactionKey: string;
};

/** 서로 다른 결제의 스냅샷을 비교하려 한 경우에만 반환되는 오류. */
interface PaymentStateIdentityError {
    readonly source: "library";
    readonly kind: "payment-state-identity-mismatch";
    readonly mismatches: readonly PaymentStateIdentityMismatch[];
}

interface PaymentStateIdentityMismatch {
    readonly field: "paymentKey" | "orderId";
    readonly previous: string;
    readonly next: string;
}

/**
 * 저장·로그하기 안전한 결제 상태 요약.
 *
 * Payment.secret, Payment.raw, 카드/계좌 상세 및 취소 사유는 포함하지 않는다.
 */
interface PaymentStateSnapshot {
    /** 영속 스키마 진화를 위한 고정 버전. */
    readonly schemaVersion: 1;
    readonly paymentKey: PaymentKey;
    readonly orderId: OrderId;
    readonly status: PaymentStatus;
    readonly lifecycle: PaymentLifecycle;
    readonly totalAmount: number;
    readonly balanceAmount: number;
    readonly lastTransactionKey: string | null;
    /** totalAmount - balanceAmount. 비정상 응답에서는 음수일 수 있으며 consistencyIssues에 남는다. */
    readonly canceledAmount: number;
    readonly amountState: PaymentAmountState;
    readonly hasPendingCancellation: boolean;
    readonly hasAbortedCancellation: boolean;
    /** 현재 스냅샷에서 새 취소 요청을 시도할 수 있는지에 대한 보수적 힌트. */
    readonly isCancelable: boolean;
    /** 입금 전·비동기 취소 진행 중을 제외하고 부분취소가 가능한지에 대한 보수적 힌트. */
    readonly isPartiallyCancelable: boolean;
    readonly cancels: readonly PaymentCancelTransactionSnapshot[];
    readonly consistencyIssues: readonly PaymentStateConsistencyIssue[];
}

/**
 * Why {@link parsePaymentStateSnapshot} rejected a value: the four string-constraint reasons
 * come from re-branding `paymentKey`/`orderId` through the existing id parsers;
 * `'malformed'` covers every structural failure (wrong type, missing field, unknown literal,
 * unsupported `schemaVersion`). The offending location is in
 * {@link InvalidPaymentStateSnapshot.path}.
 */
type PaymentStateSnapshotParseReason = InvalidInput<"paymentStateSnapshot">["reason"] | "malformed";

interface PaymentStateValueChange<T> {
    readonly previous: T;
    readonly next: T;
}

/**
 * Payment 객체 — method 한글 리터럴 판별 유니언 + `raw: unknown` 탈출구.
 * 필드 목록의 근거: docs/research/toss-payments-v2.md "Payment 객체 주요 필드".
 */
type PaymentStatus = 'READY' | 'IN_PROGRESS' | 'WAITING_FOR_DEPOSIT' | 'DONE' | 'CANCELED' | 'PARTIAL_CANCELED' | 'ABORTED' | 'EXPIRED';

/** 승인 전 결제 — method nullable. status는 전체 유니언 유지(협착은 미검증 불변식). */
interface PendingMethodPayment extends PaymentBase {
    readonly method: null;
}

interface PercentageRefundPolicyConfig extends RefundPolicyIdentity {
    readonly kind: "percentage";
    /** 0..10,000 정수. */
    readonly rateBps: number;
    readonly rounding: RefundRoundingMode;
    readonly reason?: string;
}

REFUND_TIME: Readonly<{
    minute: 60000;
    hour: number;
    day: number;
}>

type RefundCalculation = {
    readonly kind: "full";
} | {
    readonly kind: "percentage";
    readonly rateBps: number;
} | {
    readonly kind: "elapsed-time-rate";
    readonly elapsedMs: number;
    /** fallback이면 null. */
    readonly bracketIndex: number | null;
    readonly rateBps: number;
} | {
    readonly kind: "remaining-units";
    readonly totalUnits: number;
    readonly remainingUnits: number;
    readonly rateBps: number;
} | {
    readonly kind: "custom";
    readonly entitlementKind: "rate" | "amount";
    readonly details: Readonly<Record<string, RefundCalculationDetail>>;
};

type RefundCalendarError = {
    readonly source: "library";
    readonly kind: "invalid-refund-calendar";
    readonly field: string;
    readonly reason: string;
};

/** custom 정책이 반환하는 누적 환불 entitlement. 현재 실행액은 기존 환불을 차감해 계산한다. */
type RefundEntitlement = {
    readonly kind: "rate";
    readonly rateBps: number;
    readonly reason?: string;
    readonly details?: Readonly<Record<string, RefundCalculationDetail>>;
} | {
    readonly kind: "amount";
    /** 이번 환불액이 아니라 정책상 누적 환불 가능 총액. */
    readonly amount: number;
    readonly reason?: string;
    readonly details?: Readonly<Record<string, RefundCalculationDetail>>;
};

interface RefundObservedCancelState {
    readonly transactionKey: string;
    readonly cancelAmount: number;
    readonly refundableAmount: number;
    readonly canceledAt: string;
    readonly cancelStatus: CancelTransaction["cancelStatus"];
}

/** quote를 만든 Payment와 실행 직전 재조회 Payment가 같은 관측 상태인지 대조하는 값. */
interface RefundObservedPaymentState {
    readonly status: PaymentStatus;
    readonly method: Payment["method"];
    readonly lastTransactionKey: string | null;
    readonly isPartialCancelable: boolean;
    readonly cancels: readonly RefundObservedCancelState[];
}

interface RefundPolicy<Input extends RefundQuoteInput = RefundQuoteInput> extends Brand<"RefundPolicy"> {
    readonly id: string;
    readonly version: string;
    readonly kind: RefundPolicyKind;
    quote(input: Input): Result<RefundQuote, RefundQuoteError>;
    /** 저장 JSON을 활성 policy와 동일 입력으로 재계산해 실행 가능한 quote로 복원한다. */
    restoreQuote(stored: unknown, input: Input): Result<RefundQuote, RefundQuoteRestoreError>;
}

type RefundPolicyConfigError = {
    readonly source: "library";
    readonly kind: "invalid-refund-policy";
    readonly policyId: string;
    readonly field: string;
    readonly reason: string;
};

interface RefundPolicyIdentity {
    /** CS·원장에 남길 안정적인 정책 ID. */
    readonly id: string;
    /** 정책 변경 뒤에도 과거 계산을 재현하기 위한 버전. */
    readonly version: string;
    /** quote의 최대 수명. 생략하면 {@link DEFAULT_REFUND_QUOTE_TTL_MS}. */
    readonly quoteTtlMs?: number;
}

/**
 * 정책 계산 결과. plain serializable 값이며 실제 cancel 실행 전 server의 prepareRefund를
 * 통과해야 한다. quote.amount는 항상 이번에 추가로 실행할 금액이다.
 */
interface RefundQuote extends Brand<"RefundQuote"> {
    readonly kind: "none" | "full" | "partial";
    readonly policy: {
        readonly id: string;
        readonly version: string;
        readonly kind: RefundPolicyKind;
    };
    readonly paymentKey: PaymentKey;
    readonly orderId: OrderId;
    readonly currency: Payment["currency"];
    readonly evaluatedAt: string;
    /** exclusive. 실행 시각이 이 값 이상이면 반드시 재조회·재견적한다. */
    readonly validUntil: string;
    readonly observedPaymentState: RefundObservedPaymentState;
    /** quote 생성 때 관찰한 Toss Payment.balanceAmount. */
    readonly observedBalanceAmount: number;
    /** 프로젝트 장부가 기대한 잔액. 생성 성공 시 observed와 같다. */
    readonly expectedBalanceAmount: number;
    readonly basisAmount: number;
    readonly alreadyRefundedAmount: number;
    /** 정책상 누적 환불 가능 총액(반올림 후). */
    readonly entitlementAmount: number;
    /** entitlement에서 기존 확정 환불을 뺀 이번 실행액. */
    readonly amount: number;
    readonly balanceAfterRefund: number;
    /** 과거 확정 환불이 현재 정책 entitlement를 이미 넘은 금액. */
    readonly overRefundedAmount: number;
    /** 금액 직접 산출 정책이면 null. */
    readonly rateBps: number | null;
    readonly rounding: RefundRoundingMode;
    readonly calculation: RefundCalculation;
    readonly reason: string | null;
}

type RefundQuoteError = {
    readonly source: "library";
    readonly kind: "invalid-refund-input";
    readonly policyId: string;
    readonly field: string;
    readonly reason: string;
} | {
    readonly source: "library";
    readonly kind: "expected-refund-balance-mismatch";
    readonly policyId: string;
    readonly expected: number;
    readonly actual: number;
} | {
    readonly source: "library";
    readonly kind: "calculated-refund-exceeds-balance";
    readonly policyId: string;
    readonly calculatedAmount: number;
    readonly balanceAmount: number;
} | {
    readonly source: "library";
    readonly kind: "custom-refund-calculation-failed";
    readonly policyId: string;
    readonly cause: unknown;
};

/**
 * 모든 정책 quote의 공통 입력.
 *
 * basisAmount/alreadyRefundedAmount/expectedBalanceAmount는 프로젝트 장부가 제공한다.
 * 라이브러리는 expectedBalanceAmount를 최신 Payment.balanceAmount와 대조하므로 외부
 * 부분취소나 장부 drift가 있으면 계산 전에 멈춘다.
 */
interface RefundQuoteInput {
    readonly payment: Payment;
    /** 정책 비율을 곱할 프로젝트 장부 기준 금액. */
    readonly basisAmount: number;
    /** 프로젝트 장부에 provider 완료로 확정된 누적 환불액. */
    readonly alreadyRefundedAmount: number;
    /** 프로젝트 장부가 기대하는 현재 Toss 환불 가능 잔액. */
    readonly expectedBalanceAmount: number;
    /** 정책을 평가한 시각. 테스트 가능한 명시 입력이며 quote에 ISO로 남는다. */
    readonly evaluatedAt: Date;
    /**
     * 프로젝트 상태가 반드시 다시 평가되어야 하는 더 이른 경계(선택).
     * 예: 잔여 달력 일수는 다음 현지 자정. 정책 TTL/시간 구간 경계와의 최솟값이 적용된다.
     */
    readonly validUntil?: Date;
}

interface RefundQuoteParseError {
    readonly source: "library";
    readonly kind: "invalid-refund-quote";
    readonly field: string;
    readonly reason: string;
}

interface RefundQuotePolicyMismatchError {
    readonly source: "library";
    readonly kind: "refund-quote-policy-mismatch";
    readonly policyId: string;
    readonly reason: "stored-quote-does-not-match-recalculation";
}

/**
 * IANA 시간대의 달력 일수로 totalUnits/remainingUnits를 만든다.
 * 반환값은 remaining-units 정책 quote 입력에 그대로 펼칠 수 있다.
 */
declare function remainingCalendarDays(input: RemainingCalendarDaysInput): Result<RemainingCalendarDays, RefundCalendarError>;

interface RemainingCalendarDays {
    readonly startsOn: string;
    readonly endsOnExclusive: string;
    readonly evaluatedOn: string;
    readonly timeZone: string;
    readonly requestDay: "refundable" | "consumed";
    /** 다음 현지 달력 날짜가 시작되는 exclusive 재평가 시각(ISO instant). */
    readonly validUntil: string;
    readonly totalUnits: number;
    readonly remainingUnits: number;
}

interface RemainingCalendarDaysInput {
    /** YYYY-MM-DD, 서비스 시작일 포함. */
    readonly startsOn: string;
    /** YYYY-MM-DD, 서비스 종료일 미포함 — 기간은 [startsOn, endsOnExclusive). */
    readonly endsOnExclusive: string;
    readonly evaluatedAt: Date;
    /** IANA time zone (예: Asia/Seoul). */
    readonly timeZone: string;
    /** 요청 당일을 환불 대상에 포함할지 명시한다. */
    readonly requestDay: "refundable" | "consumed";
}

interface RemainingUnitsRefundPolicyConfig extends RefundPolicyIdentity {
    readonly kind: "remaining-units";
    /** 잔여 비율에 추가로 곱할 비율. 기본 10,000(100%). */
    readonly rateBps?: number;
    readonly rounding: RefundRoundingMode;
    readonly reason?: string;
}

interface RemainingUnitsRefundQuoteInput extends RefundQuoteInput {
    /** 전체 일수·회차·사용량 단위. 양수 안전한 정수. */
    readonly totalUnits: number;
    /** 0..totalUnits 안전한 정수. */
    readonly remainingUnits: number;
}

/**
 * Result — plain 판별 유니언 + 자유 함수 콤비네이터.
 * 메서드 클래스 금지(직렬화 안전) — 값은 어디서든 plain 객체다.
 */
type Result<T, E> = Ok<T> | Err<E>;

/**
 * Brand-free, JSON-ready form of {@link PaymentStateSnapshot}.
 *
 * Identical field-for-field, except `paymentKey`/`orderId` are plain `string`s — safe to put
 * in a response DTO, a queue message or a jsonb column without exporting the branded id types
 * across your provider boundary. Every other field is already a JSON primitive, a plain
 * object array, or `null`. A `PaymentStateSnapshot` is assignable to this type (brands are
 * strings underneath); the reverse direction must go through
 * {@link parsePaymentStateSnapshot}.
 *
 * JSON caveat: a snapshot whose `consistencyIssues` include `invalid-amount` with
 * `reason: 'not-safe-integer'` may carry non-finite numbers (`NaN`/`Infinity`), which
 * `JSON.stringify` silently turns into `null` — the later parse then rejects the value
 * honestly instead of resurrecting a fake amount. Check `consistencyIssues` before
 * persisting a snapshot as JSON.
 */
interface SerializedPaymentStateSnapshot {
    readonly schemaVersion: 1;
    readonly paymentKey: string;
    readonly orderId: string;
    readonly status: PaymentStatus;
    readonly lifecycle: PaymentLifecycle;
    readonly totalAmount: number;
    readonly balanceAmount: number;
    readonly lastTransactionKey: string | null;
    readonly canceledAmount: number;
    readonly amountState: PaymentAmountState;
    readonly hasPendingCancellation: boolean;
    readonly hasAbortedCancellation: boolean;
    readonly isCancelable: boolean;
    readonly isPartiallyCancelable: boolean;
    readonly cancels: readonly PaymentCancelTransactionSnapshot[];
    readonly consistencyIssues: readonly PaymentStateConsistencyIssue[];
}

/**
 * 에러 모델 — 최상위 판별자 `source`: 'library'(API 미도달 보장) / 'toss'(서버 응답) / 'network'(전송).
 *
 * retryable 판정은 **코드 테이블**로만 한다 — HTTP status 판정 금지.
 * 근거: PROVIDER_ERROR는 400이지만 재시도 가능, REFUND_REJECTED는 400이지만 비재시도.
 */
interface TossApiFailure<Code extends string = string> {
    readonly source: 'toss';
    /** 토스 응답 {code, message} 원문 무손실 보존. */
    readonly code: Code;
    readonly message: string;
    /** 보존하되 판정에 쓰지 않는다. */
    readonly httpStatus: number;
    readonly category: ErrorCategory;
    /** ⚠ 코드 테이블 판정 — HTTP status 아님. */
    readonly retryable: boolean;
    /** x-tosspayments-trace-id */
    readonly traceId: string | null;
}

interface TransferDetails {
    readonly bankCode: string;
    readonly settlementStatus: string;
}

interface TransferPayment extends PaymentBase {
    readonly method: '계좌이체';
    readonly transfer: TransferDetails;
}

interface TransportFailure {
    readonly source: 'network';
    readonly code: 'NETWORK_ERROR' | 'TIMEOUT';
    readonly retryable: true;
    readonly cause: unknown;
}

interface VirtualAccountDetails {
    readonly accountNumber: string;
    readonly accountType: string;
    readonly bankCode: string;
    readonly customerName: string;
    readonly dueDate: string;
    readonly expired: boolean;
    readonly settlementStatus: string;
    readonly refundStatus: string;
    readonly refundReceiveAccount: unknown | null;
}

interface VirtualAccountPayment extends PaymentBase {
    readonly method: '가상계좌';
    readonly virtualAccount: VirtualAccountDetails;
    /**
     * 가상계좌 승인 응답에서만 내려오는 DEPOSIT_CALLBACK 대조값.
     *
     * 결제 조회 API는 같은 가상계좌 결제라도 `null`을 반환할 수 있다. 따라서 일반
     * `Payment` 조회 결과에서 이 값을 복구할 수 있다고 가정하면 안 된다. confirm 응답에서
     * secret을 보장해야 하는 코드는 server의 `ConfirmedPayment`를 사용한다.
     */
    readonly secret: string | null;
    readonly card: null;
}

/**
 * CustomerKey ∧ 길이 ≤50 (SDK 문서 한도) — 브라우저 API는 이것만 받는다.
 * 50자(SDK) vs 300자(서버 실측) 문서 모순을 서브타입 분리로 해소한다.
 */
type WidgetCustomerKey = CustomerKey & Brand<'WidgetCustomerKey'>;

interface AgreementWidget {
    /** {@link RenderedTossWidgets.on}과 동일한 래퍼 수준 구독 해제. */
    on(event: 'agreementStatusChange', handler: (s: {
        agreedRequiredTerms: boolean;
    }) => void): () => void;
    destroy(): Promise<void>;
}

/**
 * 빌링 등록 인증창 — SDK payment({customerKey}).requestBillingAuth 래퍼.
 *
 * 빌링은 API 개별 키(ck) 전용 — 위젯 키(gck)는 컴파일 에러.
 * customer는 WidgetCustomerKey만 — ANONYMOUS는 파라미터 타입에서 배제된다
 * (빌링은 고유 customerKey 전제, SDK 문서에 ANONYMOUS 빌링 언급 없음 — 연구문서 §빌링).
 */
/**
 * SDK v2.7.1 타입 정의로 확정(Phase 0): method 'CARD' | 'TRANSFER' 판별 유니언.
 * selectableCardTypes는 CARD 전용 — TRANSFER 쪽은 `?: never`로 변수 경유 전달까지 차단한다.
 */
type BillingAuthRequest = {
    readonly method: 'CARD';
    /** origin을 포함한 완전 URL — 성공 시 쿼리로 authKey, customerKey가 붙는다. */
    readonly successUrl: string;
    readonly failUrl: string;
    readonly customerName?: string;
    readonly customerEmail?: string;
    readonly windowTarget?: 'self' | 'iframe';
    /** 결제화면에 노출할 카드 타입 — 입력 순서대로 노출, 첫 항목이 기본 선택. */
    readonly selectableCardTypes?: readonly ('PERSONAL' | 'CORPORATE')[];
} | {
    readonly method: 'TRANSFER';
    readonly successUrl: string;
    readonly failUrl: string;
    readonly customerName?: string;
    readonly customerEmail?: string;
    readonly windowTarget?: 'self' | 'iframe';
    /** 카드 전용 파라미터 (SDK v2.7.1 타입 정합) — TRANSFER에서는 존재 자체가 컴파일 에러. */
    readonly selectableCardTypes?: never;
};

/**
 * 위젯 로드 — WidgetClientKey(gck) 전용. ApiSecretKey는 물론 ApiClientKey(ck)도 컴파일 에러다.
 * customer는 2–50자 서브타입(WidgetCustomerKey) 또는 {@link ANONYMOUS}만 —
 * 300자 허용 서버용 CustomerKey는 컴파일 에러.
 */
declare function loadWidgets(clientKey: WidgetClientKey, customer: WidgetCustomerKey | Anonymous): Promise<Result<TossWidgets, WidgetError>>;

/**
 * 결제 요청 결과 — 사용자 취소는 에러가 아니다.
 * 리다이렉트 모드 고정: 프로미스 모드는 모바일 미지원(문서 근거)이라 제공하지 않는다.
 */
type PaymentRequestOutcome = {
    readonly kind: 'redirecting';
} | {
    readonly kind: 'user-canceled';
    readonly code: 'USER_CANCEL' | 'PAY_PROCESS_CANCELED';
    readonly message: string;
};

/** 상태 2: 렌더 완료 — 여기서만 결제 요청이 가능하다. */
interface RenderedTossWidgets {
    requestPayment(request: WidgetPaymentRequest): Promise<Result<PaymentRequestOutcome, SdkError>>;
    setAmount(amount: WidgetAmount): Promise<Result<RenderedTossWidgets, WidgetError>>;
    getSelectedPaymentMethod(): Promise<Result<{
        readonly code: string;
    }, WidgetError>>;
    /**
     * 결제수단 선택 이벤트 구독. 반환 함수로 구독을 해제한다 —
     * SDK on()은 해제를 제공하지 않으므로 래퍼가 활성 플래그로 전달을 중단한다.
     */
    on(event: 'paymentMethodSelect', handler: (m: {
        code: string;
    }) => void): () => void;
    destroy(): Promise<void>;
}

/**
 * 자동결제(빌링) 등록 인증창을 연다. 성공 시 successUrl로 리다이렉트되며
 * 서버에서 parseBillingAuthCallback → confirmPendingAuth → issue로 이어진다.
 * 사용자 취소(USER_CANCEL / PAY_PROCESS_CANCELED)는 에러가 아닌 user-canceled variant다.
 */
declare function requestBillingAuth(clientKey: ApiClientKey, customer: WidgetCustomerKey, request: BillingAuthRequest): Promise<Result<PaymentRequestOutcome, SdkError>>;

/** SDK 호출이 던진 예외의 {code, message} 회수 형태. */
interface SdkError {
    readonly kind: 'sdk';
    readonly code: string;
    readonly message: string;
}

/** 상태 0: 금액 미설정 — render/requestPayment 메서드 자체가 없다. */
interface TossWidgets {
    setAmount(amount: WidgetAmount): Promise<Result<TossWidgetsWithAmount, WidgetError>>;
}

/** 상태 1: 금액 설정됨 — 렌더링 가능. setAmount는 쿠폰 등 금액 변경용으로 남는다. */
interface TossWidgetsWithAmount {
    renderPaymentMethods(options: {
        readonly selector: string;
        readonly variantKey?: string;
    }): Promise<Result<RenderedTossWidgets, WidgetError>>;
    renderAgreement(options: {
        readonly selector: string;
        readonly variantKey?: string;
    }): Promise<Result<AgreementWidget, WidgetError>>;
    setAmount(amount: WidgetAmount): Promise<Result<TossWidgetsWithAmount, WidgetError>>;
}

interface WidgetAmount {
    readonly currency: 'KRW' | 'USD' | 'JPY';
    readonly value: number;
}

type WidgetError = SdkError | {
    readonly kind: 'load-failed';
    readonly cause: unknown;
};

interface WidgetPaymentRequest {
    /** 스마트 생성자 산출물만 — 서버 createOrder가 발급한 값은 JSON 경계에서 orderId(raw)로 재파싱한다. */
    readonly orderId: OrderId;
    readonly orderName: OrderName;
    /** origin을 포함한 완전 URL (SDK 문서 요구 — 런타임 검증). */
    readonly successUrl: string;
    readonly failUrl: string;
    readonly customerEmail?: string;
    readonly customerName?: string;
    readonly customerMobilePhone?: string;
    readonly taxFreeAmount?: number;
    /** 최대 5쌍 (문서: metadata 최대 5개 key-value — 런타임 검증). */
    readonly metadata?: Readonly<Record<string, string>>;
}

/**
 * 형식(템플릿 리터럴)과 명목성(브랜드)을 동시에 강제 —
 * `'test_ck_oops'` 리터럴도 parse 없이는 대입 불가.
 */
type ApiClientKey<E extends Env = Env> = (E extends 'test' ? `test_ck_${string}` : `live_ck_${string}`) & Brand<'ApiClientKey'> & EnvTag<E>;

/**
 * audit — 아웃바운드 토스 API req/res 증거 기록 (설계 §3.2, must 3/3 수렴).
 *
 * 타입뿐인 계약 + 순수 redaction 순회기 — 환경 중립(core)이며 런타임 의존성 0.
 * 부착 지점은 server/client.ts의 내부 request() 단일 관문이다(흩어짐 없음).
 *
 * 협상 불가 계약:
 * - `record()`는 await되지 않는다(fire-and-forget) — audit 오류가 결제 요청의
 *   지연·실패에 영향을 주는 경로가 없다(기록 실패 < 결제 실패).
 * - redaction은 비설정화 — 끄는 옵션·설정 파라미터를 제공하지 않는다.
 * - Authorization 헤더는 AuditEntry에 **필드 자체가 없다** — 마스킹이 아니라 구조적 부재.
 */
/**
 * 시도 1건 = 엔트리 1건 (outcome 유니언) — request/response 분리 kind안은
 * 상관(join) 비용 때문에 기각(설계 §7-7).
 *
 * ⚠ responseBody에는 redaction 후에도 고객 이름·이메일 등 PII가 잔존할 수 있다 —
 * 보관 주체·기간·접근 통제는 sink 소유자(사용자) 책임이다.
 */
interface AuditEntry {
    /** crypto.randomUUID — 시도 1건당 1엔트리. */
    readonly id: string;
    /** ISO 8601 요청(시도) 시작 시각. */
    readonly at: string;
    readonly env: Env;
    readonly method: 'GET' | 'POST' | 'DELETE';
    /** '/v1/payments/confirm' 등 pathname만 — 쿼리 미포함. */
    readonly path: string;
    /** 1부터 — retry(§3.4) 결합 시 시도마다 엔트리 1건. */
    readonly attempt: number;
    readonly idempotencyKey: string | null;
    /** redaction 통과본. ⚠ 헤더 필드가 타입에 없다 — Authorization은 구조적으로 기록 불가. body 없는 요청은 null. */
    readonly requestBody: unknown;
    readonly durationMs: number;
    /** x-tosspayments-trace-id — 고객센터 문의 키. */
    readonly traceId: string | null;
    readonly outcome: {
        readonly kind: 'ok';
        readonly httpStatus: number;
        /** redaction 통과본. */
        readonly responseBody: unknown;
    } | {
        readonly kind: 'toss-error';
        readonly httpStatus: number;
        readonly code: string;
        readonly message: string;
    } | {
        readonly kind: 'transport';
        readonly code: 'NETWORK_ERROR' | 'TIMEOUT';
    };
}

interface AuditOptions {
    readonly sink: AuditSink;
    /** sink 실패 통지. 기본 무시 — 이 콜백의 throw도 삼켜진다. */
    readonly onSinkError?: (cause: unknown, entry: AuditEntry) => void;
}

interface AuditSink {
    /**
     * 시도 1건당 1회 호출된다. 반환 Promise는 클라이언트가 await하지 않는다 —
     * sync throw·async rejection 모두 삼켜지고 `AuditOptions.onSinkError`로만 통지된다.
     */
    record(entry: AuditEntry): void | Promise<void>;
}

interface AuthKeyReceived extends Brand<'AuthKeyReceived'> {
    /** 대조 완료된 **세션 유래** 값 — 콜백 값이 아니다. authKey는 계속 봉인 상태. */
    readonly customerKey: CustomerKey;
}

interface AwaitingDepositCancelable extends Brand<'Cancelable'> {
    /** WAITING_FOR_DEPOSIT → 전액만 + refundAccount 금지(환불할 금액이 없다). */
    readonly kind: 'awaiting-deposit';
    readonly payment: Payment & {
        readonly status: 'WAITING_FOR_DEPOSIT';
    };
    readonly balanceAmount: number;
}

interface AwaitingDepositRefundRequest {
    readonly reason: CancelReason;
    readonly refundAccount?: never;
    readonly taxFreeAmount?: never;
    readonly cancelRequestId?: CancelRequestId;
    readonly currency?: never;
}

type BillingApproveError = TossApiFailure<BillingErrorCode> | TransportFailure | {
    readonly source: 'library';
    readonly kind: 'missing-idempotency-key';
} | {
    readonly source: 'library';
    readonly kind: 'invalid-input';
    readonly field: string;
    readonly reason: string;
}
/** 봉인 소실 복제본 — billing.load()로 재수화하라. */
 | {
    readonly source: 'library';
    readonly kind: 'profile-detached';
    readonly customerKey: CustomerKey;
};

type BillingAuthCallback = {
    readonly status: 'authorized';
    readonly pending: PendingBillingAuth;
} | {
    readonly status: 'user-canceled';
    readonly code: string;
} | {
    readonly status: 'failed';
    readonly code: string;
    readonly message: string;
};

interface BillingCapabilities {
    /** 카드 정보 직접 전달 발급(/v1/billing/authorizations/card) — 추가 계약 필요. */
    readonly directCardIssue?: true;
    /** @deprecated approve는 이제 모든 구성에서 멱등키가 필수다. */
    readonly requireApproveIdempotencyKey?: true;
}

type BillingFlow<E extends Env, C extends BillingCapabilities = {}> = BillingFlowBase<E> & (C extends {
    directCardIssue: true;
} ? {
    /**
     * 추가 계약 필요(NOT_SUPPORTED_METHOD). 테스트 표준 카드 9410001234567890
     * (Phase 0 실측 — BIN 6자리 단독은 400 INVALID_CARD_NUMBER).
     */
    issueWithCard(input: DirectCardIssueInput, options?: CallOptions<E>): Promise<Result<BillingProfile, IssueBillingKeyError>>;
} : {});

interface BillingFlowBase<E extends Env> {
    /**
     * POST /v1/billing/authorizations/issue → store.save 성공 후에만 Ok.
     * 저장 실패면 Err에 발급된 record 동봉 — 조회 API가 없으므로 저장 실패 = 키 유실이다.
     */
    issue(auth: AuthKeyReceived, options?: CallOptions<E>): Promise<Result<BillingProfile, IssueBillingKeyError>>;
    /** 스토어에서 재수화 — BillingProfile을 얻는 유일한 다른 경로(봉인 소실 복구 API). */
    load(customerKey: CustomerKey): Promise<Result<BillingProfile | null, StoreFailure>>;
    /**
     * ⚠ 마이그레이션 전용 이관 경로(§7 확정 6) — 기존 시스템이 보유한 billingKey를
     * 형식 검증 후 store.save 하고 BillingProfile로 승격한다.
     *
     * 토스에는 빌링키 조회 API가 없어 **record 값의 진위를 서버에서 재검증할 수 없다** —
     * 오염된 record면 '타입은 맞고 값은 틀린' 프로필이 만들어져 approve에서
     * INVALID_BILL_KEY_REQUEST 류로 실패한다. 신뢰할 수 있는 원본에서만 이관할 것.
     */
    import(record: BillingKeyRecord): Promise<Result<BillingProfile, ImportBillingKeyError>>;
    /**
     * BillingOrder에는 customerKey 필드가 없다 — 봉인 쌍으로만 승인 →
     * NOT_MATCHES_CUSTOMER_KEY 구조적 방지. 봉인이 소실된 profile(스프레드 복제본 등)은
     * 런타임 Err('profile-detached') — billing.load로 재수화 안내.
     *
     * options와 idempotencyKey는 모든 구성에서 필수다. TypeScript 우회를 거친 런타임 호출도
     * missing-idempotency-key로 API 전송 전에 거부한다.
     */
    readonly approve: (profile: BillingProfile, order: BillingOrder, options: CallOptions<E> & {
        readonly idempotencyKey: IdempotencyKey;
    }) => Promise<Result<BillingPayment, BillingApproveError>>;
    /**
     * DELETE /v1/billing/{billingKey} 뒤
     * `store.delete({ customerKey, expectedBillingKey: billingKey })`.
     *
     * 반환의 `currentStoredKeyDeleted`가 false면 profile은 이미 오래됐거나 행이 없어
     * 현재 저장 credential을 지우지 않았다. 갱신 API는 존재하지 않는다 — refresh류
     * 메서드 없음. 재발급 = 새 인증부터.
     */
    revoke(profile: BillingProfile, options?: CallOptions<E>): Promise<Result<RevokeBillingKeyOutcome, RevokeBillingKeyError>>;
}

/**
 * 현재 billing key를 조건부로 제거하는 요청.
 *
 * 두 raw 문자열을 별도 인자로 받지 않고 한 객체로 묶어, 예전의
 * `delete(customerKey)` 구현이 TypeScript 구조 타이핑에서 우연히 호환되는 일을 막는다.
 * 이 객체는 billing key 영속화 경계에서만 만들고 로그/telemetry에 통째로 남기지 않는다.
 */
interface BillingKeyDeleteRequest {
    readonly customerKey: BillingKeyRecord['customerKey'];
    readonly expectedBillingKey: BillingKeyRecord['billingKey'];
}

/**
 * 영속화 경계 — 여기서만 raw 쌍(customerKey + billingKey)이 보인다.
 *
 * ⚠ 토스의 빌링 보안 모델은 이 쌍의 분리에 의존한다("빌링키가 노출되어도 매핑된
 * customerKey를 모른다면 결제가 불가능합니다" — 빌링 가이드). billingKey와
 * customerKey를 같은 로그에 함께 남기지 말 것.
 */
interface BillingKeyRecord {
    readonly customerKey: string;
    readonly billingKey: string;
    /** 응답 원문 한글 리터럴 — 요청 enum(CARD/TRANSFER)과 비대칭. */
    readonly method: '카드' | '계좌이체';
    /** 발급 응답의 authenticatedAt. */
    readonly issuedAt: string;
    readonly card: {
        readonly issuerCode: string;
        readonly number: string;
        readonly cardType: '신용' | '체크' | '기프트' | '미확인';
        readonly ownerType: '개인' | '법인' | '미확인';
    } | null;
    /** 퀵계좌이체 발급 — 배열이다(응답 원문 구조). */
    readonly transfers: readonly {
        readonly bankName: string;
        readonly bankAccountNumber: string;
    }[] | null;
}

/**
 * billing key 저장의 비밀 아닌 lifecycle 상관관계 값.
 *
 * `operationId`는 동일 customerKey의 서로 다른 발급 시도마다 달라야 한다. core
 * `billing.issue`는 `CallOptions.idempotencyKey`가 있으면 이 값으로 자동 전달한다.
 * raw billing key, auth key, 카드/계좌 정보는 절대 넣지 않는다.
 */
interface BillingKeySaveOptions {
    readonly operationId?: string;
}

/** 저장소 필수 주입 — 토스에 빌링키 조회 API가 없다: 저장이 유일한 보관 수단. */
interface BillingKeyStore {
    /**
     * record를 upsert한다. `operationId`는 발급 뒤 별도 projection을 같은 customerKey
     * fence 안에서 마무리해야 하는 소비자를 위한 비밀이 아닌 상관관계 식별자다.
     *
     * 구현은 값을 로그에 남기지 말고, 지원한다면 현재 row와 원자적으로 대조할 수 있는
     * fingerprint/receipt만 보관해야 한다. 일반 save만 필요한 소비자는 생략할 수 있다.
     */
    save(record: BillingKeyRecord, options?: BillingKeySaveOptions): Promise<void>;
    find(customerKey: CustomerKey): Promise<BillingKeyRecord | null>;
    /**
     * 현재 저장된 billing key가 `expectedBillingKey`일 때만 원자적으로 삭제한다.
     *
     * `false`는 행이 없거나 더 새 키로 교체되어 아무 것도 지우지 않았다는 안전한 결과다.
     * `find()` 후 일반 delete로 흉내 내면 재발급과 경합해 새 키를 지울 수 있으므로,
     * 프로덕션 구현은 하나의 DB 조건문/CAS 또는 잠금 transaction으로 비교와 삭제를
     * 함께 수행해야 한다. 저장소 실패만 throw한다.
     */
    delete(request: BillingKeyDeleteRequest): Promise<boolean>;
}

/** customerKey 필드가 없음이 핵심 — 봉인 쌍(profile)의 값만 전송된다. */
interface BillingOrder {
    readonly orderId: OrderId;
    readonly orderName: OrderName;
    readonly amount: number;
    readonly customerEmail?: string;
    readonly customerName?: string;
    /** FDS 부정거래 탐지용. */
    readonly customerIp?: string;
    readonly taxFreeAmount?: number;
    readonly taxExemptionAmount?: number;
}

type BillingPayment = Payment & {
    readonly type: 'BILLING';
    readonly status: 'DONE';
};

/**
 * billingKey는 공개 필드·JSON 직렬화·열거 어디에도 노출되지 않는다(비공개 심볼, 비열거).
 * WeakMap이 아니므로 일반 전달은 안전하지만, 스프레드/직렬화 복제본은 approve에서
 * 명시적 Err('profile-detached') — billing.load()로 재수화하라.
 */
interface BillingProfile extends Brand<'BillingProfile'> {
    readonly customerKey: CustomerKey;
    readonly method: '카드' | '계좌이체';
    /** "433012******890" — 표시용. */
    readonly maskedSource: string;
    readonly issuedAt: string;
}

interface CallbackParseError {
    readonly source: 'library';
    readonly kind: 'callback-parse';
    /** 문제가 된 파라미터 이름 목록 (missing-param 외 reason에서도 대상 파라미터를 담는다). */
    readonly missing: readonly string[];
    readonly reason: 'missing-param' | 'bad-amount' | 'bad-order-id';
}

/**
 * confirm 플로우 — parse → verify(OrderStore) → confirm 3단계 + confirmCallback 원스톱.
 *
 * 금액 대조("쿼리 파라미터의 amount 값과 setAmount()의 amount 값이 같은지 반드시
 * 확인하세요" — 문서 의무)와 10분 승인 시한을 타입으로 강제한다: confirm은
 * VerifiedCheckout만 받고, VerifiedCheckout은 verify 통과로만 얻는다.
 */
/** 프레임워크 무관 콜백 입력 — Next.js req.url, Express req.query, Hono c.req.url, URL 전부 수용. */
type CallbackQueryInput = string | URL | URLSearchParams | Readonly<Record<string, string | readonly string[] | undefined>>;

interface CallOptions<E extends Env> {
    /**
     * ≤300자, POST 전용. 처음 사용일부터 15일 유효 — TTL 초과 후 재사용하면 새 요청으로
     * 실행될 수 있다(문서는 기간만 명시 — 안전하지 않은 것으로 취급). 멱등 판정 조합은 "키 + API 키 + 주소 + 메서드"이며 body는 포함되지
     * 않는다(문서 명시) — 키 재사용 시 body 동일성은 호출자(또는 재시도 티켓)가 보장해야 한다.
     */
    readonly idempotencyKey?: IdempotencyKey;
    /**
     * TossPayments-Test-Code 헤더 — 에러 시나리오 시뮬레이션.
     * 라이브 키에선 서버가 조용히 무시하는 함정 → 타입으로 차단.
     * ⚠ 비분배 조건부 — 미내로잉 union 키(E = Env)도 never다.
     */
    readonly testCode?: [
        E
    ] extends [
        'test'
    ] ? string : never;
    readonly signal?: AbortSignal;
}

type CancelError = TossApiFailure<CancelErrorCode>
/** 응답 유실 — retry(ticket)로 동일 멱등키+동일 body 재실행. */
 | (TransportFailure & {
    readonly retry: CancelRetryTicket;
}) | CancelPreflightError | {
    /** provider가 취소 트랜잭션을 최종 거부했다. 같은 멱등키 재시도로 성공시킬 수 없다. */
    readonly source: 'library';
    readonly kind: 'cancel-aborted';
    readonly paymentKey: PaymentKey;
    readonly transactionKey: string;
    readonly cancelRequestId: string | null;
};

interface CancelOutcome {
    /** 전액 취소여도 status 'CANCELED' 단정 금지 — 부분취소 이력이 있으면 PARTIAL_CANCELED 유지(실측). */
    readonly payment: Payment & {
        readonly status: 'CANCELED' | 'PARTIAL_CANCELED';
    };
    /** 이번 취소 건. ABORTED는 CancelError로 분리되므로 성공 outcome에는 들어오지 않는다. */
    readonly cancel: CancelTransaction & {
        readonly cancelStatus: 'DONE' | 'IN_PROGRESS';
    };
    /** 완전 취소 판정의 유일한 기준: balanceAmount === 0. status로 판정하지 않는다. */
    readonly fullyCanceled: boolean;
    /** cancelStatus === 'IN_PROGRESS' (PayPal 등 해외 비동기) → CANCEL_STATUS_CHANGED 웹훅 대기. */
    readonly pending: boolean;
    /** 실제 사용된 키 (자동 생성분 포함). */
    readonly idempotencyKey: IdempotencyKey;
}

type CancelPreflightError = {
    /** 우회해서 서버로 보내면 403 NOT_CANCELABLE_AMOUNT (실측) — API 호출 전에 차단한다. */
    readonly source: 'library';
    readonly kind: 'amount-exceeds-balance';
    readonly cancelAmount: number;
    readonly balanceAmount: number;
} | {
    readonly source: 'library';
    readonly kind: 'expected-amount-mismatch';
    readonly expected: number;
    readonly actual: number;
} | {
    readonly source: 'library';
    readonly kind: 'invalid-input';
    readonly field: string;
    readonly reason: string;
} | {
    readonly source: 'library';
    readonly kind: 'partial-cancel-not-allowed';
    readonly paymentKey: PaymentKey;
} | {
    readonly source: 'library';
    readonly kind: 'retry-ticket-expired';
    readonly issuedAt: string;
} | {
    readonly source: 'library';
    readonly kind: 'retry-store-failure';
    readonly operation: 'save' | 'load' | 'delete';
    readonly cause: unknown;
};

/**
 * 취소 요청 ID — 6–64자, `^[A-Za-z0-9\-_=]+$` (상점 발급 고유값).
 * **중국·동남아 비동기(Alipay 등) 결제 취소에만 필수**다 — 공식 V2 '해외 간편결제
 * 연동하기'(문서 ID 53)의 취소 Request Body 규격. 국내/일반 취소에는 불필요.
 */
type CancelRequestId = string & Brand<'CancelRequestId'>;

/** 환불계좌 등 민감 요청을 포함할 수 있으므로 반드시 암호화 at-rest 저장할 것. */
interface CancelRetryRecord {
    readonly ticketId: string;
    readonly paymentKey: string;
    readonly idempotencyKey: string;
    readonly issuedAt: string;
    readonly path: string;
    readonly bodyJson: string;
    readonly testCode: string | undefined;
    readonly expectedCancelAmount: number;
    readonly previousBalanceAmount: number;
}

interface CancelRetryStore {
    save(record: CancelRetryRecord): Promise<void>;
    load(ticketId: string): Promise<CancelRetryRecord | null>;
    delete(ticketId: string): Promise<void>;
}

/**
 * transport 실패 시 발급되는 불투명 재시도 티켓. 같은 프로세스에서는 비열거 봉인을,
 * 재시작 뒤에는 CancelRetryStore의 암호화 record를 사용해 동일 멱등키+body를 복원한다.
 * issuedAt 기준 `DEFAULT_IDEMPOTENCY_REPLAY_WINDOW_MS`(14일 — provider TTL 15일에서 하루 여유)가
 * 지난 티켓은 새 요청으로 실행될 위험이 있어 로컬에서 `retry-ticket-expired`로 거부한다.
 */
interface CancelRetryTicket extends Brand<'CancelRetryTicket'> {
    readonly ticketId: string;
    readonly paymentKey: PaymentKey;
    readonly idempotencyKey: IdempotencyKey;
    readonly issuedAt: string;
    /** true면 네트워크 요청 전에 주입된 CancelRetryStore에 요청 바이트가 저장된 상태. */
    readonly durable: boolean;
}

interface CancelTransaction {
    readonly transactionKey: string;
    readonly cancelAmount: number;
    readonly cancelReason: string;
    readonly taxFreeAmount: number;
    readonly taxExemptionAmount: number;
    /** (응답) 이 취소 후 남은 환불 가능액 — 취소 요청 파라미터의 refundableAmount와 이름만 같다. */
    readonly refundableAmount: number;
    readonly transferDiscountAmount: number;
    readonly easyPayDiscountAmount: number;
    readonly canceledAt: string;
    readonly receiptKey: string | null;
    /** 해외 간편결제(PayPal)는 IN_PROGRESS로 시작하는 비동기 취소 — CANCEL_STATUS_CHANGED 웹훅으로 완결. */
    readonly cancelStatus: 'DONE' | 'IN_PROGRESS' | 'ABORTED';
    /** 비동기 취소 전용. */
    readonly cancelRequestId: string | null;
}

interface CardDetails {
    readonly amount: number;
    readonly issuerCode: string;
    readonly acquirerCode: string | null;
    /** 마스킹된 카드번호. */
    readonly number: string;
    readonly installmentPlanMonths: number;
    readonly approveNo: string;
    readonly useCardPoint: boolean;
    readonly cardType: '신용' | '체크' | '기프트' | '미확인';
    readonly ownerType: '개인' | '법인' | '미확인';
    readonly acquireStatus: string;
    readonly isInterestFree: boolean;
    readonly interestPayer: string | null;
}

interface CardPayment extends PaymentBase {
    readonly method: '카드';
    readonly card: CardDetails;
    readonly virtualAccount: null;
}

/**
 * 승인 API가 직접 반환한 결제.
 *
 * 일반 조회의 가상계좌 `secret`은 `null`일 수 있지만, confirm 성공으로 반환하는 가상계좌는
 * DEPOSIT_CALLBACK을 검증할 non-empty secret을 반드시 포함한다. 이 좁힘은 2xx 응답의
 * runtime 검사 뒤에만 부여된다.
 */
type ConfirmedPayment = (Exclude<Payment, VirtualAccountPayment> & {
    readonly status: ConfirmedStatus;
}) | (VirtualAccountPayment & {
    readonly status: ConfirmedStatus;
    readonly secret: string;
});

/**
 * confirm 응답에서 secret을 받지 못했고, 조회가 결제 자체는 확인한 가상계좌.
 *
 * 결제를 실패로 처리하거나 재confirm하면 안 되지만, DEPOSIT_CALLBACK을 안전하게 검증할
 * 비밀값도 복구할 수 없다. 호출자는 주문을 보류하고 운영 복구 경로로 보내야 한다.
 */
type ConfirmedWithoutDepositSecret = VirtualAccountPayment & {
    readonly status: ConfirmedStatus;
    readonly secret: null;
};

type ConfirmError = TossApiFailure<ConfirmErrorCode> | TransportFailure | {
    readonly source: 'library';
    readonly kind: 'approval-window-exceeded';
    readonly deadline: Date;
    readonly now: Date;
};

type ConfirmErrorCode = 'ALREADY_PROCESSED_PAYMENT'
/** 인증 후 10분 초과 404 — 재시도 불가한 최종 실패(결제 재요청 필요). */
 | 'NOT_FOUND_PAYMENT_SESSION' | 'PAY_PROCESS_ABORTED' | 'INVALID_REQUEST' | 'INVALID_PAYMENT_KEY' | 'REJECT_CARD_PAYMENT' | 'PROVIDER_ERROR' | 'UNAUTHORIZED_KEY' | 'INVALID_API_KEY' | 'FORBIDDEN_REQUEST' | 'NOT_FOUND_PAYMENT' | (string & {});

interface ConfirmFlow<E extends Env> {
    /** 검증 + store.saveOrder까지 완료된 뒤에만 Ok — 금액을 저장 시점에 고정. */
    createOrder(input: {
        amount: number;
        /** ≤100자 precheck. */
        orderName: string;
        /** 생략 시 generateOrderId(). */
        orderId?: OrderId;
        /** 기본 'KRW'. */
        currency?: 'KRW' | 'USD' | 'JPY';
    }): Promise<Result<PendingOrder, CreateOrderError>>;
    /** 저장 주문 로드 → amount 일치 → 시한 검증. 통과해야만 VerifiedCheckout. */
    verify(callback: UnverifiedCallback): Promise<Result<VerifiedCheckout, VerifyCheckoutError>>;
    /**
     * VerifiedCheckout만 받는다 — UnverifiedCallback은 컴파일 에러.
     * 멱등키는 일급 옵션이며 **기본 미부착**(§7 확정 5 — 에러 응답 멱등 재생 여부 미실측이라 보수적).
     */
    confirm(checkout: VerifiedCheckout, options?: CallOptions<E>): Promise<Result<ConfirmedPayment, ConfirmError>>;
    /** 원스톱: parse → verify → confirm. 검증을 생략이 아니라 내장 — 단계별 에러가 union으로 구분된다. */
    confirmCallback(input: CallbackQueryInput, options?: CallOptions<E>): Promise<Result<ConfirmedPayment, CallbackParseError | VerifyCheckoutError | ConfirmError>>;
    /**
     * §3.7 {@link resolveConfirmFailure}의 플로우 결합판 — 플로우의 client를 재사용한다.
     * 일반적인 가상계좌 조회는 secret을 반환하지 않으므로
     * `confirmed-without-deposit-secret`을 주문 보류/운영 복구로 처리해야 한다. provider가
     * 예외적으로 secret을 보존한 `actually-confirmed`일 때만 §3.1 저장 경로를 재사용한다.
     *
     * ⚠ 조회 Err = 진실 미확정 — 성공/실패 어느 쪽으로도 사용자에게 단정 안내하지 말 것.
     */
    resolveFailure(orderId: OrderId, error: ConfirmError): Promise<Result<ConfirmResolution, LookupError$1>>;
}

interface ConfirmFlowOptions {
    /**
     * 기본 10분(600_000ms). Phase 0 확정: 인증 완료(successUrl 리다이렉트) 후 10분,
     * 초과 시 상태 EXPIRED → confirm은 404 NOT_FOUND_PAYMENT_SESSION(재시도 불가 최종 실패).
     * 30분은 결제창 실행(READY)→구매자 인증 구간의 별개 시한 — 라이브러리 통제 밖.
     */
    /** 1~600_000ms의 안전한 정수. provider 승인 시한(10분)을 넘겨 local 검증을 느슨하게 할 수 없다. */
    readonly approvalWindowMs?: number;
    readonly clock?: () => Date;
    /**
     * §3.1 가상계좌 secret 자동 저장 — confirm/confirmCallback이 Ok이고
     * **`payment.method === '가상계좌'`일 때만** saveSecret을 await 호출한다.
     *
     * method 가드 근거(Phase 5 실측): BILLING 카드 결제 응답에도 secret이 non-null로
     * 내려온다 — secret 존재로 판정하면 빌링 결제마다 무의미한 저장이 발생한다.
     *
     * 저장 실패여도 confirm은 **Ok 유지**(협상 불가) — 승인은 토스 측에서 이미 완결이라
     * Err로 뒤집으면 "승인됐는데 실패 처리 + 사용자 재confirm"이라는 더 큰 사고가 된다.
     * 가상계좌 secret은 승인 응답에서만 얻을 수 있고 조회로 복구할 수 없으므로, 저장 실패는
     * 반드시 운영 알림·재처리 대상으로 남겨야 한다. 실패 통지:
     * {@link onDepositSecretSaveFailed} + 'deposit.secret-save-failed' 이벤트.
     */
    readonly depositSecrets?: DepositSecretStore;
    /**
     * saveSecret 실패 통지 — payload에 **secret 원문 미포함**(로그 유출 방지).
     * 가상계좌 secret은 조회로 복구할 수 없으므로, 호출자는 결제를 보류하고 승인 응답 원문을
     * 노출하지 않는 운영 복구 절차를 통해 처리해야 한다.
     * 미지정 시 실패 1건당 console.warn 1회(라이브러리에서 유일하게 시끄러운 기본값 —
     * 침묵 유실 방지: 저장 누락 = 해당 주문의 DEPOSIT_CALLBACK 전부 unknown-order 거부).
     * 이 콜백의 throw는 삼켜진다(Ok 확정 결과 무간섭).
     */
    readonly onDepositSecretSaveFailed?: (info: {
        readonly orderId: OrderId;
        readonly paymentKey: PaymentKey;
        readonly cause: unknown;
    }) => void;
    /**
     * §3.3 이벤트 버스 — 'payment.confirmed' / 'payment.confirm-failed' /
     * 'deposit.secret-saved' / 'deposit.secret-save-failed' 발행 지점.
     * createTossEvents 산출물만 발행이 흐른다(구조적 모조 객체는 no-op).
     */
    readonly events?: TossEvents;
}

/**
 * 세션에 저장된 customerKey와 대조 — 통과해야만 AuthKeyReceived.
 * 이 단계를 건너뛰고 issue를 호출할 방법이 없다 (쿼리 값은 위변조 가능 — 문서도
 * "검증 후 발급 API 호출"을 요구).
 */
declare function confirmPendingAuth(pending: PendingBillingAuth, expectedCustomerKey: CustomerKey): Result<AuthKeyReceived, {
    readonly source: 'library';
    readonly kind: 'customer-key-mismatch';
    readonly expected: string;
    readonly returned: string;
}>;

/**
 * §3.7 confirm 실패 복구·안내 3분기 — "confirm Err ≠ 결제 실패"(G8).
 *
 * transport 실패(승인됐는데 응답 유실)·ALREADY_PROCESSED_PAYMENT(새로고침 이중 confirm)를
 * 일괄 실패 처리하면 "돈은 나갔는데 실패 안내"라는 최악의 CS 사고가 난다 — 조회로 진실을
 * 확정한 뒤 분기하라.
 */
type ConfirmResolution = 
/** 조회로 DONE|WAITING_FOR_DEPOSIT 및 (가상계좌라면) secret까지 확인됨. */
{
    readonly resolution: 'actually-confirmed';
    readonly payment: ConfirmedPayment;
}
/** 결제는 확인됐지만 가상계좌 secret은 lookup으로 복구할 수 없다 — 주문 보류/운영 복구. */
 | {
    readonly resolution: 'confirmed-without-deposit-secret';
    readonly payment: ConfirmedWithoutDepositSecret;
}
/** NOT_FOUND_PAYMENT_SESSION(10분 초과) 등 — 결제 재요청 유도. */
 | {
    readonly resolution: 'retry-payment';
}
/** 조회로도 미승인 확정. */
 | {
    readonly resolution: 'definitively-failed';
    readonly error: ConfirmError;
};

/**
 * 빌링 플로우 팩토리 — client는 'api' KeyKind 전용(위젯 키 클라이언트는 컴파일 에러),
 * store는 필수(조회 API가 없어 저장이 유일한 보관 수단).
 */
declare function createBillingFlow<E extends Env, C extends BillingCapabilities = {}>(client: TossServerClient<E, 'api'>, store: BillingKeyStore, options?: {
    readonly capabilities?: C;
    /**
     * §3.3 이벤트 버스 — billing.issued/approved/approve-failed/revoked 발행 지점.
     * payload에 billingKey는 원천 부재(봉인 원칙 유지). createTossEvents 산출물만 발행이 흐른다.
     */
    readonly events?: TossEvents;
}): BillingFlow<E, C>;

/**
 * createFileAuditSink — JSONL append 파일 싱크 참조 구현 (설계 §3.2).
 *
 * 코어 "런타임 의존성 0·플랫폼 중립" 원칙과의 공존:
 * - `node:fs/promises`는 **최초 record 시 지연 동적 import** — 정적 `node:` import가 없어
 *   번들에 node 의존이 각인되지 않는다(tsup `external: [/^node:/]` + platform neutral 유지).
 * - Edge에서 createFileAuditSink를 호출하지 않는 한 "./server"의 Edge 호환은 불변이다.
 *
 * 운영 계약:
 * - Promise 체이닝 직렬화 큐 — record 호출 순서 = 파일 append 순서(엔트리 교차 없음).
 *   한 append의 실패는 그 record의 반환 Promise로만 전파되고 큐는 계속 살아있다.
 * - fire-and-forget(클라이언트가 await하지 않음)이라 프로세스 즉사 시 마지막 엔트리가
 *   유실될 수 있다 — `flush()`/`close()`를 graceful shutdown 훅에 연결하라.
 * - ⚠ 다중 프로세스 병행 쓰기 무방비 — 단일 인스턴스(프로세스당 파일 1개) 전제.
 */
declare function createFileAuditSink(filePath: string, options?: {
    /** 엔트리 → 1행 문자열(개행 미포함). 기본 JSONL 1행(JSON.stringify). */
    readonly formatter?: (entry: AuditEntry) => string;
}): AuditSink & {
    flush(): Promise<void>;
    close(): Promise<void>;
};

type CreateOrderError = {
    readonly source: 'library';
    readonly kind: 'invalid-input';
    readonly field: string;
    readonly reason: string;
} | {
    readonly source: 'library';
    readonly kind: 'store-failure';
    readonly operation: 'save';
    readonly cause: unknown;
};

/**
 * 오버로드로 키 종류가 각인된다 — 위젯 상점의 confirm은 gsk 필수(키 쌍 규칙, 불일치 시
 * INVALID_API_KEY — 400인 점 주의). 빌링 플로우는 'api' KeyKind만 받는다.
 */
declare function createTossClient<E extends Env>(key: ApiSecretKey<E>, options?: TossClientOptions): TossServerClient<E, 'api'>;

declare function createTossClient<E extends Env>(key: WidgetSecretKey<E>, options?: TossClientOptions): TossServerClient<E, 'widget'>;

/**
 * 이벤트 버스 생성 — 각 배선 지점(TossClientOptions.events 등)에 주입한다.
 *
 * ⚠ 발행은 createTossEvents 산출물에만 흐른다 — 구조적으로 흉내 낸 사용자 객체를 주입하면
 * 구독 표면으로는 동작하지 않고 발행 지점이 조용히 no-op이 된다(내부 emit 계층 부재).
 */
declare function createTossEvents(options?: {
    /** 핸들러 예외 통지. 기본 무시 — 이 콜백의 throw도 삼켜진다. */
    readonly onHandlerError?: (info: {
        readonly type: TossEventName;
        readonly cause: unknown;
    }) => void;
}): TossEvents;

/**
 * 파사드 팩토리 — 오버로드 2종(API 키 / 위젯 키). 위젯 키 + `billingKeys`는 어느
 * 오버로드도 충족하지 못해 컴파일 에러다(키 쌍 규칙 선차단).
 *
 * ⚠ config를 스프레드로 동적 구성하면 `const` 추론이 풀려 조건부 프로퍼티 판정이
 * 무너질 수 있다 — 동적 구성이 필요하면 기존 개별 팩토리 4종을 직접 사용하라.
 * forRootAsync 등 간접 전달에는 {@link defineTossPaymentsConfig}로 추론을 고정하라.
 */
declare function createTossPayments<E extends Env, const C extends TossPaymentsApiConfig<E>>(config: C & {
    readonly secretKey: ApiSecretKey<E>;
}): TossPaymentsKit<E, 'api', C>;

declare function createTossPayments<E extends Env, const C extends TossPaymentsWidgetConfig<E>>(config: C & {
    readonly secretKey: WidgetSecretKey<E>;
}): TossPaymentsKit<E, 'widget', C>;

interface CustomRefundPolicyConfig<Context> extends RefundPolicyIdentity {
    readonly kind: "custom";
    readonly rounding: RefundRoundingMode;
    /** throw 대신 Result 실패를 사용한다. throw도 라이브러리가 포착해 quote 오류로 바꾼다. */
    readonly calculate: (input: CustomRefundQuoteInput<Context>) => Result<RefundEntitlement, unknown>;
}

interface CustomRefundQuoteInput<Context> extends RefundQuoteInput {
    readonly context: Context;
}

type DepositedVaCancelable = (DepositedVaCancelableBase & {
    readonly partialAllowed: true;
    readonly payment: DepositedVaCancelableBase['payment'] & {
        readonly isPartialCancelable: true;
    };
}) | (DepositedVaCancelableBase & {
    readonly partialAllowed: false;
    readonly payment: DepositedVaCancelableBase['payment'] & {
        readonly isPartialCancelable: false;
    };
});

interface DepositedVirtualAccountRefundRequest {
    readonly reason: CancelReason;
    readonly refundAccount: RefundAccount;
    readonly taxFreeAmount?: number;
    readonly cancelRequestId?: CancelRequestId;
    readonly currency?: never;
}

/**
 * 가상계좌 secret 저장소 — 웹훅 `DepositSecretSource`(getSecret)의 상위 타입 (설계 §3.1, G1).
 *
 * 한 객체로 confirm측 자동 저장(`ConfirmFlowOptions.depositSecrets`) + 웹훅측 대조
 * (`WebhookVerifierConfig.depositSecrets`) 양쪽을 1회 배선한다 — 저장(README 수동 한 줄)과
 * 조회(웹훅 config)가 다른 파일에 흩어져 저장 누락 → DEPOSIT_CALLBACK 전부 unknown-order
 * 거부가 되는 사고를 구조로 막는다.
 */
interface DepositSecretStore extends DepositSecretSource {
    /**
     * upsert 시맨틱 계약 — 기존 수동 저장과 병용해도 이중 저장이 무해해야 한다.
     * (getSecret(orderId): Promise<string | null>은 DepositSecretSource에서 상속 —
     * 기존 WebhookVerifierConfig.depositSecrets에 그대로 전달 가능, 파괴 없음.)
     */
    saveSecret(orderId: OrderId, secret: string): Promise<void>;
}

/** Input for {@link deriveIdempotencyKey}. */
interface DeriveIdempotencyKeyInput {
    /** Logical operation name, e.g. `'billing_initial_charge'` or `'subscription_renewal'`. */
    readonly operation: string;
    /**
     * Identity of the logical business event — ids and period markers that make the key
     * deterministic (subscription id, period start epoch, quote id, …). Never put raw
     * billing/auth keys, card or account numbers here: the key travels in request headers and
     * audit logs.
     */
    readonly parts: readonly string[];
    /**
     * Optional attempt discriminator. Omit it for the first submission; supply a fresh value
     * (e.g. a UUID) for a *new* attempt after a definitive 4xx, because Toss replays the original
     * 4xx for the same key for 15 days. Keep it **absent** when you intend a replay
     * (transport failure, `IDEMPOTENT_REQUEST_PROCESSING`).
     */
    readonly attempt?: string | undefined;
}

