 * across your provider boundary. Every other field is already a JSON primitive, a plain
 * object array, or `null`. A `PaymentStateSnapshot` is assignable to this type (brands are
 * strings underneath); the reverse direction must go through
 * {@link parsePaymentStateSnapshot}.
 *
 * JSON caveat: a snapshot whose `consistencyIssues` include `invalid-amount` with
 * `reason: 'not-safe-integer'` may carry non-finite numbers (`NaN`/`Infinity`), which
 * `JSON.stringify` silently turns into `null` — the later parse then rejects the value
 * honestly instead of resurrecting a fake amount. Check `consistencyIssues` before
 * persisting a snapshot as JSON.
 */
interface SerializedPaymentStateSnapshot {
    readonly schemaVersion: 1;
    readonly paymentKey: string;
    readonly orderId: string;
    readonly status: PaymentStatus;
    readonly lifecycle: PaymentLifecycle;
    readonly totalAmount: number;
    readonly balanceAmount: number;
    readonly lastTransactionKey: string | null;
    readonly canceledAmount: number;
    readonly amountState: PaymentAmountState;
    readonly hasPendingCancellation: boolean;
    readonly hasAbortedCancellation: boolean;
    readonly isCancelable: boolean;
    readonly isPartiallyCancelable: boolean;
    readonly cancels: readonly PaymentCancelTransactionSnapshot[];
    readonly consistencyIssues: readonly PaymentStateConsistencyIssue[];
}

type SettledCancelable = (SettledCancelableBase & {
    readonly partialAllowed: true;
    readonly payment: SettledCancelableBase['payment'] & {
        readonly isPartialCancelable: true;
    };
}) | (SettledCancelableBase & {
    readonly partialAllowed: false;
    readonly payment: SettledCancelableBase['payment'] & {
        readonly isPartialCancelable: false;
    };
});

interface SettledRefundRequest {
    readonly reason: CancelReason;
    readonly refundAccount?: never;
    readonly taxFreeAmount?: number;
    readonly cancelRequestId?: CancelRequestId;
    /** 견적의 결제 통화가 자동 전송된다. */
    readonly currency?: never;
}

/**
 * 저장소 인터페이스 — 검증 플로우가 성립하기 위한 필수 주입 지점.
 *
 * - OrderStore: 금액 비교의 단일 진실 공급원. createOrder가 save를 호출하므로
 *   '저장을 잊는' 실수가 플로우 안에서 불가능해진다.
 * - BillingKeyStore: 토스에 빌링키 조회 API가 없다 — 저장 실패 = 복구 불가.
 */
interface StoredOrder {
    readonly orderId: OrderId;
    /** requestPayment 시점에 고정한 금액 — 단일 진실 공급원. */
    readonly amount: number;
    readonly currency: 'KRW' | 'USD' | 'JPY';
    readonly orderName: string;
    /** ISO 8601. */
    readonly createdAt: string;
}

interface StoreFailure {
    readonly source: 'library';
    readonly kind: 'store-failure';
    readonly operation: 'save' | 'find' | 'delete';
    readonly cause: unknown;
}

/**
 * 에러 모델 — 최상위 판별자 `source`: 'library'(API 미도달 보장) / 'toss'(서버 응답) / 'network'(전송).
 *
 * retryable 판정은 **코드 테이블**로만 한다 — HTTP status 판정 금지.
 * 근거: PROVIDER_ERROR는 400이지만 재시도 가능, REFUND_REJECTED는 400이지만 비재시도.
 */
interface TossApiFailure<Code extends string = string> {
    readonly source: 'toss';
    /** 토스 응답 {code, message} 원문 무손실 보존. */
    readonly code: Code;
    readonly message: string;
    /** 보존하되 판정에 쓰지 않는다. */
    readonly httpStatus: number;
    readonly category: ErrorCategory;
    /** ⚠ 코드 테이블 판정 — HTTP status 아님. */
    readonly retryable: boolean;
    /** x-tosspayments-trace-id */
    readonly traceId: string | null;
}

/** 취소 실행 네임스페이스 — TossServerClient.cancels 의 타입. */
interface TossCancels<E extends Env> {
    /**
     * 전액 환불. expectedAmount는 필수이며 **호출자 장부(자체 DB)의 기대 금액**이어야 한다 —
     * 서버 balanceAmount(= target.balanceAmount)를 되돌려 넣으면 검증이 항진식이 된다.
     * 불일치 시 API 호출 전 Err. refundableAmount는 항상 자동 전송(서버 낙관적 잠금).
     * 멱등키 미지정 시 실행 전에 UUID 생성·body와 함께 봉인 — 실패 시 retry 티켓으로 회수.
     * ⚠ 유니언 오버로드 없음 — kind 내로잉 없이는 호출 자체가 컴파일 에러.
     */
    cancelFully(target: SettledCancelable, request: {
        readonly reason: CancelReason;
        readonly expectedAmount: number;
        /** 가상계좌 아님 — 변수/스프레드 경유도 차단. */
        readonly refundAccount?: never;
        readonly taxFreeAmount?: number;
        readonly currency?: 'KRW' | 'USD' | 'JPY';
        /** 중국·동남아 비동기(Alipay 등) 결제 취소에만 필수 — 상점 발급 고유값(문서 ID 53 §5). */
        readonly cancelRequestId?: CancelRequestId;
    }, options?: CallOptions<E>): Promise<Result<CancelOutcome, CancelError>>;
    cancelFully(target: DepositedVaCancelable, request: {
        readonly reason: CancelReason;
        readonly expectedAmount: number;
        /** 입금 완료 가상계좌 — 필수. */
        readonly refundAccount: RefundAccount;
        readonly taxFreeAmount?: number;
        readonly currency?: 'KRW' | 'USD' | 'JPY';
        /** 중국·동남아 비동기(Alipay 등) 결제 취소에만 필수 — 상점 발급 고유값(문서 ID 53 §5). */
        readonly cancelRequestId?: CancelRequestId;
    }, options?: CallOptions<E>): Promise<Result<CancelOutcome, CancelError>>;
    cancelFully(target: AwaitingDepositCancelable, request: {
        readonly reason: CancelReason;
        readonly expectedAmount: number;
        /** 입금 전 — 환불할 금액이 없으므로 금지. */
        readonly refundAccount?: never;
        /** 중국·동남아 비동기(Alipay 등) 결제 취소에만 필수 — 상점 발급 고유값(문서 ID 53 §5). */
        readonly cancelRequestId?: CancelRequestId;
    }, options?: CallOptions<E>): Promise<Result<CancelOutcome, CancelError>>;
    /**
     * 부분 환불. AwaitingDepositCancelable 오버로드 없음 → 입금 전 부분취소는 컴파일 에러
     * (서버: NOT_ALLOWED_PARTIAL_REFUND_WAITING_DEPOSIT). 사전검증: amount ≤ balanceAmount.
     */
    cancelPartially(target: Extract<SettledCancelable, {
        readonly partialAllowed: true;
    }>, request: {
        readonly reason: CancelReason;
        readonly amount: number;
        readonly refundAccount?: never;
        readonly taxFreeAmount?: number;
        readonly currency?: 'KRW' | 'USD' | 'JPY';
        /** 중국·동남아 비동기(Alipay 등) 결제 취소에만 필수 — 상점 발급 고유값(문서 ID 53 §5). */
        readonly cancelRequestId?: CancelRequestId;
    }, options?: CallOptions<E>): Promise<Result<CancelOutcome, CancelError>>;
    cancelPartially(target: Extract<DepositedVaCancelable, {
        readonly partialAllowed: true;
    }>, request: {
        readonly reason: CancelReason;
        readonly amount: number;
        readonly refundAccount: RefundAccount;
        readonly taxFreeAmount?: number;
        readonly currency?: 'KRW' | 'USD' | 'JPY';
        /** 중국·동남아 비동기(Alipay 등) 결제 취소에만 필수 — 상점 발급 고유값(문서 ID 53 §5). */
        readonly cancelRequestId?: CancelRequestId;
    }, options?: CallOptions<E>): Promise<Result<CancelOutcome, CancelError>>;
    /** transport 실패 티켓 재실행 — 봉인된 동일 멱등키+body. 서버에 도달했었다면 멱등 재생, 아니면 재실행. */
    retry(ticket: CancelRetryTicket, options?: Pick<CallOptions<E>, 'signal'>): Promise<Result<CancelOutcome, CancelError>>;
    /** 영속 CancelRetryStore의 opaque ticketId로 프로세스 재시작 후 재실행. */
    retryById(ticketId: string, options?: Pick<CallOptions<E>, 'signal'>): Promise<Result<CancelOutcome, CancelError>>;
}

interface TossClientOptions {
    /** 기본 globalThis.fetch (Node 20+ 내장). 테스트에서는 모킹 주입 지점. */
    readonly fetch?: typeof fetch;
    /** 기본 https://api.tosspayments.com */
    readonly baseUrl?: string;
    /**
     * live 키로 공식 API 호스트 외 주소를 사용하는 위험한 탈출구.
     * 일반 운영에서는 절대 켜지 말 것.
     */
    readonly dangerouslyAllowCustomLiveBaseUrl?: true;
    /** 기본 30_000ms — AbortSignal.timeout과 호출자 signal을 결합해 적용한다(재시도 시 시도별 독립 적용). */
    readonly timeoutMs?: number;
    /** §3.2 아웃바운드 req/res 증거 기록 — 기본 꺼짐. 시도 1건 = AuditEntry 1건. */
    readonly audit?: AuditOptions;
    /** §3.4 자동 재시도 — 기본 꺼짐(미설정 시 1회 시도, 현행 동작과 동일). */
    readonly retry?: RetryOptions;
    /** §3.3 이벤트 버스 — 'api.call' 전용(논리 요청당 최종 1회). createTossEvents 산출물만 발행이 흐른다. */
    readonly events?: TossEvents;
    /** 취소 transport 실패 티켓을 프로세스 재시작 후에도 재실행하기 위한 영속 저장소. */
    readonly cancelRetries?: CancelRetryStore;
}

/**
 * at: ISO 8601 발화 시각.
 * 분배 조건부 — 구체 K에서는 `{type: K; at} & TossEventMap[K]`와 동일하고,
 * 무인자 별칭(TossEvent)은 type으로 내로잉되는 판별 유니언이 된다.
 */
type TossEvent<K extends TossEventName = TossEventName> = K extends TossEventName ? {
    readonly type: K;
    readonly at: string;
} & TossEventMap[K] : never;

interface TossEventMap {
    /**
     * 요청 라이프사이클 — started/succeeded/failed 3분할 대신 완료 1종(과설계 금지).
     * 논리 요청당 1회(최종 outcome). durationMs는 첫 시도 시작부터 최종 outcome 확정까지의
     * 총 경과(재시도 대기 포함) — 시도별 소요는 audit(§3.2)의 AuditEntry.durationMs로.
     */
    'api.call': {
        readonly method: string;
        readonly path: string;
        readonly outcome: 'ok' | 'toss-error' | 'transport';
        readonly httpStatus: number | null;
        readonly durationMs: number;
        readonly traceId: string | null;
        /** retry(§3.4) 결합 시 총 시도 수 — 미결합이면 1. */
        readonly attempts: number;
    };
    /**
     * store 검증 통과 후 Ok 확정 시점.
     * ⚠ payment에 secret 포함 가능(실측: BILLING 카드 결제도 non-null) — payload 통짜 로깅
     * 금지. 기록 용도는 audit(§3.2)으로(redaction 통과본만 기록된다).
     */
    'payment.confirmed': {
        readonly payment: ConfirmedPayment;
    };
    'payment.confirm-failed': {
        /** parse 단계 실패면 null. */
        readonly orderId: OrderId | null;
        readonly error: CallbackParseError | VerifyCheckoutError | ConfirmError;
    };
    'cancel.executed': {
        readonly outcome: CancelOutcome;
    };
    'cancel.failed': {
        readonly paymentKey: PaymentKey;
        readonly error: CancelError;
    };
    /** billingKey는 payload 원천 부재 — 봉인 원칙 유지(유출 원천 차단). */
    'billing.issued': {
        readonly customerKey: CustomerKey;
    };
    'billing.approved': {
        readonly payment: BillingPayment;
        readonly customerKey: CustomerKey;
    };
    'billing.approve-failed': {
        readonly customerKey: CustomerKey;
        readonly error: BillingApproveError;
    };
    'billing.revoked': {
        readonly customerKey: CustomerKey;
    };
    /** §3.1 depositSecrets 연동. */
    'deposit.secret-saved': {
        readonly orderId: OrderId;
    };
    'deposit.secret-save-failed': {
        readonly orderId: OrderId;
        readonly paymentKey: PaymentKey;
        readonly cause: unknown;
    };
    /** 요약만 — AcceptedWebhook 통짜 전달 대신 secret 제거·타입 순환 회피가 보장되는 최소 필드. */
    'webhook.accepted': {
        readonly trust: 'signature' | 'secret' | 'unverified';
        readonly eventType: string;
        readonly transmissionId: string;
    };
    'webhook.duplicate': {
        readonly transmissionId: string;
    };
    'webhook.rejected': {
        readonly rejection: WebhookRejection;
    };
}

/** 공개 표면은 구독 전용 — emit은 내부 인터페이스로만 흐른다(라이브러리만 발행). */
interface TossEvents {
    /**
     * 반환값 = 구독 해제. 핸들러 파라미터는 구체 K에서 `TossEvent<K>`와 동일한 교차 형태 —
     * 제네릭 K에서 분배 조건부(TossEvent)가 지연 평가되는 것을 피해 core 이미터와의
     * 구조적 호환을 유지한다.
     */
    on<K extends TossEventName>(type: K, handler: (event: {
        readonly type: K;
        readonly at: string;
    } & TossEventMap[K]) => void | Promise<void>): () => void;
}

interface TossPaymentsApiConfig<E extends Env> extends TossPaymentsBaseConfig<E> {
    /** 브랜드 키만 수용 — raw string 미수용 (§7-1 기각: Env phantom 소실·실패 시점 이원화). */
    readonly secretKey: ApiSecretKey<E>;
    /** billing 플로우 배선 — 미지정 시 반환 타입에 `billing` 부재. */
    readonly billingKeys?: BillingKeyStore;
    readonly billing?: {
        readonly capabilities?: BillingCapabilities;
    };
}

/**
 * createTossPayments 파사드 — 배선을 누락할 수 없는 조립층 (설계 §2, G2).
 *
 * **순수 조립층**이다: 기존 팩토리 4종(createTossClient/createConfirmFlow/
 * createBillingFlow/createWebhookVerifier)에 전량 위임하고 검증 로직 중복이 0이다.
 * 배선하지 않은 플로우는 반환 타입에 **프로퍼티 자체가 없어** 사용 시점에 컴파일
 * 에러가 난다 — "스토어 미제공 시 플로우 생성 불가"라는 기존 런타임 보장을 타입으로
 * 옮긴 것뿐, 새 동작이 없다.
 *
 * 확정 판정(§2):
 * - flat config + 오버로드 2종 — 중첩(keys/stores/options)은 조건부 타입 판정 경로를
 *   깊게 만들어 추론 취약성만 늘린다.
 * - 단일 키 = 파사드 1개 — 위젯 결제 + 빌링 병용 상점은 파사드 2개(gsk용/sk용)를
 *   만든다. 키 쌍 규칙이 파사드 경계와 일치해 "confirm은 위젯 client 우선" 같은
 *   새 암묵 규칙이 생기지 않는다.
 * - raw string 키 미수용(§7-1 기각) — Env phantom 소실·실패 시점 이원화.
 */
interface TossPaymentsBaseConfig<E extends Env> {
    /** confirm 플로우 배선 — 미지정 시 반환 타입에 `confirm` 부재. */
    readonly orders?: OrderStore;
    /**
     * G1 — 1회 배선으로 confirm측 자동 저장 + webhook측 getSecret 대조 양쪽 커버 (§3.1).
     * README의 수동 저장 한 줄(`db.deposits.save`)이 사라진다.
     */
    readonly depositSecrets?: DepositSecretStore;
    /**
     * §3.1 saveSecret 실패 통지 — payload에 secret 원문 미포함(로그 유출 방지).
     * 미지정 시 실패 1건당 console.warn 1회. 복구: `getPaymentByOrderId(orderId)` →
     * `Payment.secret` → `saveSecret` 재시도.
     */
    readonly onDepositSecretSaveFailed?: (info: {
        readonly orderId: OrderId;
        readonly paymentKey: PaymentKey;
        readonly cause: unknown;
    }) => void;
    /** webhook 배선 — 미지정 시 반환 타입에 `webhook` 부재. depositSecrets는 위 필드가 자동 배선. */
    readonly webhook?: {
        readonly dedupe: WebhookDedupeStore;
        readonly securityKeys?: readonly SecurityKey[];
        readonly allowedSourceIps?: readonly string[] | false;
        /** 서명 이벤트 전송 시각의 과거/미래 허용 폭. 기본 5분. */
        readonly transmissionTimeToleranceMs?: number | false;
        /** 테스트 또는 통제된 런타임의 시계 주입용. */
        readonly clock?: () => Date;
        /** true → 파사드 내부 client를 PaymentLookup으로 자동 결속 (§3.5 배선 1비트). */
        readonly autoRefetch?: true;
    };
    /**
     * 옵션 3종 — 기본 전부 꺼짐. events는 client·confirm·billing·webhook 4곳에 자동 배선된다.
     * 미주입 시 반환 kit의 `events`는 no-op 구독 표면(발행 지점 순회 0회)이다.
     */
    readonly events?: TossEvents;
    readonly audit?: AuditOptions;
    readonly retry?: RetryOptions;
    /** 취소 transport 실패 재시도 티켓의 영속 저장소. */
    readonly cancelRetries?: CancelRetryStore;
    /** fetch/baseUrl/timeoutMs — audit/retry/events는 파사드가 위 필드에서 병합 주입한다. */
    readonly client?: Pick<TossClientOptions, 'fetch' | 'baseUrl' | 'timeoutMs' | 'dangerouslyAllowCustomLiveBaseUrl'>;
    readonly confirm?: Pick<ConfirmFlowOptions, 'approvalWindowMs' | 'clock'>;
}

/**
 * 파사드 산출물 — 배선한 플로우만 프로퍼티가 존재한다.
 *
 * 기지 리스크(§2): 조건부 교차 타입의 에러 메시지는 "`billing` 프로퍼티가 없다"고만
 * 말하고 원인(billingKeys 미배선)을 직접 말하지 않는다 — 각 프로퍼티 TSDoc의
 * "이 프로퍼티가 없다면" 매핑과 README 에러↔원인 표를 참조하라.
 */
type TossPaymentsKit<E extends Env, K extends KeyKind, C> = {
    readonly client: TossServerClient<E, K>;
    /**
     * 항상 존재 — config.events 미주입 시 no-op 구독 표면(구독해도 아무 이벤트도 발화되지
     * 않는다 — 발행 지점 순회 0회). 이벤트를 받으려면 `createTossEvents()`를 config.events에
     * 주입하라.
     */
    readonly events: TossEvents;
} & (C extends {
    readonly orders: OrderStore;
} ? {
    /** confirm 플로우. **이 프로퍼티가 없다면** → config에 `orders`(OrderStore)가 빠진 것이다. */
    readonly confirm: ConfirmFlow<E>;
} : {}) & (C extends {
    readonly billingKeys: BillingKeyStore;
} ? {
    /**
     * 빌링 플로우. **이 프로퍼티가 없다면** → config에 `billingKeys`(BillingKeyStore)가
     * 빠졌거나, 위젯 시크릿 키 파사드다(빌링은 API 키 전용 — 키 쌍 규칙).
     */
    readonly billing: BillingFlow<E, CapabilitiesOf<C>>;
} : {}) & (C extends {
    readonly webhook: object;
} ? {
    /** 웹훅 verifier. **이 프로퍼티가 없다면** → config에 `webhook`({ dedupe })이 빠진 것이다. */
    readonly webhook: WebhookVerifier;
} : {});

interface TossPaymentsWidgetConfig<E extends Env> extends TossPaymentsBaseConfig<E> {
    readonly secretKey: WidgetSecretKey<E>;
