/**
 * 토스 웹훅 createdAt 3형식 관대 파서.
 *
 * 이벤트마다 형식이 다르다(문서):
 * 1. 구형 이벤트: `yyyy-MM-dd'T'HH:mm:ss.SSSSSS` — 마이크로초 6자리, 오프셋 없음
 * 2. DEPOSIT_CALLBACK/신형 이벤트: `yyyy-MM-dd'T'HH:mm:ss±hh:mm` — 오프셋 형식
 * 3. 밀리초 형식(`...ss.SSS`, 오프셋 유무 무관) — 관대 수용
 *
 * 오프셋이 없는 형식은 **KST(+09:00)로 해석**한다 — 비공식 유도: 토스 문서의
 * 오프셋 포함 예시가 전부 +09:00이고 무오프셋 형식과 같은 시스템에서 발신되므로,
 * JS 기본(로컬 타임존) 해석은 UTC 서버에서 9시간 어긋난다.
 * 초과 정밀도(마이크로초 이하)는 밀리초로 절단한다.
 */
declare function parseTossTimestamp(raw: string): Result<Date, {
    readonly kind: 'bad-timestamp';
    readonly raw: string;
}>;

/**
 * {@link Unverified.refetch}가 요구하는 최소 조회 능력 — 구조적 인터페이스.
 *
 * `@gj-kit/toss-payments/server`의 `TossServerClient`가 그대로 구조 호환된다.
 * webhook 엔트리는 Edge 등에서 서버 클라이언트 없이 단독 사용 가능해야 하므로
 * server 모듈을 import하지 않고 여기서 구조적으로 정의한다.
 */
interface PaymentLookup {
    getPayment(key: PaymentKey, options?: {
        readonly signal?: AbortSignal;
    }): Promise<Result<Payment, LookupError>>;
    getPaymentByOrderId(orderId: OrderId, options?: {
        readonly signal?: AbortSignal;
    }): Promise<Result<Payment, LookupError>>;
}

/**
 * 웹훅 이벤트 타입 + 신뢰 3등급 + 전방 호환 UNKNOWN 래퍼.
 *
 * '검증됨' 단일 타입은 의도적으로 없다 — 토스가 전 이벤트에 서명을 제공하지 않는다:
 * 서명(HMAC)은 payout.changed/seller.changed에만, secret 대조는 DEPOSIT_CALLBACK에만
 * 존재하고 나머지는 암호학적 진위 검증 수단이 없다.
 * 출처: docs/research/toss-payments-v2.md "웹훅과 보안".
 */
interface PaymentStatusChangedEvent {
    readonly envelope: 'legacy';
    readonly eventType: 'PAYMENT_STATUS_CHANGED';
    /** 마이크로초 6자리 무오프셋 형식(yyyy-MM-dd'T'HH:mm:ss.SSSSSS) — {@link import('./envelope').parseTossTimestamp} 권장. */
    readonly createdAt: string;
    /**
     * core Payment 재사용(웹훅 전용 타입의 이중 관리 회피) + 종결 status 협착 —
     * 문서: EXPIRED/DONE/ABORTED/CANCELED/PARTIAL_CANCELED로의 전이 시에만 발송된다.
     */
    readonly data: Payment & {
        readonly status: 'DONE' | 'CANCELED' | 'PARTIAL_CANCELED' | 'ABORTED' | 'EXPIRED';
    };
}

/** 지급대행 상태 통지 — v1 범위 밖이라 entityBody는 원문(unknown) 전달, 서명 검증만 제공. */
interface PayoutChangedEvent {
    readonly envelope: 'v2';
    readonly eventType: 'payout.changed';
    readonly createdAt: string;
    readonly eventId: string;
    readonly entityType: 'payout';
    readonly entityBody: unknown;
}

/** DEPOSIT_CALLBACK — 승인 시 저장해 둔 Payment.secret 대조 통과. */
interface SecretVerified {
    readonly trust: 'secret';
    readonly event: DepositCallbackEvent;
    readonly meta: WebhookMeta;
}

interface SellerChangedEvent {
    readonly envelope: 'v2';
    readonly eventType: 'seller.changed';
    readonly createdAt: string;
    readonly eventId: string;
    readonly entityType: 'seller';
    readonly entityBody: unknown;
}

/** payout.changed / seller.changed — HMAC-SHA256 서명 검증 통과. */
interface SignatureVerified {
    readonly trust: 'signature';
    readonly event: SignedWebhookEvent;
    readonly meta: WebhookMeta;
}

/** 전방 호환 래퍼 — 새 이벤트·알 수 없는 구조가 와도 verify는 깨지지 않는다. */
interface UnknownWebhookEvent {
    readonly envelope: 'legacy' | 'v2' | 'flat';
    readonly eventType: 'UNKNOWN';
    /** 원문의 eventType 문자열 — 구조상 존재하지 않았으면 빈 문자열. */
    readonly rawEventType: string;
    readonly createdAt: string | null;
    readonly raw: unknown;
}

/** 나머지 전부 — 이름부터 신뢰 금지. payload를 직접 믿지 말고 refetch로 승격하라. */
interface Unverified {
    readonly trust: 'unverified';
    readonly event: UnverifiedWebhookEvent;
    readonly meta: WebhookMeta;
    /** 조회 API 재확인 — Unverified를 신뢰 가능한 Payment로 승격하는 유일한 경로(한 줄, 단언 없음). */
    refetch(client: PaymentLookup): Promise<Result<Payment, LookupError | NoPaymentReference>>;
    /**
     * §3.5 autoRefetch 설정 + 어댑터(fetchHandler/nodeHandler) 경유 시에만 채워짐 —
     * undefined = 옵션 꺼짐 또는 수동 verify 경로. Err여도 이벤트는 핸들러에 도달하며,
     * 핸들러가 실패를 던지면 어댑터는 claim을 해제하고 5xx로 재전송을 유도한다.
     *
     * ⚠ trust는 여전히 'unverified'다 — 조회 성공은 웹훅 발신자 진위를 증명하지 않는다
     * (위조 웹훅이 실존 orderId를 찍으면 조회는 성공한다, §7-2). payload가 아닌 이 조회
     * 결과로 상태를 갱신하라. prefetched 실패 시 payload 폴백은 금물.
     */
    readonly prefetched?: Result<Payment, LookupError | NoPaymentReference>;
}

/**
 * claim은 원자적이어야 한다 — 조회 후 생성하는 2단계 구현은 TOCTOU 레이스라 금지.
 * PROCESSING에는 crash-recovery lease를, COMPLETED에는 토스의 최장 재전송 기간보다 긴
 * TTL(권장 5일)을 적용한다.
 */
type WebhookClaimState = 'claimed' | 'processing' | 'completed';

interface WebhookDedupeStore {
    /** 원자적 상태 전이. processing 레코드는 lease 만료 후 재점유 가능해야 한다. */
    claim(dedupeKey: string): Promise<WebhookClaimState>;
    /** 비즈니스 핸들러가 내구적 처리를 완료한 후만 호출된다. */
    complete(dedupeKey: string): Promise<void>;
    /** 처리 실패 시 재전송이 다시 점유할 수 있게 한다. */
    release(dedupeKey: string): Promise<void>;
}

/**
 * 핸들러 키 = 구독 가능한 전체 이벤트.
 * `onBillingApproved`는 존재하지 않는다 — 토스가 빌링 승인 웹훅을 제공하지 않는다
 * (BILLING_DELETED만 존재). approve 반환값 + getPayment 재확인이 완결 신호다.
 */
interface WebhookHandlers {
    onDepositCallback?: (w: SecretVerified) => void | Promise<void>;
    onPaymentStatusChanged?: (w: Unverified & {
        event: PaymentStatusChangedEvent;
    }) => void | Promise<void>;
    /** 해외 간편결제 전용. */
    onCancelStatusChanged?: (w: Unverified & {
        event: CancelStatusChangedEvent;
    }) => void | Promise<void>;
    onBillingDeleted?: (w: Unverified & {
        event: BillingDeletedEvent;
    }) => void | Promise<void>;
    onMethodUpdated?: (w: Unverified & {
        event: MethodUpdatedEvent;
    }) => void | Promise<void>;
    onCustomerStatusChanged?: (w: Unverified & {
        event: CustomerStatusChangedEvent;
    }) => void | Promise<void>;
    onOrderPaymentStatusChanged?: (w: Unverified & {
        event: OrderPaymentStatusChangedEvent;
    }) => void | Promise<void>;
    onPayoutChanged?: (w: SignatureVerified & {
        event: PayoutChangedEvent;
    }) => void | Promise<void>;
    onSellerChanged?: (w: SignatureVerified & {
        event: SellerChangedEvent;
    }) => void | Promise<void>;
    onArsReservationChanged?: (w: Unverified & {
        event: ArsReservationChangedEvent;
    }) => void | Promise<void>;
    /** 전방 호환 — 새 이벤트가 와도 여기로 흐른다. */
    onUnknownEvent?: (w: Unverified & {
        event: UnknownWebhookEvent;
    }) => void | Promise<void>;
}

/** 모든 웹훅 공통 HTTP 헤더에서 추출한 메타데이터. */
interface WebhookMeta {
    /** tosspayments-webhook-transmission-id — 전송 시도 식별자. */
    readonly transmissionId: string;
    /** tosspayments-webhook-transmission-time — 서명 대상에 포함되는 전송 시각. */
    readonly transmissionTime: string;
    /** tosspayments-webhook-transmission-retried-count — 누락/비정상이면 0. */
    readonly retriedCount: number;
    /** 재전송 시도가 바뀌어도 같은 사업 이벤트를 찾는 안정 dedupe 키. */
    readonly dedupeKey: string;
}

type WebhookRejection = {
    readonly kind: 'invalid-signature';
    readonly signatureCount: number;
    readonly keysTried: number;
}
/** 위조 의심 — 저장된 secret과 불일치. */
 | {
    readonly kind: 'secret-mismatch';
    readonly orderId: string;
}
/** depositSecrets가 null 반환 — 승인 시 저장 누락. */
 | {
    readonly kind: 'unknown-order';
    readonly orderId: string;
} | {
    readonly kind: 'missing-config';
    readonly needed: 'securityKeys' | 'depositSecrets';
} | {
    readonly kind: 'untrusted-source-ip';
    readonly ip: string;
}
/** 서명·secret이 없는 이벤트에서 출처 IP 미제공 — 기본 fail-closed. */
 | {
    readonly kind: 'missing-source-ip';
} | {
    readonly kind: 'invalid-transmission-time';
    readonly value: string;
} | {
    readonly kind: 'stale-transmission-time';
    readonly value: string;
}
/** 동일 이벤트가 아직 처리 중 — 어댑터는 503으로 재전송을 유도한다. */
 | {
    readonly kind: 'processing';
    readonly dedupeKey: string;
} | {
    readonly kind: 'parse-failed';
    readonly detail: string;
} | {
    readonly kind: 'store-failure';
    readonly cause: unknown;
};

/** duplicate는 Err가 아닌 정상 verdict — 200 ack 후 스킵 (400 반환 시 3일 19시간 재전송 폭탄). */
type WebhookVerdict = {
    readonly duplicate: false;
    readonly webhook: AcceptedWebhook;
} | {
    readonly duplicate: true;
    readonly transmissionId: string;
};

interface WebhookVerifier {
    /**
     * raw body 강제 — 파싱된 객체를 받는 오버로드는 없다(서명 검증 원천 보장).
     * 순서: 헤더 추출 → 봉투 판별 → 진위 검증(일반 이벤트는 sourceIp 필수) →
     * dedupe.claim(진위 통과 후에만) → verdict.
     */
    verify(rawBody: string | Uint8Array, headers: IncomingHeaders, context?: {
        readonly sourceIp?: string;
    }): Promise<Result<WebhookVerdict, WebhookRejection>>;
    /** 수동 verify 경로의 비즈니스 처리 완료 표시. 어댑터는 자동 호출한다. */
    complete(webhook: AcceptedWebhook): Promise<void>;
    /** 수동 verify 경로의 처리 실패 보상. 어댑터는 자동 호출한다. */
    release(webhook: AcceptedWebhook): Promise<void>;
    /**
     * Fetch 표준 어댑터(Next.js Route Handler / Hono) — raw body 추출·검증·dedupe와
     * 처리 완료/실패 claim 전이를 소유한다. 핸들러 완료 후에만 200을 반환하며,
     * options.maxBodyBytes를 넘는 수신 body는 검증 전에 413으로 거부한다.
     */
    fetchHandler(handlers: WebhookHandlers, options?: FetchHandlerOptions): (request: Request) => Promise<Response>;
    /**
     * Express/Node — 모든 content-type을 받는 `express.raw()` 뒤에 장착(JSON 파싱 미들웨어 금지).
     * options.maxBodyBytes를 넘는 수신 body는 검증 전에 413으로 거부한다.
     */
    nodeHandler(handlers: WebhookHandlers, options?: NodeHandlerOptions): (req: NodeIncomingMessageLike, res: NodeServerResponseLike) => Promise<void>;
}

interface WebhookVerifierConfig {
    /** 필수 — 재전송 최대 7회 + 가상계좌 이중 이벤트(PAYMENT_STATUS_CHANGED+DEPOSIT_CALLBACK 동시 구독). */
    readonly dedupe: WebhookDedupeStore;
    /** 키 로테이션(재발급 병행 기간) 대비 배열 — 서명×키 조합 중 1개 일치 시 통과. */
    readonly securityKeys?: readonly SecurityKey[];
    /** 미주입 상태서 DEPOSIT_CALLBACK 수신 → Err missing-config. */
    readonly depositSecrets?: DepositSecretSource;
    /**
     * 기본: 문서 IP 목록({@link TOSS_WEBHOOK_SOURCE_IPS}) 내장. `false` = 끔.
     * 서명·secret이 없는 이벤트는 sourceIp가 없으면 거부한다(fail-closed).
     * 프록시/로드밸런서 뒤에서는 검증된 ingress가 복원한 주소만 전달해야 한다.
     * Unverified 이벤트의 보조 방어선일 뿐 암호학적 검증을 대체하지 않는다.
     *
     * IPv4-mapped IPv6(`::ffff:x.x.x.x`)는 비교 전에 순수 IPv4 표기로 정규화한다 —
     * Node dual-stack 리스너의 `req.socket.remoteAddress`가 이 형태이기 때문(목록 항목
     * 쪽도 동일 정규화). 항목은 순수 IPv4 표기 권장.
     */
    readonly allowedSourceIps?: readonly string[] | false;
    /** 서명 전송 시각의 과거/미래 허용 폭. 기본 5분, false는 비권장 비활성화. */
    readonly transmissionTimeToleranceMs?: number | false;
    /** 테스트와 시계 주입용. */
    readonly clock?: () => Date;
    /**
     * §3.3 이벤트 버스 — webhook.accepted/duplicate/rejected 발행 지점(요약 필드만 —
     * DEPOSIT_CALLBACK rawBody의 secret은 어떤 이벤트 payload에도 실리지 않는다).
     * createTossEvents 산출물만 발행이 흐른다(구조적 모조 객체는 no-op).
     */
    readonly events?: TossEvents;
    /**
     * §3.5 — 설정 시 fetchHandler/nodeHandler의 핸들러 디스패치 직전에
     * 결제 참조가 있는 Unverified 이벤트를 자동 재조회해 `prefetched`로 첨부한다.
     * dedupe 통과분에만 수행(재전송 7회가 조회 7회가 되지 않음).
     * 어댑터는 prefetch와 핸들러가 성공하고 claim을 COMPLETED로 바꾼 뒤에만 200을 반환한다.
     * 빠른 응답이 필요하면 핸들러가 내구적 큐에 적재하는 지점까지 책임져야 한다.
     * 수동 verify() 경로에는 네트워크 호출을 넣지 않으며 trust 등급도 승격하지 않는다.
     */
    readonly autoRefetch?: {
        /** 기존 PaymentLookup 구조적 인터페이스 재사용 — webhook→server 런타임 의존 없음. */
        readonly client: PaymentLookup;
        /** 생략 시 결제 참조 보유 이벤트 전부. 분당 100건 쿼터 방어용 필터. */
        readonly eventTypes?: readonly ('PAYMENT_STATUS_CHANGED' | 'CANCEL_STATUS_CHANGED' | 'ORDER_PAYMENT_STATUS_CHANGED')[];
    };
}

/**
 * 이름별 kit 바인딩 토큰을 만든다. `Symbol.for`를 써 ESM/CJS 이중 로드에서도 같은
 * 이름은 같은 토큰으로 해석된다. 같은 Nest application에서 같은 이름을 두 번
 * register하면 provider 토큰이 충돌하므로 이름을 유일하게 유지해야 한다.
 */
declare function getTossPaymentsToken(name: TossPaymentsKitName): symbol;

symbols.sourceDocumentation:
파사드 kit 주입 데코레이터.

주입 파라미터의 타입은 소실되지 않도록 {@link TossPaymentsFor} 별칭(설계 §4.3 —
`defineTossPaymentsConfig` + `typeof config`)으로 선언하라 — 미배선 플로우 접근이
주입부에서도 컴파일 에러가 된다.

```ts
constructor(@InjectTossPayments() private readonly toss: AppToss) {}

// 여러 키 쌍을 쓸 때는 register({ name })와 같은 이름을 명시한다.
constructor(@InjectTossPayments('billing') private readonly toss: BillingToss) {}
```

symbols.declaration:
/**
 * 컨트롤러 사용 (설계 §4.4):
 * ```ts
 * @Post('webhooks/toss')
 * async handle(@Req() req: RawBodyRequest<Request>, @Res() res: Response) {
 *   await toNestWebhookHandler(verifier, handlers)(req, res);
 * }
 * ```
 *
 * 위임 구조: rawBody 확보만 이 헬퍼가 소유하고, 검증·dedupe·200 ack·autoRefetch
 * prefetch·핸들러 디스패치는 전부 코어 `verifier.nodeHandler`에 위임한다 — 로직 중복 0.
 */
declare function toNestWebhookHandler(verifier: WebhookVerifier, handlers: WebhookHandlers, options?: NestWebhookHandlerOptions): (req: NestWebhookRequest, res: NodeServerResponseLike) => Promise<void>;

/**
 * 앱이 조건부 파사드 타입을 보존하는 별칭 헬퍼 (설계 §4.3) — forRootAsync는 런타임
 * 토큰 주입이라 kit 타입이 소실되므로, `defineTossPaymentsConfig`로 고정한 config의
 * `typeof`에서 kit 타입을 복원한다. 배선 누락 플로우 접근은 주입부에서도 컴파일 에러.
 *
 * ```ts
 * export const tossConfig = defineTossPaymentsConfig({ ... });
 * export type AppToss = TossPaymentsFor<typeof tossConfig>;
 * ```
 */
type TossPaymentsFor<C extends AnyTossPaymentsConfig> = C extends TossPaymentsApiConfig<infer E> ? TossPaymentsKit<E, 'api', C> : C extends TossPaymentsWidgetConfig<infer E> ? TossPaymentsKit<E, 'widget', C> : never;

/**
 * Named kit 식별자. 서로 다른 키 쌍(API `sk`, 결제위젯 `gsk` 등)은 반드시 다른 이름으로
 * 등록한다. 이름은 Nest application 안에서 유일해야 한다.
 */
type TossPaymentsKitName = string;

declare class TossPaymentsModule {
    /**
     * 동기 조립 — `{ provide: TOSS_PAYMENTS, useValue: createTossPayments(config) }`.
     * config는 코어 `defineTossPaymentsConfig` 산출물을 권장(간접 전달 시 타입 보존).
     */
    static forRoot<E extends Env, const C extends AnyTossPaymentsConfig>(config: C, options?: TossPaymentsModuleOptions): DynamicModule;
    /** 비동기 조립 — 스토어를 Nest 프로바이더(inject)로 받아 useFactory에서 config를 만든다. */
    static forRootAsync<C extends AnyTossPaymentsConfig>(options: TossPaymentsModuleAsyncOptions<C>): DynamicModule;
    /**
     * 이름 있는 동기 조립. `forRoot`는 기존 단일 kit(`TOSS_PAYMENTS`) 호환 API로
     * 유지하고, 여러 키 쌍은 이 메서드로 분리한다.
     */
    static register<const C extends AnyTossPaymentsConfig>(options: TossPaymentsModuleRegisterOptions<C>): DynamicModule;
    /** 이름 있는 비동기 조립. provider별 config/store를 독립적으로 주입한다. */
    static registerAsync<C extends AnyTossPaymentsConfig>(options: TossPaymentsModuleRegisterAsyncOptions<C>): DynamicModule;
}

/** forRootAsync 옵션 (설계 §4.2) — 스토어(PrismaService 등)를 DI 의존성으로 조립하는 경로. */
interface TossPaymentsModuleAsyncOptions<C extends AnyTossPaymentsConfig> {
    readonly imports?: DynamicModule['imports'];
    /** useFactory 파라미터로 주입할 프로바이더 토큰. 예: [PrismaService, ConfigService] */
    readonly inject?: readonly InjectionToken[];
    /**
     * config 팩토리. **반환값은 반드시 `defineTossPaymentsConfig(...)`로 감싸라**(설계 §4.3 강권) —
     * 팩토리 반환 경로에서는 const 추론이 풀려 조건부 프로퍼티(배선) 판정이 무너질 수 있다.
     */
    readonly useFactory: (...deps: readonly any[]) => C | Promise<C>;
    /** 기본 true — 결제 kit은 전역 싱글턴이 자연스러운 단위다(모듈마다 재조립 금지). */
    readonly global?: boolean;
}

/** `forRoot`/`register`에서 공유하는 Nest module 옵션. */
interface TossPaymentsModuleOptions {
    /** 기본 true. 모듈 경계를 엄격히 유지하려면 false를 명시한다. */
    readonly global?: boolean;
}

/** 이름 있는 kit의 비동기 조립 옵션. */
interface TossPaymentsModuleRegisterAsyncOptions<C extends AnyTossPaymentsConfig> extends TossPaymentsModuleAsyncOptions<C> {
    readonly name: TossPaymentsKitName;
}

/**
 * 이름 있는 kit의 동기 조립 옵션.
 *
 * API `sk`와 결제위젯 `gsk`처럼 서로 다른 키 쌍을 동시에 써야 할 때 사용한다.
 * `name`은 한 Nest application에서 유일해야 하며, 주입부의
