 * 앱이 소유하는 비동기 민감값 보호기.
 *
 * AES-GCM, envelope encryption, KMS 등을 선택할 수 있도록 crypto 의존성을 이 패키지에
 * 들이지 않는다. `encrypt`는 평문과 다른, DB에 안전하게 저장 가능한 문자열을 반환해야
 * 하고 `decrypt`는 같은 context에서만 원문을 복원해야 한다. 구현은 암호화 실패 메시지에
 * 평문을 포함하지 않아야 한다.
 *
 * 이 패키지의 스토어가 넘기는 평문은 항상 well-formed UTF-16이다(JSON.stringify 출력 또는
 * ASCII secret). 구현은 비페어 서로게이트를 조용히 바꿔 봉하지 말고 거부해야 한다 — 레퍼런스
 * AES-256-GCM 보호기는 `TypeError`로 거부한다.
 */
interface SensitiveValueProtector {
    encrypt(plaintext: string, context: SensitiveValueContext): Promise<string>;
    decrypt(ciphertext: string, context: SensitiveValueContext): Promise<string>;
}

interface TossPaymentsPostgres {
    readonly orders: OrderStore;
    readonly depositSecrets: DepositSecretStore;
    /**
     * 코어 BillingKeyStore + PostgreSQL conditional compare-and-mutate 확장.
     *
     * `deleteIfBillingKeyMatches`/`replaceIfBillingKeyMatches`는 stale BILLING_DELETED와
     * projection 보상 경합에서 무조건 delete/save 대신 사용하는 원자적 API다.
     */
    readonly billingKeys: PgBillingKeyStore;
    readonly cancelRetries: CancelRetryStore;
    readonly webhookDedupe: WebhookDedupeStore;
    readonly audit: AuditSink & {
        flush(): Promise<void>;
    };
    readonly inbox: WebhookInboxStore;
    /**
     * 앱이 만든 nonsecret HMAC/blind-index key로 짧은 host lifecycle을 인스턴스 간
     * 순서화하는 PostgreSQL advisory transaction lock facility.
     *
     * 이 API는 다른 ORM connection의 transaction과 2PC 원자성을 만들지 않는다. provider
     * network I/O가 아니라 local durable finalization만 callback에 넣어야 한다.
     */
    readonly opaqueLocks: PgOpaqueAdvisoryLocks;
    /** 명시 호출 전용 — 부팅 시 자동 실행 없음. `app.listen` 전에 await하는 것이 골든 패스. */
    migrate(): Promise<MigrationResult>;
    /**
     * TTL 행 정리 — 명시 호출 전용(자동 타이머 없음). audit_entries·webhook_inbox·
     * orders·deposit_secrets는 지우지 않는다 — 보관 정책은 소비자 책임.
     */
    cleanup(): Promise<CleanupResult>;
}

declare class TossPaymentsPostgresModule {
    /** 동기 조립 — `{ provide: TOSS_PAYMENTS_POSTGRES, useValue: createTossPaymentsPostgres(options) }`. */
    static forRoot(options: TossPaymentsPostgresModuleOptions): DynamicModule;
    /**
     * 비동기 조립 — 골든 패스는 코어 모듈과의 연쇄다:
     *
     * ```ts
     * TossPaymentsModule.forRootAsync({
     *   imports: [TossPaymentsPostgresModule.forRootAsync({ ... })],
     *   inject: [TOSS_PAYMENTS_POSTGRES],
     *   useFactory: (pg: TossPaymentsPostgres) =>
     *     defineTossPaymentsConfig({ secretKey, orders: pg.orders, ... }),
     * })
