}

type OpaqueAdvisoryLockKey = string & {
    readonly [opaqueAdvisoryLockKeyBrand]: 'OpaqueAdvisoryLockKey';
};

/**
 * BillingKeyStore PostgreSQL 구현 (설계 §3.3).
 *
 * 코어 계약의 핵심 불변식:
 * - 토스에 빌링키 조회 API가 없다 — **저장 실패 = 복구 불가**. 이 테이블이 유일한
 *   보관 수단이므로 save는 드라이버 에러를 감추지 않고 그대로 던진다(코어가 감쌈).
 * - `save`는 upsert(customer_key)다 — issue/import 양쪽에서 호출되는 계약이고 코어가
 *   교체 정책을 규정하지 않으므로 최신 발급본을 유지한다.
 * - `billing_key`에는 BillingKeyRecord 전체의 보호된 JSON 문자열만 쓴다. `card`와
 *   `transfers`까지 함께 보호해 계좌번호 등 부수 메타데이터가 jsonb에 평문으로 남지
 *   않게 한다. method/issued_at은 운영 조회용 비밀이 아닌 최소 메타데이터로만 남긴다.
 * - ⚠ 보안 불변식(코어 stores.ts): 어떤 에러 메시지에도 billing_key 값을 싣지 않고,
 *   customerKey와 billingKey를 같은 문자열(로그 한 줄)에 함께 두지 않는다 — 토스의
 *   빌링 보안 모델이 이 쌍의 분리에 의존한다. 이 파일의 메시지는 둘 다 싣지 않는다.
 */
/**
 * `withMutationLock` callback에만 전달되는 customerKey-고정 mutation handle.
 *
 * 핸들은 lock을 잡은 customerKey 하나만 조작한다. callback 안에서 바깥
 * `pg.billingKeys`를 다시 호출하면 다른 커넥션이 같은 advisory lock을 기다려 deadlock이
 * 되므로, 모든 billing key 작업은 이 handle을 통해 수행해야 한다.
 */
interface PgBillingKeyMutation {
    readonly customerKey: BillingKeyRecord['customerKey'];
    find(): Promise<BillingKeyRecord | null>;
    save(record: BillingKeyRecord, options?: BillingKeySaveOptions): Promise<void>;
    /**
     * 현재 raw billing key와 일치할 때만 삭제한다. 무조건 삭제 API는 의도적으로 없다.
     */
    delete(expectedBillingKey: BillingKeyRecord['billingKey']): Promise<boolean>;
    replaceAndGetPrevious(record: BillingKeyRecord, options?: BillingKeySaveOptions): Promise<PgBillingKeySnapshot | null>;
    /**
     * 저장 당시의 nonsecret operationId fingerprint가 예상 operationId와 같은지 확인한다.
     * callback 내부에서만 쓰며 raw operationId/fingerprint 어느 것도 반환하지 않는다.
     */
    isCurrentOperationId(operationId: string): Promise<boolean>;
    deleteIfBillingKeyMatches(expectedBillingKey: BillingKeyRecord['billingKey']): Promise<boolean>;
    replaceIfBillingKeyMatches(expectedBillingKey: BillingKeyRecord['billingKey'], replacement: BillingKeyRecord | PgBillingKeySnapshot | null): Promise<boolean>;
}

/**
 * Opaque previous snapshot returned by `replaceAndGetPrevious`.
 *
 * Only `record` is readable, for recovery or display. Passing the original snapshot object
 * back to `replaceIfBillingKeyMatches` also restores the nonsecret operation fingerprint.
 * The fingerprint and the trusted record are linked only through a module-private
 * `WeakMap`, so JSON copies, spreads, manual reconstructions, or inheriting objects have no
 * registry identity and the lifecycle fence is intentionally false after such a restore.
 */
interface PgBillingKeySnapshot {
    readonly record: BillingKeyRecord;
}

/**
 * lifecycle work를 short-lived PostgreSQL advisory transaction lock 아래 실행하는 표면.
 *
 * callback에 SQL session을 전달하지 않는다. 이 API의 목적은 host DB transaction/worker
 * lifecycle의 **순서화**이며, 다른 ORM connection의 transaction과 2PC 원자성을 만들지
 * 않는다. callback은 local durable work만 수행하고 provider/HTTP 같은 긴 network I/O는
 * 넣지 않아야 한다. callback 안에서 같은 key로 이 facility를 재진입하면 다른 connection이
 * 바깥 transaction의 xact lock을 기다려 self-deadlock하므로, 연관 작업은 한 callback에 둔다.
 */
interface PgOpaqueAdvisoryLocks {
    withLock<T>(key: OpaqueAdvisoryLockKey, operation: () => T | Promise<T>): Promise<T>;
}

/**
 * 보호기 호출마다 전달되는 AAD 결속 정보.
